    private static int RunRouteSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "route-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        DataKernelOptions options = new(
            AppendBufferSize: 16 * 1024,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata developerMetadata = new(
            DevIdentity: "RouteSanity",
            DevCustomText: "routing sanity",
            DevGuid: Guid.Parse("7786ef8e-50f0-475b-b72d-f9ded770f7d8"),
            DevDate1UtcTicks: 101,
            DevDate2UtcTicks: 202,
            DevNumber: 303);

        RouterRouteSnapshot[] childRoutes =
        [
            new RouterRouteSnapshot(0x00, 0x3F, 0x0010_0000),
            new RouterRouteSnapshot(0x40, 0x7F, 0x0020_0000),
            new RouterRouteSnapshot(0x80, 0xFF, 0x0030_0000)
        ];

        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, developerMetadata, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "routing", 0);
            (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
            (RouterSnapshot child, DataKernelCommitTelemetry childCommit) = session.CreateCompressedRouter(1, 1, 16, 1, childRoutes);
            DataKernelCommitTelemetry routeCommit = session.UpdateRouterRoute(root.Offset, 0x41, 0x41, 0x41, child.Offset);

            PrintCommit("route root create", rootCommit);
            PrintCommit("route child create", childCommit);
            PrintCommit("route link update", routeCommit);

            ValidateRoutingVectors(session, root.Offset, child.Offset);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slot = reopened.IndexDirectory.ActiveSlots[0];
            long rootOffset = slot.RootRouterOffset;
            long childOffset = reopened.FindRouterTarget(rootOffset, 0x41);
            ValidateRoutingVectors(reopened, rootOffset, childOffset);
        }

        Console.WriteLine($"route-sanity ok path={path}");
        return 0;
    }


    private static int RunScalar8Scalar8Sanity(string[] args)
    {
        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Create(GetIntOption(args, "--shelf-size", Scalar8Scalar8Profile.Default32KiB.ShelfExtentSize));
        byte[] bytes = new byte[profile.ShelfExtentSize];
        Scalar8Scalar8 shelf = new(bytes, profile);
        shelf.Initialize();
        Scalar8Scalar8ReadOnly readOnly = shelf.AsReadOnly();
        if (!readOnly.IsValid || readOnly.ItemCount != 0)
        {
            throw new InvalidDataException("SS8-8 initialized shelf is invalid.");
        }

        ValidateScalar8Scalar8InsertOrder(profile, [3, 1, 2, 2], [30, 10, 20, 19]);
        ValidateScalar8Scalar8InsertOrder(profile, [9, 8, 7, 6, 5, 4, 3, 2, 1], [90, 80, 70, 60, 50, 40, 30, 20, 10]);
        ValidateScalar8Scalar8RandomInsertOrder(profile);
        ValidateScalar8Scalar8DuplicateBehavior(profile);
        ValidateScalar8Scalar8FullBoundary(profile);
        Console.WriteLine($"ss8-8-sanity ok size={profile.ShelfExtentSize} maxItems={profile.MaxItemCount} unusedTail={profile.UnusedTailBytes}");
        return 0;
    }


    /// <summary>
    /// Validates the first primitive `SS16-8` shelf shape without routed or public wrapper integration.<br/>
    /// The scenario checks 16-byte key ordering, duplicate behavior, key-conflict behavior, range copy, and the full-shelf boundary at the requested shelf size.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the primitive `SS16-8` shelf validates.</returns>
    private static int RunScalar16Scalar8Sanity(string[] args)
    {
        Scalar16Scalar8Profile profile = Scalar16Scalar8Profile.Create(GetIntOption(args, "--shelf-size", Scalar16Scalar8Profile.Default32KiB.ShelfExtentSize));
        byte[] bytes = new byte[profile.ShelfExtentSize];
        Scalar16Scalar8 shelf = new(bytes, profile);
        shelf.Initialize();
        Scalar16Scalar8ReadOnly readOnly = shelf.AsReadOnly();
        if (!readOnly.IsValid || readOnly.ItemCount != 0)
        {
            throw new InvalidDataException("SS16-8 initialized shelf is invalid.");
        }

        ValidateScalar16Scalar8InsertOrder(
            profile,
            [0, 0, 1, 0, 1],
            [3, 1, 0, 2, 1],
            [30, 10, 100, 20, 101]);
        ValidateScalar16Scalar8InsertOrder(
            profile,
            [2, 1, 1, 0, 0],
            [0, 9, 8, 2, 1],
            [200, 190, 180, 20, 10]);
        ValidateScalar16Scalar8RandomInsertOrder(profile);
        ValidateScalar16Scalar8DuplicateBehavior(profile);
        ValidateScalar16Scalar8RangeCopy(profile);
        ValidateScalar16Scalar8FullBoundary(profile);
        Console.WriteLine($"ss16-8-sanity ok size={profile.ShelfExtentSize} maxItems={profile.MaxItemCount} unusedTail={profile.UnusedTailBytes}");
        return 0;
    }


