            Fixed32Scalar8ReadOnly readOnly = new(readBack, profile);
            ValidateFixed32Scalar8Sorted(readOnly);
            ValidateFixed32Scalar8ReadbackWindow(readOnly);
            PrintRead("fs32-8 read", kernel.GetAndResetReadTelemetry());

            RawDataReservation rewrite = kernel.ReserveAt(reservation.Extent.Offset, profile.ShelfExtentSize);
            readBack.CopyTo(rewrite.Span);
            Fixed32Scalar8 rewrittenShelf = new(rewrite.Span, profile);
            CreateFixed32Scalar8Key(999, out ulong key0, out ulong key1, out ulong key2, out ulong key3);
            Fixed32Scalar8InsertResult insertResult = rewrittenShelf.Insert(
                key0,
                key1,
                key2,
                key3,
                Fixed32Scalar8Layout.EncodeUnsignedScalar8(999_999),
                allowDuplicateKeys: true);
            if (insertResult != Fixed32Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected FS32-8 fixed-offset rewrite insert, got {insertResult}.");
            }

            DataKernelCommitTelemetry rewriteCommit = kernel.Commit();
            ValidateFixed32Scalar8CommitShape("fs32-8 rewrite", backing, rewriteCommit, profile);

            byte[] rewrittenReadBack = new byte[profile.ShelfExtentSize];
            kernel.Read(reservation.Extent.Offset, rewrittenReadBack);
            Fixed32Scalar8ReadOnly rewrittenReadOnly = new(rewrittenReadBack, profile);
            ValidateFixed32Scalar8Sorted(rewrittenReadOnly);
            if (!rewrittenReadOnly.Contains(key0, key1, key2, key3, Fixed32Scalar8Layout.EncodeUnsignedScalar8(999_999)))
            {
                throw new InvalidDataException("FS32-8 fixed-offset rewrite did not persist inserted tuple.");
            }

            ValidateFixed32Scalar8ReadbackWindow(rewrittenReadOnly);
            PrintRead("fs32-8 rewrite read", kernel.GetAndResetReadTelemetry());
            Console.WriteLine(backing == DataKernelBackingKind.File
                ? $"fs32-8-dk-sanity ok backing=file path={path} offset={reservation.Extent.Offset}"
                : $"fs32-8-dk-sanity ok backing=memory offset={reservation.Extent.Offset}");
        }

        return 0;
    }


