    /// This keeps the widened-key and widened-identity shape below routing while proving the persisted shelf extent behaves like a fixed-size storage unit.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the `SS16-16` shelf roundtrip and fixed-offset rewrite validate.</returns>
    private static int RunScalar16Scalar16DataKernelSanity(string[] args)
    {
        DataKernelBackingKind backing = GetBackingOption(args);
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss16-16-dk-sanity.lbdx"));
        if (backing == DataKernelBackingKind.File)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.Delete(path);
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: DefaultReservedPrefixBytes,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        Scalar16Scalar16Profile profile = Scalar16Scalar16Profile.Create(GetIntOption(args, "--shelf-size", Scalar16Scalar16Profile.Default32KiB.ShelfExtentSize));
        using (DataKernel kernel = OpenKernel(backing, path, FileMode.Create, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            RawDataReservation reservation = kernel.Reserve(profile.ShelfExtentSize);
            Scalar16Scalar16 shelf = new(reservation.Span, profile);
            shelf.Initialize();
            PopulateScalar16Scalar16Shelf(ref shelf, 256);

            DataKernelCommitTelemetry createCommit = kernel.Commit();
            ValidateScalar16Scalar16CommitShape("ss16-16 create", backing, createCommit, profile);

            byte[] readBack = new byte[profile.ShelfExtentSize];
            kernel.Read(reservation.Extent.Offset, readBack);
            Scalar16Scalar16ReadOnly readOnly = new(readBack, profile);
            ValidateScalar16Scalar16Sorted(readOnly);
            ValidateScalar16Scalar16ReadbackWindow(readOnly);
            PrintRead("ss16-16 read", kernel.GetAndResetReadTelemetry());

            RawDataReservation rewrite = kernel.ReserveAt(reservation.Extent.Offset, profile.ShelfExtentSize);
            readBack.CopyTo(rewrite.Span);
            Scalar16Scalar16 rewrittenShelf = new(rewrite.Span, profile);
            Scalar16Scalar16InsertResult insertResult = rewrittenShelf.Insert(
                encodedKeyHigh: 1,
                encodedKeyLow: 128,
                encodedIdentityHigh: 1,
                encodedIdentityLow: 999_999,
                allowDuplicateKeys: true);
            if (insertResult != Scalar16Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS16-16 fixed-offset rewrite insert, got {insertResult}.");
            }

            DataKernelCommitTelemetry rewriteCommit = kernel.Commit();
            ValidateScalar16Scalar16CommitShape("ss16-16 rewrite", backing, rewriteCommit, profile);

            byte[] rewrittenReadBack = new byte[profile.ShelfExtentSize];
            kernel.Read(reservation.Extent.Offset, rewrittenReadBack);
            Scalar16Scalar16ReadOnly rewrittenReadOnly = new(rewrittenReadBack, profile);
            ValidateScalar16Scalar16Sorted(rewrittenReadOnly);
            if (!rewrittenReadOnly.Contains(1, 128, 1, 999_999))
            {
                throw new InvalidDataException("SS16-16 fixed-offset rewrite did not persist inserted tuple.");
            }

            ValidateScalar16Scalar16ReadbackWindow(rewrittenReadOnly);
            PrintRead("ss16-16 rewrite read", kernel.GetAndResetReadTelemetry());
            Console.WriteLine(backing == DataKernelBackingKind.File
                ? $"ss16-16-dk-sanity ok backing=file path={path} offset={reservation.Extent.Offset}"
                : $"ss16-16-dk-sanity ok backing=memory offset={reservation.Extent.Offset}");
        }

        return 0;
    }


