    /// <summary>
    /// Validates the first routed `SS8-8` no-split insert mutation path.<br/>
    /// The command creates one routed shelf, inserts one new tuple through the route, and verifies that only the shelf extent is rewritten.<br/>
    /// It intentionally avoids split handling so the no-split dirty/write contract is proven before structural split behavior is added.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the routed no-split insert validation succeeds; otherwise one.</returns>
    private static int RunScalar8Scalar8RouteInsertSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-route-insert-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--item-count", 512);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        if (itemCount <= 0 || itemCount + 1 > profile.MaxItemCount)
        {
            Console.Error.WriteLine($"ss8-8-route-insert-sanity item count must be between 1 and {profile.MaxItemCount - 1}.");
            return 1;
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexRouteInsertSanity",
            DevCustomText: "ss8-8 routed insert",
            DevGuid: Guid.Parse("1d79a163-9aa9-46f8-88a6-bc344bd33b77"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 4);

        long rootOffset;
        long shelfOffset;
        ulong insertedKey = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)(itemCount + 128));
        ulong insertedIdentity = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)(itemCount + 128));
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8ins", 0);
            (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
            PrintCommit("ss8-8 insert root create", rootCommit);
            rootOffset = root.Offset;

            (shelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar8ShelfAndLinkRootRoute(rootOffset, 0x00, profile, itemCount);
            PrintCommit("ss8-8 insert shelf link", linkCommit);
            ValidateScalar8Scalar8RouteLinkCommit(linkCommit, profile, allocatorMetadataPages: 2);
            _ = session.GetAndResetReadTelemetry();

            (long routedOffset, Scalar8Scalar8InsertResult insertResult, DataKernelCommitTelemetry insertCommit) = session.InsertRoutedScalar8Scalar8NoSplit(
                rootOffset,
                0x00,
                profile,
                insertedKey,
                insertedIdentity,
                allowDuplicateKeys: true);
            if (routedOffset != shelfOffset || insertResult != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected routed SS8-8 no-split insert at shelf {shelfOffset}, got offset {routedOffset} result {insertResult}.");
            }

            PrintRead("ss8-8 insert route read", session.GetAndResetReadTelemetry());
            PrintCommit("ss8-8 insert shelf rewrite", insertCommit);
            ValidateScalar8Scalar8RouteInsertCommit(insertCommit, profile);
            ValidateRoutedScalar8Scalar8Shelf(session, rootOffset, shelfOffset, profile, itemCount + 1, insertedKey, insertedIdentity);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = reopened.GetAndResetReadTelemetry();
            ValidateRoutedScalar8Scalar8Shelf(reopened, rootOffset, shelfOffset, profile, itemCount + 1, insertedKey, insertedIdentity);
        }

        Console.WriteLine($"ss8-8-route-insert-sanity ok path={path} root={rootOffset} shelf={shelfOffset} size={profile.ShelfExtentSize} items={itemCount + 1}");
        return 0;
    }


