    /// <summary>
    /// Validates the first routed `SS8-8` split mutation path where the split boundary is representable by a root-router prefix byte.<br/>
    /// The command creates one full shelf shared by two root prefixes, splits it into the original left shelf plus one appended right shelf, and rewrites only the changed root route.<br/>
    /// This proves the first structural mutation write shape before same-prefix shelf-to-router transformation is added.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the routed split validation succeeds; otherwise one.</returns>
    private static int RunScalar8Scalar8RouteSplitSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-route-split-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        int leftCount = profile.MaxItemCount / 2;
        int rightCount = profile.MaxItemCount - leftCount;
        ulong[] encodedKeys = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentities = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            ulong encoded = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)i);
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        const ulong rightPrefixBase = 0x8000_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            ulong encoded = rightPrefixBase + (ulong)i;
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        ulong insertedKey = rightPrefixBase + 10_000UL;
        ulong insertedIdentity = insertedKey;
        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexRouteSplitSanity",
            DevCustomText: "ss8-8 routed split",
            DevGuid: Guid.Parse("80e9775a-61e4-4b16-980d-195b9c3364dd"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 5);

        long rootOffset;
        long leftShelfOffset;
        long rightShelfOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8split", 0);
            (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
            PrintCommit("ss8-8 split root create", rootCommit);
            rootOffset = root.Offset;

            (leftShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(
                rootOffset,
                profile,
                encodedKeys,
                encodedIdentities,
                [0x00, 0x80]);
            PrintCommit("ss8-8 split shared shelf link", linkCommit);
            ValidateScalar8Scalar8RouteLinkCommit(linkCommit, profile, allocatorMetadataPages: 2);
            _ = session.GetAndResetReadTelemetry();

            (
                long splitLeftOffset,
                long splitRightOffset,
                int splitLeftCount,
                int splitRightCount,
                Scalar8Scalar8InsertResult insertResult,
                DataKernelCommitTelemetry splitCommit) = session.SplitRoutedScalar8Scalar8ByRootPrefix(
                    rootOffset,
                    0x00,
                    0x80,
                    profile,
                    insertedKey,
                    insertedIdentity);

            if (splitLeftOffset != leftShelfOffset || insertResult != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected routed SS8-8 split to rewrite left shelf {leftShelfOffset}, got offset {splitLeftOffset} result {insertResult}.");
            }

            rightShelfOffset = splitRightOffset;
            if (rightShelfOffset == 0 || rightShelfOffset == leftShelfOffset)
            {
                throw new InvalidDataException("Routed SS8-8 split did not allocate a distinct right shelf.");
            }

            if (splitLeftCount != leftCount || splitRightCount != rightCount + 1)
            {
                throw new InvalidDataException($"Routed SS8-8 split counts drifted. Expected {leftCount}/{rightCount + 1}, actual {splitLeftCount}/{splitRightCount}.");
            }

            PrintRead("ss8-8 split route read", session.GetAndResetReadTelemetry());
            PrintCommit("ss8-8 split commit", splitCommit);
            ValidateScalar8Scalar8RouteSplitCommit(splitCommit, profile, allocatorMetadataPages: 1, expectedWriteCalls: 4);
            ValidateRoutedScalar8Scalar8ShelfShape(session, rootOffset, 0x00, leftShelfOffset, profile, leftCount, Scalar8Scalar8Layout.EncodeUnsignedScalar8(128), Scalar8Scalar8Layout.EncodeUnsignedScalar8(128));
            ValidateRoutedScalar8Scalar8ShelfShape(session, rootOffset, 0x80, rightShelfOffset, profile, rightCount + 1, insertedKey, insertedIdentity);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = reopened.GetAndResetReadTelemetry();
            ValidateRoutedScalar8Scalar8ShelfShape(reopened, rootOffset, 0x00, leftShelfOffset, profile, leftCount, Scalar8Scalar8Layout.EncodeUnsignedScalar8(128), Scalar8Scalar8Layout.EncodeUnsignedScalar8(128));
            ValidateRoutedScalar8Scalar8ShelfShape(reopened, rootOffset, 0x80, rightShelfOffset, profile, rightCount + 1, insertedKey, insertedIdentity);
        }

        Console.WriteLine($"ss8-8-route-split-sanity ok path={path} root={rootOffset} left={leftShelfOffset} right={rightShelfOffset} size={profile.ShelfExtentSize} items={leftCount}/{rightCount + 1}");
        return 0;
    }


