    /// <summary>
    /// Validates the first routed `FS32-8` split mutation path where the split boundary is representable by a root-router prefix byte.<br/>
    /// The command creates one full fixed-key shelf shared by two root prefixes, splits it into the original left shelf plus one appended right shelf, and rewrites only the changed root route.<br/>
    /// This mirrors `ss16-8-route-split-sanity` while keeping the `FS32-8` shelf bytes and routing primitive isolated.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the routed split validation succeeds; otherwise one.</returns>
    private static int RunFixed32Scalar8RouteSplitSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "fs32-8-route-split-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Fixed32Scalar8Profile profile = Fixed32Scalar8Profile.Default40KiB;
        int leftCount = profile.MaxItemCount / 2;
        int rightCount = profile.MaxItemCount - leftCount;
        ulong[] key0s = new ulong[profile.MaxItemCount];
        ulong[] key1s = new ulong[profile.MaxItemCount];
        ulong[] key2s = new ulong[profile.MaxItemCount];
        ulong[] key3s = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentities = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            Fixed32Scalar8Layout.EncodeFixed32FromUInt64((ulong)i, out key0s[index], out key1s[index], out key2s[index], out key3s[index]);
            encodedIdentities[index] = Fixed32Scalar8Layout.EncodeUnsignedScalar8((ulong)i);
            index++;
        }

        const ulong rightPrefixKey0 = 0x8000_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            key0s[index] = rightPrefixKey0;
            key1s[index] = 0;
            key2s[index] = 0;
            key3s[index] = (ulong)i;
            encodedIdentities[index] = Fixed32Scalar8Layout.EncodeUnsignedScalar8((ulong)i);
            index++;
        }

        ulong insertedKey0 = rightPrefixKey0;
        ulong insertedKey1 = 0;
        ulong insertedKey2 = 0;
        ulong insertedKey3 = 10_000UL;
        ulong insertedIdentity = Fixed32Scalar8Layout.EncodeUnsignedScalar8(10_000UL);
        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexRouteSplitSanity",
            DevCustomText: "fs32-8 routed split",
            DevGuid: Guid.Parse("d9e4e542-65e6-42dc-a78c-258b97e4e715"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 9);

        long rootOffset;
        long leftShelfOffset;
        long rightShelfOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "f32split", 0);
            (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
            PrintCommit("fs32-8 split root create", rootCommit);
            rootOffset = root.Offset;

            (leftShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateFixed32Scalar8ShelfAndLinkRootRoutes(
                rootOffset,
                profile,
                key0s,
                key1s,
                key2s,
                key3s,
                encodedIdentities,
                [0x00, 0x80]);
            PrintCommit("fs32-8 split shared shelf link", linkCommit);
            ValidateFixed32Scalar8RouteLinkCommit(linkCommit, profile);
            _ = session.GetAndResetReadTelemetry();

            (
                long splitLeftOffset,
                long splitRightOffset,
                int splitLeftCount,
                int splitRightCount,
                Fixed32Scalar8InsertResult insertResult,
                DataKernelCommitTelemetry splitCommit) = session.SplitRoutedFixed32Scalar8ByRootPrefix(
                    rootOffset,
                    0x00,
                    0x80,
                    profile,
                    insertedKey0,
                    insertedKey1,
                    insertedKey2,
                    insertedKey3,
                    insertedIdentity);

            if (splitLeftOffset != leftShelfOffset || insertResult != Fixed32Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected routed FS32-8 split to rewrite left shelf {leftShelfOffset}, got offset {splitLeftOffset} result {insertResult}.");
            }

            rightShelfOffset = splitRightOffset;
            if (rightShelfOffset == 0 || rightShelfOffset == leftShelfOffset)
            {
                throw new InvalidDataException("Routed FS32-8 split did not allocate a distinct right shelf.");
            }

            if (splitLeftCount != leftCount || splitRightCount != rightCount + 1)
            {
                throw new InvalidDataException($"Routed FS32-8 split counts drifted. Expected {leftCount}/{rightCount + 1}, actual {splitLeftCount}/{splitRightCount}.");
            }

            PrintRead("fs32-8 split route read", session.GetAndResetReadTelemetry());
            PrintCommit("fs32-8 split commit", splitCommit);
            ValidateFixed32Scalar8RouteSplitCommit(splitCommit, profile);
            ValidateRoutedFixed32Scalar8ShelfShape(session, rootOffset, 0x00, leftShelfOffset, profile, leftCount, 0, 0, 0, 128, Fixed32Scalar8Layout.EncodeUnsignedScalar8(128));
            ValidateRoutedFixed32Scalar8ShelfShape(session, rootOffset, 0x80, rightShelfOffset, profile, rightCount + 1, insertedKey0, insertedKey1, insertedKey2, insertedKey3, insertedIdentity);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = reopened.GetAndResetReadTelemetry();
            ValidateRoutedFixed32Scalar8ShelfShape(reopened, rootOffset, 0x00, leftShelfOffset, profile, leftCount, 0, 0, 0, 128, Fixed32Scalar8Layout.EncodeUnsignedScalar8(128));
            ValidateRoutedFixed32Scalar8ShelfShape(reopened, rootOffset, 0x80, rightShelfOffset, profile, rightCount + 1, insertedKey0, insertedKey1, insertedKey2, insertedKey3, insertedIdentity);
        }

        Console.WriteLine($"fs32-8-route-split-sanity ok path={path} root={rootOffset} left={leftShelfOffset} right={rightShelfOffset} size={profile.ShelfExtentSize} items={leftCount}/{rightCount + 1}");
        return 0;
    }


