    /// <summary>
    /// Validates that every routed split-capable 16-byte identity shape preserves the full persisted identity pair.<br/>
    /// The command inserts more rows than one profiled shelf can hold for `SS8-16`, `SS16-16`, and `FS32-16`, forcing walked split paths instead of only no-split rewrites.<br/>
    /// After reopening each file, it point-reads every key range and compares both identity lanes against deterministic non-zero high/low values.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when all 16-byte identity split preservation checks pass.</returns>
    private static int RunIdentity16SplitPreservationSanity(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "identity16-split-preservation"));
        int extraItems = GetIntOption(args, "--extra-items", 257);
        if (extraItems <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), extraItems, "identity16-split-preservation-sanity requires a positive --extra-items value.");
        }

        Directory.CreateDirectory(directory);
        int scalar8Scalar16Count = RunScalar8Scalar16IdentitySplitPreservation(Path.Combine(directory, "ss8-16-identity16-split-preservation.lbdx"), extraItems);
        int scalar16Scalar16Count = RunScalar16Scalar16IdentitySplitPreservation(Path.Combine(directory, "ss16-16-identity16-split-preservation.lbdx"), extraItems);
        int fixed32Scalar16Count = RunFixed32Scalar16IdentitySplitPreservation(Path.Combine(directory, "fs32-16-identity16-split-preservation.lbdx"), extraItems);

        Console.WriteLine($"identity16-split-preservation-sanity ok directory={directory} ss8-16={scalar8Scalar16Count} ss16-16={scalar16Scalar16Count} fs32-16={fixed32Scalar16Count}");
        return 0;
    }


    /// <summary>
    /// Forces `SS8-16` walked splits and verifies exact 16-byte identities after reopen.<br/>
    /// Keys intentionally share the root prefix while varying deeper bytes so a full shelf must transform into deeper routed shelves.<br/>
    /// Identity high and low lanes are both non-zero and deterministic, catching regressions that accidentally keep only the low lane.<br/>
    /// </summary>
    /// <param name="path">The file path used for the isolated shape check.</param>
    /// <param name="extraItems">The number of rows to insert beyond one profiled shelf capacity.</param>
    /// <returns>The inserted item count.</returns>
    private static int RunScalar8Scalar16IdentitySplitPreservation(string path, int extraItems)
    {
        File.Delete(path);
        Scalar8Scalar16Profile profile = Scalar8Scalar16Profile.Default32KiB;
        int itemCount = checked(profile.MaxItemCount + extraItems);
        DataKernelOptions options = CreateIdentity16SplitPreservationOptions();
        long rootOffset;

        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(81616), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "s816id16", 0));
            rootOffset = root.Offset;
            _ = session.CreateScalar8Scalar16ShelfAndLinkRootRoute(rootOffset, 0x00, profile, itemCount: 0);

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            for (int i = 0; i < itemCount; i++)
            {
                ulong key = CreateIdentity16SplitScalar8Key(i);
                CreateIdentity16SplitIdentity(i, out ulong identityHigh, out ulong identityLow);
                Scalar8Scalar16RoutedInsertResult result = session.InsertWalkedRoutedScalar8Scalar16(rootOffset, profile, key, identityHigh, identityLow, allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.InsertResult != Scalar8Scalar16InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected SS8-16 identity split insert {i}, got {result.Kind}/{result.InsertResult}.");
                }
            }

            _ = durabilityBatch.Commit();
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            using RouteTargetKindCache targetKindCache = RouteTargetKindCache.Rent();
            byte[] shelfScratch = new byte[profile.ShelfExtentSize];
            for (int i = 0; i < itemCount; i++)
            {
                ulong key = CreateIdentity16SplitScalar8Key(i);
                CreateIdentity16SplitIdentity(i, out ulong expectedHigh, out ulong expectedLow);
                ValidateScalar8Scalar16IdentityPointRead(reopened, rootOffset, profile, key, expectedHigh, expectedLow, shelfScratch, targetKindCache);
            }
        }

        return itemCount;
    }


