    /// <summary>
    /// Forces `FS32-16` walked splits and verifies exact 16-byte identities after reopen.<br/>
    /// The first fixed-key lane shares the root prefix and varies deeper bytes so this specifically covers the recent full-pair `FS32-16` split promotion.<br/>
    /// Each reopened point read validates both identity lanes, making low-only preservation bugs visible.<br/>
    /// </summary>
    /// <param name="path">The file path used for the isolated shape check.</param>
    /// <param name="extraItems">The number of rows to insert beyond one profiled shelf capacity.</param>
    /// <returns>The inserted item count.</returns>
    private static int RunFixed32Scalar16IdentitySplitPreservation(string path, int extraItems)
    {
        File.Delete(path);
        Fixed32Scalar16Profile profile = Fixed32Scalar16Profile.Default40KiB;
        int itemCount = checked(profile.MaxItemCount + extraItems);
        DataKernelOptions options = CreateIdentity16SplitPreservationOptions();
        long rootOffset;

        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(321616), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "f3216id", 0));
            rootOffset = root.Offset;
            _ = session.CreateFixed32Scalar16ShelfAndLinkRootRoute(rootOffset, 0x00, profile, itemCount: 0);

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch();
            for (int i = 0; i < itemCount; i++)
            {
                CreateIdentity16SplitFixed32Key(i, out ulong key0, out ulong key1, out ulong key2, out ulong key3);
                CreateIdentity16SplitIdentity(i, out ulong identityHigh, out ulong identityLow);
                Fixed32Scalar16RoutedInsertResult result = session.InsertWalkedRoutedFixed32Scalar16(rootOffset, profile, key0, key1, key2, key3, identityHigh, identityLow, allowDuplicateKeys: true, maxRouterHops: 32);
                if (result.InsertResult != Fixed32Scalar16InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected FS32-16 identity split insert {i}, got {result.Kind}/{result.InsertResult}.");
                }
            }

            _ = durabilityBatch.Commit();
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            using RouteTargetKindCache targetKindCache = RouteTargetKindCache.Rent();
            byte[] shelfScratch = new byte[profile.ShelfExtentSize];
            for (int i = 0; i < itemCount; i++)
            {
                CreateIdentity16SplitFixed32Key(i, out ulong key0, out ulong key1, out ulong key2, out ulong key3);
                CreateIdentity16SplitIdentity(i, out ulong expectedHigh, out ulong expectedLow);
                ValidateFixed32Scalar16IdentityPointRead(reopened, rootOffset, profile, key0, key1, key2, key3, expectedHigh, expectedLow, shelfScratch, targetKindCache);
            }
        }

        return itemCount;
    }


    /// <summary>
    /// Validates the first routed `SS8-8` same-root-prefix split where the full shelf transmorphs into a child router.<br/>
    /// The command creates one full shelf under root prefix `0x00`, splits by second-byte prefix `0x80`, and verifies that the root router is not rewritten.<br/>
    /// This proves the structural-reuse path where the old shelf offset becomes a router while two new shelves are appended.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the routed transform validation succeeds; otherwise one.</returns>
    private static int RunScalar8Scalar8RouteTransformSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-route-transform-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        int leftCount = profile.MaxItemCount / 2;
        int rightCount = profile.MaxItemCount - leftCount;
        ulong[] encodedKeys = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentities = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            ulong encoded = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)i);
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            ulong encoded = secondByteRightBase + (ulong)i;
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        ulong insertedKey = secondByteRightBase + 10_000UL;
        ulong insertedIdentity = insertedKey;
        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexRouteTransformSanity",
            DevCustomText: "ss8-8 routed transform split",
            DevGuid: Guid.Parse("2d370bd7-4c9b-4963-a1fe-8e4c0f5dd165"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 6);

        long rootOffset;
        long childRouterOffset;
        long leftShelfOffset;
        long rightShelfOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8xform", 0);
            (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
            PrintCommit("ss8-8 transform root create", rootCommit);
            rootOffset = root.Offset;

            (long sourceShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(
                rootOffset,
                profile,
                encodedKeys,
                encodedIdentities,
                [0x00]);
            PrintCommit("ss8-8 transform source shelf link", linkCommit);
            ValidateScalar8Scalar8RouteLinkCommit(linkCommit, profile, allocatorMetadataPages: 2);
            _ = session.GetAndResetReadTelemetry();

            (
                long transformedOffset,
                long splitLeftOffset,
                long splitRightOffset,
                int splitLeftCount,
                int splitRightCount,
                Scalar8Scalar8InsertResult insertResult,
                DataKernelCommitTelemetry transformCommit) = session.SplitRoutedScalar8Scalar8ByShelfTransform(
                    rootOffset,
                    0x00,
                    0x80,
                    profile,
                    insertedKey,
                    insertedIdentity);

            if (transformedOffset != sourceShelfOffset || insertResult != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS8-8 transform split to reuse shelf offset {sourceShelfOffset}, got offset {transformedOffset} result {insertResult}.");
            }

            childRouterOffset = transformedOffset;
            leftShelfOffset = splitLeftOffset;
            rightShelfOffset = splitRightOffset;
            if (leftShelfOffset == 0 || rightShelfOffset == 0 || leftShelfOffset == rightShelfOffset)
            {
                throw new InvalidDataException("SS8-8 transform split did not allocate distinct replacement shelves.");
            }

            if (splitLeftCount != leftCount || splitRightCount != rightCount + 1)
            {
                throw new InvalidDataException($"SS8-8 transform split counts drifted. Expected {leftCount}/{rightCount + 1}, actual {splitLeftCount}/{splitRightCount}.");
            }

            PrintRead("ss8-8 transform route read", session.GetAndResetReadTelemetry());
            PrintCommit("ss8-8 transform commit", transformCommit);
            ValidateScalar8Scalar8TransformCommit(transformCommit, profile, allocatorMetadataPages: 1);

            long rootTargetAfterTransform = session.FindRouterTarget(rootOffset, 0x00);
            if (rootTargetAfterTransform != childRouterOffset)
            {
                throw new InvalidDataException("SS8-8 transform split changed the root route target.");
            }

            PrintRead("ss8-8 transform root unchanged read", session.GetAndResetReadTelemetry());
            ValidateTwoLevelRoutedScalar8Scalar8ShelfShape(session, rootOffset, 0x00, 0x00, childRouterOffset, leftShelfOffset, profile, leftCount, Scalar8Scalar8Layout.EncodeUnsignedScalar8(128), Scalar8Scalar8Layout.EncodeUnsignedScalar8(128));
            ValidateTwoLevelRoutedScalar8Scalar8ShelfShape(session, rootOffset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, rightCount + 1, insertedKey, insertedIdentity);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = reopened.GetAndResetReadTelemetry();
            ValidateTwoLevelRoutedScalar8Scalar8ShelfShape(reopened, rootOffset, 0x00, 0x00, childRouterOffset, leftShelfOffset, profile, leftCount, Scalar8Scalar8Layout.EncodeUnsignedScalar8(128), Scalar8Scalar8Layout.EncodeUnsignedScalar8(128));
            ValidateTwoLevelRoutedScalar8Scalar8ShelfShape(reopened, rootOffset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, rightCount + 1, insertedKey, insertedIdentity);
        }

        Console.WriteLine($"ss8-8-route-transform-sanity ok path={path} root={rootOffset} child={childRouterOffset} left={leftShelfOffset} right={rightShelfOffset} size={profile.ShelfExtentSize} items={leftCount}/{rightCount + 1}");
        return 0;
    }


