            }

            PrintRead("ss8-16 transform root unchanged read", session.GetAndResetReadTelemetry());
            ValidateTwoLevelRoutedScalar8Scalar16ShelfShape(session, rootOffset, 0x00, 0x00, childRouterOffset, leftShelfOffset, profile, leftCount, Scalar8Scalar16Layout.EncodeUnsignedScalar8(128), 0, 128);
