    /// <summary>
    /// Validates the first routed `SS16-16` same-root-prefix split where the full widened-key and widened-identity shelf transmorphs into a child router.<br/>
    /// The command creates one full shelf under root prefix `0x00`, splits by second-byte prefix `0x80`, and verifies that the root router is not rewritten.<br/>
    /// This proves the structural-reuse path where the old shelf offset becomes a router while two `SS16-16` shelves are appended.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the routed transform validation succeeds; otherwise one.</returns>
    private static int RunScalar16Scalar16RouteTransformSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss16-16-route-transform-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar16Scalar16Profile profile = Scalar16Scalar16Profile.Default32KiB;
        int leftCount = profile.MaxItemCount / 2;
        int rightCount = profile.MaxItemCount - leftCount;
        ulong[] encodedKeyHighs = new ulong[profile.MaxItemCount];
        ulong[] encodedKeyLows = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentityHighs = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentityLows = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            encodedKeyHighs[index] = 0;
            encodedKeyLows[index] = (ulong)i;
            encodedIdentityHighs[index] = 0;
            encodedIdentityLows[index] = (ulong)i;
            index++;
        }

        const ulong secondByteRightBaseHigh = 0x0080_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            encodedKeyHighs[index] = secondByteRightBaseHigh;
            encodedKeyLows[index] = (ulong)i;
            encodedIdentityHighs[index] = 0;
            encodedIdentityLows[index] = (ulong)i;
            index++;
        }

        ulong insertedKeyHigh = secondByteRightBaseHigh;
        ulong insertedKeyLow = 10_000UL;
        ulong insertedIdentityHigh = 1;
        ulong insertedIdentityLow = 10_000UL;
        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexRouteTransformSanity",
            DevCustomText: "ss16-16 routed transform split",
            DevGuid: Guid.Parse("4ce33139-c52e-4ec1-a8bf-949d9c8dc677"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 9);

        long rootOffset;
        long childRouterOffset;
        long leftShelfOffset;
        long rightShelfOffset;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "s1616xfm", 0);
            (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
            PrintCommit("ss16-16 transform root create", rootCommit);
            rootOffset = root.Offset;

            (long sourceShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar16Scalar16ShelfAndLinkRootRoutes(
                rootOffset,
                profile,
                encodedKeyHighs,
                encodedKeyLows,
                encodedIdentityHighs,
                encodedIdentityLows,
                [0x00]);
            PrintCommit("ss16-16 transform source shelf link", linkCommit);
            ValidateScalar16Scalar16RouteLinkCommit(linkCommit, profile);
            _ = session.GetAndResetReadTelemetry();

            (
                long transformedOffset,
                long splitLeftOffset,
                long splitRightOffset,
                int splitLeftCount,
                int splitRightCount,
                Scalar16Scalar16InsertResult insertResult,
                DataKernelCommitTelemetry transformCommit) = session.SplitRoutedScalar16Scalar16ByShelfTransform(
                    rootOffset,
                    0x00,
                    0x80,
                    profile,
                    insertedKeyHigh,
                    insertedKeyLow,
                    insertedIdentityHigh,
                    insertedIdentityLow);

            if (transformedOffset != sourceShelfOffset || insertResult != Scalar16Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected SS16-16 transform split to reuse shelf offset {sourceShelfOffset}, got offset {transformedOffset} result {insertResult}.");
            }

            childRouterOffset = transformedOffset;
            leftShelfOffset = splitLeftOffset;
            rightShelfOffset = splitRightOffset;
            if (leftShelfOffset == 0 || rightShelfOffset == 0 || leftShelfOffset == rightShelfOffset)
            {
                throw new InvalidDataException("SS16-16 transform split did not allocate distinct replacement shelves.");
            }

            if (splitLeftCount != leftCount || splitRightCount != rightCount + 1)
            {
                throw new InvalidDataException($"SS16-16 transform split counts drifted. Expected {leftCount}/{rightCount + 1}, actual {splitLeftCount}/{splitRightCount}.");
            }

            PrintRead("ss16-16 transform route read", session.GetAndResetReadTelemetry());
            PrintCommit("ss16-16 transform commit", transformCommit);
            ValidateScalar16Scalar16TransformCommit(transformCommit, profile);

            long rootTargetAfterTransform = session.FindRouterTarget(rootOffset, 0x00);
            if (rootTargetAfterTransform != childRouterOffset)
            {
                throw new InvalidDataException("SS16-16 transform split changed the root route target.");
            }

            PrintRead("ss16-16 transform root unchanged read", session.GetAndResetReadTelemetry());
            ValidateTwoLevelRoutedScalar16Scalar16ShelfShape(session, rootOffset, 0x00, 0x00, childRouterOffset, leftShelfOffset, profile, leftCount, 0, 128, 0, 128);
            ValidateTwoLevelRoutedScalar16Scalar16ShelfShape(session, rootOffset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, rightCount + 1, insertedKeyHigh, insertedKeyLow, insertedIdentityHigh, insertedIdentityLow);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = reopened.GetAndResetReadTelemetry();
            ValidateTwoLevelRoutedScalar16Scalar16ShelfShape(reopened, rootOffset, 0x00, 0x00, childRouterOffset, leftShelfOffset, profile, leftCount, 0, 128, 0, 128);
            ValidateTwoLevelRoutedScalar16Scalar16ShelfShape(reopened, rootOffset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, rightCount + 1, insertedKeyHigh, insertedKeyLow, insertedIdentityHigh, insertedIdentityLow);
        }

        Console.WriteLine($"ss16-16-route-transform-sanity ok path={path} root={rootOffset} child={childRouterOffset} left={leftShelfOffset} right={rightShelfOffset} size={profile.ShelfExtentSize} items={leftCount}/{rightCount + 1}");
        return 0;
    }


    /// <summary>
    /// Validates the unified internal routed `SS8-8` insert decision path across the three currently supported structural outcomes.<br/>
    /// The command uses separate files for no-split, root-prefix split, and same-prefix transform split so each scenario has deterministic route state and telemetry.<br/>
    /// This is an orchestration sanity check, not a replacement for the narrower mutation-shape tests.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when all routed insert decision scenarios succeed; otherwise one.</returns>
    private static int RunScalar8Scalar8RoutedInsertDecisionSanity(string[] args)
    {
        string basePath = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-routed-insert-decision-sanity.lbdx"));
        string directory = Path.GetDirectoryName(basePath)!;
        string fileName = Path.GetFileNameWithoutExtension(basePath);
        Directory.CreateDirectory(directory);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        string noSplitPath = Path.Combine(directory, fileName + "-nosplit.lbdx");
        string rootSplitPath = Path.Combine(directory, fileName + "-rootsplit.lbdx");
        string transformPath = Path.Combine(directory, fileName + "-transform.lbdx");
        File.Delete(noSplitPath);
        File.Delete(rootSplitPath);
        File.Delete(transformPath);

        RunScalar8Scalar8RoutedInsertDecisionNoSplit(noSplitPath, profile);
        RunScalar8Scalar8RoutedInsertDecisionRootSplit(rootSplitPath, profile);
        RunScalar8Scalar8RoutedInsertDecisionTransform(transformPath, profile);

        Console.WriteLine($"ss8-8-routed-insert-decision-sanity ok basePath={basePath} size={profile.ShelfExtentSize}");
        return 0;
    }


    /// <summary>
    /// Validates the first post-transform routed insert path through a root router, transformed child router, and target `SS8-8` shelf.<br/>
    /// The command creates a same-prefix transform split, then inserts one additional tuple into the right replacement shelf without triggering another split.<br/>
    /// This proves the first two-level no-split mutation before general deeper route walking is introduced.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the two-level routed insert validation succeeds; otherwise one.</returns>
    private static int RunScalar8Scalar8TwoLevelInsertSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-two-level-insert-sanity.lbdx"));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);

        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.Default32KiB;
        int leftCount = profile.MaxItemCount / 2;
        int rightCount = profile.MaxItemCount - leftCount;
        ulong[] encodedKeys = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentities = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            ulong encoded = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)i);
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            ulong encoded = secondByteRightBase + (ulong)i;
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexTwoLevelInsert",
            DevCustomText: "ss8-8 two-level insert",
            DevGuid: Guid.Parse("9652d924-654b-4975-b7cb-793fa3d98986"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 10);

        long rootOffset;
        long childRouterOffset;
        long rightShelfOffset;
        ulong splitInsertedKey = secondByteRightBase + 10_000UL;
        ulong splitInsertedIdentity = splitInsertedKey;
        ulong insertedKey = secondByteRightBase + 20_000UL;
        ulong insertedIdentity = insertedKey;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8lvl2", 0);
            (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
            PrintCommit("ss8-8 two-level root create", rootCommit);
            rootOffset = root.Offset;

            (long sourceShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(rootOffset, profile, encodedKeys, encodedIdentities, [0x00]);
            PrintCommit("ss8-8 two-level source shelf link", linkCommit);
            ValidateScalar8Scalar8RouteLinkCommit(linkCommit, profile, allocatorMetadataPages: 2);
            _ = session.GetAndResetReadTelemetry();

            (
                childRouterOffset,
                _,
                rightShelfOffset,
                _,
                int splitRightCount,
                Scalar8Scalar8InsertResult splitResult,
                DataKernelCommitTelemetry transformCommit) = session.SplitRoutedScalar8Scalar8ByShelfTransform(
                    rootOffset,
                    0x00,
                    0x80,
                    profile,
                    splitInsertedKey,
                    splitInsertedIdentity);
            if (childRouterOffset != sourceShelfOffset || splitResult != Scalar8Scalar8InsertResult.Inserted || splitRightCount != rightCount + 1)
            {
                throw new InvalidDataException("Two-level insert setup transform split did not produce the expected right shelf.");
            }

            PrintRead("ss8-8 two-level transform read", session.GetAndResetReadTelemetry());
            PrintCommit("ss8-8 two-level transform commit", transformCommit);
            ValidateScalar8Scalar8TransformCommit(transformCommit, profile, allocatorMetadataPages: 1);
            _ = session.GetAndResetReadTelemetry();

            Scalar8Scalar8RoutedInsertResult result = session.InsertTwoLevelRoutedScalar8Scalar8NoSplit(
                rootOffset,
                0x00,
                0x80,
                profile,
                insertedKey,
                insertedIdentity,
                allowDuplicateKeys: true);
            if (result.Kind != Scalar8Scalar8RoutedInsertKind.TwoLevelNoSplit || result.PrimaryOffset != rightShelfOffset || result.InsertResult != Scalar8Scalar8InsertResult.Inserted)
            {
                throw new InvalidDataException($"Expected two-level SS8-8 no-split insert at shelf {rightShelfOffset}, got {result.Kind}/{result.InsertResult} offset {result.PrimaryOffset}.");
            }

            PrintRead("ss8-8 two-level insert read", session.GetAndResetReadTelemetry());
            PrintCommit("ss8-8 two-level insert commit", result.Commit);
            ValidateScalar8Scalar8RouteInsertCommit(result.Commit, profile);
            ValidateTwoLevelRoutedScalar8Scalar8ShelfShape(session, rootOffset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, rightCount + 2, insertedKey, insertedIdentity);
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = reopened.GetAndResetReadTelemetry();
            ValidateTwoLevelRoutedScalar8Scalar8ShelfShape(reopened, rootOffset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, rightCount + 2, insertedKey, insertedIdentity);
        }

        Console.WriteLine($"ss8-8-two-level-insert-sanity ok path={path} root={rootOffset} child={childRouterOffset} shelf={rightShelfOffset} size={profile.ShelfExtentSize} items={rightCount + 2}");
        return 0;
    }


