    private static int RunScalar8Scalar16WalkedInsertSanity(string[] args)
    {
        string basePath = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-16-walked-insert-sanity.lbdx"));
        string directory = Path.GetDirectoryName(basePath)!;
        string fileName = Path.GetFileNameWithoutExtension(basePath);
        Directory.CreateDirectory(directory);

        Scalar8Scalar16Profile profile = Scalar8Scalar16Profile.Default32KiB;
        string oneLevelPath = Path.Combine(directory, fileName + "-one.lbdx");
        string twoLevelPath = Path.Combine(directory, fileName + "-two.lbdx");
        File.Delete(oneLevelPath);
        File.Delete(twoLevelPath);

        RunScalar8Scalar16WalkedInsertOneLevel(oneLevelPath, profile);
        RunScalar8Scalar16WalkedInsertTwoLevel(twoLevelPath, profile);

