            DataKernelCommitTelemetry setupCommit) = session.CreateScalar16Scalar16ShelfBehindChildRouter(
                root.Offset,
                0x00,
                0x00,
                profile,
                keyHighs,
                keyLows,
                identityHighs,
                identityLows);
        PrintCommit("ss16-16 walked transform setup", setupCommit);
        _ = session.GetAndResetReadTelemetry();

        (
            long transformedRouterOffset,
            long leftShelfOffset,
            long rightShelfOffset,
            _,
            _,
            Scalar16Scalar16InsertResult insertResult,
            DataKernelCommitTelemetry commit) = session.SplitWalkedRoutedScalar16Scalar16ByShelfTransform(
                root.Offset,
                profile,
                insertedKeyHigh,
                insertedKeyLow,
                insertedIdentityHigh,
                insertedIdentityLow,
                maxRouterHops: 8);
        DataKernelReadTelemetry readTelemetry = session.GetAndResetReadTelemetry();
        PrintRead("ss16-16 walked transform read", readTelemetry);
        PrintCommit("ss16-16 walked transform commit", commit);
        if (transformedRouterOffset != sourceShelfOffset || leftShelfOffset == 0 || rightShelfOffset == 0 || insertResult != Scalar16Scalar16InsertResult.Inserted)
        {
            throw new InvalidDataException("Walked SS16-16 transform split did not return the expected storage-facing result.");
        }

        if (readTelemetry.ReadCallCount != 5 || readTelemetry.BytesRead != RouterLayout.Size + sizeof(uint) + RouterLayout.Size + sizeof(uint) + profile.ShelfExtentSize)
        {
            throw new InvalidDataException("Walked SS16-16 transform split should read root router, child classifier, child router, shelf classifier, and one full shelf.");
        }

        ValidateAllocatedWalkedTransformCommit(commit, profile.ShelfExtentSize, allocationHeaderPages: 2);
        long rootTargetAfter = session.FindRouterTarget(root.Offset, 0x00);
        long childTargetAfter = session.FindRouterTarget(childRouterOffset, 0x00);
        if (rootTargetAfter != childRouterOffset || childTargetAfter != sourceShelfOffset)
        {
            throw new InvalidDataException("Walked SS16-16 transform split dirtied a parent route unexpectedly.");
        }

        long exactStemTarget = session.FindRouterTarget(sourceShelfOffset, 0x22);
        if (exactStemTarget == 0 ||
            session.FindRouterTarget(sourceShelfOffset, 0x21) != 0 ||
            session.FindRouterTarget(sourceShelfOffset, 0x23) != 0)
        {
            throw new InvalidDataException("Walked SS16-16 transform split did not preserve an exact-only intermediate route stem.");
        }

        Scalar16Scalar16RouteTarget routedTarget = session.WalkScalar16Scalar16RouteTarget(root.Offset, insertedKeyHigh, insertedKeyLow, maxRouterHops: 8);
        if (routedTarget.Kind != Scalar16Scalar16RouteTargetKind.Shelf || routedTarget.Offset != rightShelfOffset || routedTarget.RouterDepth != 3)
        {
            throw new InvalidDataException("Walked SS16-16 transform split did not route inserted key through the new next-depth router.");
        }

        _ = session.GetAndResetReadTelemetry();
        ValidateTwoLevelRoutedScalar16Scalar16ShelfShape(
            session,
            sourceShelfOffset,
            0x22,
            0x80,
            exactStemTarget,
            rightShelfOffset,
            profile,
            rightCount + 1,
            insertedKeyHigh,
            insertedKeyLow,
            insertedIdentityHigh,
            insertedIdentityLow);

        Console.WriteLine($"ss16-16-walked-transform-sanity ok path={path} root={root.Offset} child={childRouterOffset} transformed={transformedRouterOffset} left={leftShelfOffset} right={rightShelfOffset} size={profile.ShelfExtentSize}");
        return 0;
    }


