            ValidateGenericInsert(index.Insert(bytes32Next, nextGuidIdentity), "byte32[]/Guid post-cache insert");
            (cachedEntries, _, _) = index.Session.GetFixed32Scalar16ReadCacheStatsForValidation(index.RootRouterOffset);
