            long[] identities = new long[4];
            LibraDexGenericRangeReadResult read = opened.ReadRange(42, 43, identities);
            ValidateGenericRead(read, identities, new long[] { 4200, 4300 }, "long/long reopened read");
        }

        using (LibraDexIndex<Guid, long> openedGuid = Indexes.Open<Guid, long>(path, slotIndex: 1, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
