        using (LibraDexIndex<byte[], byte[]> openedBytes = Indexes.Open<byte[], byte[]>(path, slotIndex: 4, keyWidth: LibraDexScalarWidth.Bytes16, identityWidth: LibraDexScalarWidth.Bytes8, options: options, telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
