            LibraDexConditionEndCondition catalogPolicyInSetCondition = LibraDexCondition
                .ForGroup("policy")
                .Index("alias").AsString.InSet(new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ERIC" })
                .EndCondition;
