    /// <summary>
    /// Runs the reusable whole-solution quality gate over correctness-critical harness scenarios.<br/>
    /// The gate captures lightweight elapsed-time, allocation-delta, and output-file-size metrics without asserting performance thresholds yet, because this first pass establishes a repeatable baseline before adding fail policy.<br/>
    /// </summary>
    /// <param name="args">The command-line arguments; supports `--directory`, `--profile`, and `--keep-files`.</param>
    /// <returns>Zero when every included quality scenario passes.</returns>
    private static int RunSolutionQualitySanity(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "solution-quality-sanity"));
        string profile = GetOption(args, "--profile", "core");
        bool keepFiles = HasFlag(args, "--keep-files");
        Directory.CreateDirectory(directory);

        QualityScenario[] scenarios = CreateQualityScenarios(profile);
        List<QualityScenarioResult> results = new(scenarios.Length);
        Stopwatch totalWatch = Stopwatch.StartNew();
        Console.WriteLine($"solution quality sanity profile={profile} scenarios={scenarios.Length} directory={directory}");
        for (int i = 0; i < scenarios.Length; i++)
        {
            QualityScenario scenario = scenarios[i];
            string? target = scenario.FileName is null ? null : Path.Combine(directory, scenario.FileName);
            DeleteQualityTarget(target, scenario.TargetOption);

            string[] scenarioArgs = CreateQualityScenarioArgs(scenario, target);
            Console.WriteLine($"quality start {i + 1}/{scenarios.Length} {scenario.Command}");
            long allocatedBefore = GC.GetTotalAllocatedBytes(precise: true);
            Stopwatch watch = Stopwatch.StartNew();
            int exitCode = Run(scenarioArgs);
            watch.Stop();
            long allocatedAfter = GC.GetTotalAllocatedBytes(precise: true);
            if (exitCode != 0)
            {
                throw new InvalidDataException($"Quality scenario '{scenario.Command}' failed with exit code {exitCode}.");
            }

            long fileBytes = GetQualityTargetBytes(target, scenario.TargetOption);
            long allocatedBytes = Math.Max(0, allocatedAfter - allocatedBefore);
            results.Add(new QualityScenarioResult(
                scenario.Command,
                watch.Elapsed,
                allocatedBytes,
                fileBytes,
                target));
            Console.WriteLine(string.Create(
                CultureInfo.InvariantCulture,
                $"quality ok {scenario.Command} elapsedMs={watch.Elapsed.TotalMilliseconds:F3} allocatedBytes={allocatedBytes} fileBytes={fileBytes}"));

            if (!keepFiles)
            {
                DeleteQualityTarget(target, scenario.TargetOption);
            }
        }

        totalWatch.Stop();
        Console.WriteLine();
        Console.WriteLine("| Scenario | Elapsed ms | Allocated MiB | File MiB |");
        Console.WriteLine("|---|---:|---:|---:|");
        for (int i = 0; i < results.Count; i++)
        {
            QualityScenarioResult result = results[i];
            Console.WriteLine(string.Create(
                CultureInfo.InvariantCulture,
                $"| {result.Command} | {result.Elapsed.TotalMilliseconds:F3} | {result.AllocatedBytes / 1048576d:F3} | {result.FileBytes / 1048576d:F3} |"));
        }

        long totalAllocated = results.Sum(static result => result.AllocatedBytes);
        long totalFileBytes = results.Sum(static result => result.FileBytes);
        Console.WriteLine(string.Create(
            CultureInfo.InvariantCulture,
            $"solution-quality-sanity ok profile={profile} scenarios={results.Count} elapsedMs={totalWatch.Elapsed.TotalMilliseconds:F3} allocatedMiB={totalAllocated / 1048576d:F3} fileMiB={totalFileBytes / 1048576d:F3}"));
        return 0;
    }


    /// <summary>
    /// Creates the scenario matrix for one quality-gate profile.<br/>
    /// The `core` profile favors broad correctness plus cheap size/timing telemetry; `extended` adds heavier routed and transform checks without making them the default developer loop.<br/>
    /// </summary>
    /// <param name="profile">The requested profile name.</param>
    /// <returns>The quality scenarios in execution order.</returns>
    private static QualityScenario[] CreateQualityScenarios(string profile)
    {
        QualityScenario[] core =
        {
            new("public-surface-api-sanity", "public-surface-api-sanity.lbdx"),
            new("catalog-api-sanity", "catalog-api-sanity.lbdx"),
            new("generic-index-api-sanity", "generic-index-api-sanity.lbdx"),
            new("multi-index-same-identities-sanity", "multi-index-same-identities-sanity.lbdx"),
            new("write-intent-sanity", "write-intent-sanity.lbdx"),
            new("ss8-8-index-api-sanity", "ss8-8-index-api-sanity.lbdx"),
            new("ss16-8-sanity", null),
            new("ss8-16-sanity", null),
            new("ss16-16-sanity", null),
            new("fs32-8-sanity", null),
            new("fs32-16-sanity", null),
            new("vs8-index-api-sanity", "vs8-index-api-sanity.lbdx"),
            new("vs16-index-api-sanity", "vs16-index-api-sanity.lbdx"),
            new("vv-index-api-sanity", "vv-index-api-sanity.lbdx"),
            new("sv8-index-api-sanity", "sv8-index-api-sanity.lbdx"),
            new("sv16-index-api-sanity", "sv16-index-api-sanity.lbdx"),
            new("varlen-queued-maintenance-sanity", "varlen-queued-maintenance-sanity", "--directory"),
            new("varlen-optimizer-lifecycle-sanity", "varlen-optimizer-lifecycle-sanity", "--directory")
        };

        if (string.Equals(profile, "core", StringComparison.OrdinalIgnoreCase))
        {
            return core;
        }

        if (!string.Equals(profile, "extended", StringComparison.OrdinalIgnoreCase))
        {
            throw new ArgumentException("Quality profile must be 'core' or 'extended'.", nameof(profile));
        }

        QualityScenario[] extended =
        {
            new("route-sanity", "route-sanity.lbdx"),
            new("ss8-8-route-sanity", "ss8-8-route-sanity.lbdx"),
            new("ss16-8-route-sanity", "ss16-8-route-sanity.lbdx"),
            new("ss8-16-route-sanity", "ss8-16-route-sanity.lbdx"),
            new("ss16-16-route-sanity", "ss16-16-route-sanity.lbdx"),
            new("fs32-8-route-sanity", "fs32-8-route-sanity.lbdx"),
            new("vs8-routed-sanity", "vs8-routed-sanity.lbdx"),
            new("vs16-routed-sanity", "vs16-routed-sanity", "--directory"),
            new("vv-routed-sanity", "vv-routed-sanity.lbdx"),
            new("sv8-routed-sanity", "sv8-routed-sanity.lbdx"),
            new("sv16-routed-sanity", "sv16-routed-sanity.lbdx"),
            new("vs8-route-versioned-publish-sanity", "vs8-route-versioned-publish-sanity.lbdx"),
            new("varlen-promoted-router-view-sanity", "varlen-promoted-router-view-sanity", "--directory")
        };

        return core.Concat(extended).ToArray();
    }


    /// <summary>
    /// Builds the command-line argument array for one quality-gate scenario.<br/>
    /// Scenarios with an output path receive the gate-controlled `--path` value so elapsed time and file size can be compared across repeatable fixture names.<br/>
    /// </summary>
    /// <param name="scenario">The quality scenario descriptor.</param>
    /// <param name="path">The scenario output path, or null for pathless scenarios.</param>
    /// <returns>The argument array passed back through the harness dispatcher.</returns>
    private static string[] CreateQualityScenarioArgs(QualityScenario scenario, string? path)
    {
        List<string> args = new() { scenario.Command };
        if (path is not null)
        {
            args.Add(scenario.TargetOption);
            args.Add(path);
        }

        args.AddRange(scenario.ExtraArgs);
        return args.ToArray();
    }


    /// <summary>
    /// Deletes a quality-gate target before or after one scenario run.<br/>
    /// The target option decides whether the target is a single file path or a scenario-owned directory under the gate directory.<br/>
    /// </summary>
    /// <param name="target">The target file or directory, or null when the scenario has no persisted target.</param>
    /// <param name="targetOption">The command-line option used for the target.</param>
    private static void DeleteQualityTarget(string? target, string targetOption)
    {
        if (target is null)
        {
            return;
        }

        if (string.Equals(targetOption, "--directory", StringComparison.OrdinalIgnoreCase))
        {
            if (Directory.Exists(target))
            {
                Directory.Delete(target, recursive: true);
            }

            return;
        }

        File.Delete(target);
    }


    /// <summary>
    /// Calculates the persisted byte size for a quality-gate target.<br/>
    /// File targets report one file length, while directory targets sum all files created below the scenario-owned directory.<br/>
    /// </summary>
    /// <param name="target">The target file or directory, or null when the scenario has no persisted target.</param>
    /// <param name="targetOption">The command-line option used for the target.</param>
    /// <returns>The total persisted bytes observed after the scenario completes.</returns>
    private static long GetQualityTargetBytes(string? target, string targetOption)
    {
        if (target is null)
        {
            return 0;
        }

        if (string.Equals(targetOption, "--directory", StringComparison.OrdinalIgnoreCase))
        {
            return Directory.Exists(target)
                ? Directory.EnumerateFiles(target, "*", SearchOption.AllDirectories).Sum(static file => new FileInfo(file).Length)
                : 0;
        }

        return File.Exists(target) ? new FileInfo(target).Length : 0;
    }


    /// <summary>
    /// Tests whether a command-line flag is present.<br/>
    /// Flags are matched case-insensitively so harness scripts can remain tolerant of PowerShell casing habits.<br/>
    /// </summary>
    /// <param name="args">The command-line arguments.</param>
    /// <param name="name">The flag name to find.</param>
    /// <returns><see langword="true"/> when the flag is present.</returns>
    private static bool HasFlag(string[] args, string name)
    {
        return args.Any(argument => string.Equals(argument, name, StringComparison.OrdinalIgnoreCase));
    }


    private readonly record struct QualityScenario(string Command, string? FileName, string TargetOption = "--path", params string[] ExtraArgs);


    /// <summary>
    /// Compares public fixed-shape materialized reads with the new datareader-style cursor paths.<br/>
    /// The command builds one file-backed generic index per fixed shape, then measures materialized identity reads, cursor identity-only iteration, cursor key-only iteration, full tuple iteration, `Count`, and coarse `Skip` traversal.<br/>
    /// This is intentionally separate from the SQLite comparison suite because it isolates API-layer cost inside LibraDex before cross-engine comparisons are interpreted.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the fixed cursor reader comparison completes and writes a compact report.</returns>
    private static int RunFixedReaderPerf(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "FixedReaderPerf"));
        int itemCount = GetIntOption(args, "--items", 8192);
        int rangeCount = GetIntOption(args, "--range-count", 1024);
        int iterations = GetIntOption(args, "--iterations", 200);
        int repeatCount = GetIntOption(args, "--repeat-count", 3);
        if (itemCount <= 0 || rangeCount <= 0 || rangeCount > itemCount || iterations <= 0 || repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "fixed-reader-perf requires positive items, positive range count no larger than items, positive iterations, and positive repeat count.");
        }

        Directory.CreateDirectory(directory);
        DataKernelOptions options = CreateDesignPerfOptions();
        int startIndex = (itemCount - rangeCount) / 2;
        List<FixedReaderPerfRow> rows = [];

        rows.Add(MeasureFixedReaderPerfLongLong(Path.Combine(directory, "fixed-reader-ss8-8.lbdx"), options, itemCount, startIndex, rangeCount, iterations, repeatCount));
        rows.Add(MeasureFixedReaderPerfBytes16Long(Path.Combine(directory, "fixed-reader-ss16-8.lbdx"), options, itemCount, startIndex, rangeCount, iterations, repeatCount));
        rows.Add(MeasureFixedReaderPerfLongGuid(Path.Combine(directory, "fixed-reader-ss8-16.lbdx"), options, itemCount, startIndex, rangeCount, iterations, repeatCount));
        rows.Add(MeasureFixedReaderPerfBytes16Guid(Path.Combine(directory, "fixed-reader-ss16-16.lbdx"), options, itemCount, startIndex, rangeCount, iterations, repeatCount));
        rows.Add(MeasureFixedReaderPerfBytes32Long(Path.Combine(directory, "fixed-reader-fs32-8.lbdx"), options, itemCount, startIndex, rangeCount, iterations, repeatCount));
        rows.Add(MeasureFixedReaderPerfBytes32Guid(Path.Combine(directory, "fixed-reader-fs32-16.lbdx"), options, itemCount, startIndex, rangeCount, iterations, repeatCount));

        string reportPath = WriteFixedReaderPerfReport(directory, itemCount, startIndex, rangeCount, iterations, repeatCount, rows);
        Console.WriteLine("fixed reader perf");
        Console.WriteLine($"directory {directory}");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"rangeStart {startIndex}");
        Console.WriteLine($"rangeCount {rangeCount}");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"repeatCount {repeatCount}");
        PrintFixedReaderPerfRows(rows);
        Console.WriteLine($"report {reportPath}");
        Console.WriteLine("fixed-reader-perf ok");
        return 0;
    }


    /// <summary>
    /// Validates the first public write-intent option surface and the internal `VS8` batch policy hook.<br/>
    /// The command verifies default enum values, typed and generic batch overload compatibility, and a clustered varlen insert batch that exercises the mutation-hint sampling path.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when write-intent defaults, public overloads, and the clustered `VS8` session path validate.</returns>
    private static int RunWriteIntentSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "write-intent-sanity.lbdx"));
        int itemCount = GetIntOption(args, "--items", 2200);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int sharedPrefixLength = GetIntOption(args, "--shared-prefix-length", 8);
        if (itemCount <= 0 || keyLength <= sharedPrefixLength + 1 || keyLength > 1024 || sharedPrefixLength < 1 || sharedPrefixLength > 250)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Write-intent sanity requires positive items, key length within 2-1024, and a shared prefix that leaves at least two varying bytes.");
        }

        LibraDexWriteIntent defaultIntent = default;
        if (defaultIntent != LibraDexWriteIntent.Default ||
            defaultIntent.Order != LibraDexWriteOrder.Default ||
            defaultIntent.Volume != LibraDexWriteVolume.Default ||
            defaultIntent.Locality != LibraDexWriteLocality.Default ||
            defaultIntent.Priority != LibraDexWritePriority.Default)
        {
            throw new InvalidDataException("Default write intent did not preserve all Default enum values.");
        }

        LibraDexWriteIntent clusteredIntent = new(
            Order: LibraDexWriteOrder.Random,
            Volume: LibraDexWriteVolume.Thousands,
            Locality: LibraDexWriteLocality.Clustered,
            Priority: LibraDexWritePriority.WriteSpeed);

        DataKernelOptions options = CreateDesignPerfOptions();
        ulong[] typedIdentities = new ulong[4];
        using (UnsignedScalar8Scalar8Index typed = Indexes.SS88.Unsigned.Create(
            backingKind: DataKernelBackingKind.Memory,
            name: "write-intent-typed",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(914),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            using UnsignedScalar8Scalar8Batch batch = typed.BeginBatch(clusteredIntent);
            _ = batch.Insert(11, 1100);
            _ = batch.Insert(12, 1200);
            UnsignedScalar8Scalar8BatchCommitResult commit = batch.Commit();
            if (commit.InsertedCount != 2 || commit.DeferredCommitRequests == 0)
            {
                throw new InvalidDataException("Typed write-intent batch did not commit the expected inserted tuple count.");
            }

            UnsignedScalar8Scalar8RangeReadResult read = typed.ReadRange(11, 12, typedIdentities);
            if (read.IdentityCount != 2 || typedIdentities[0] != 1100 || typedIdentities[1] != 1200)
            {
                throw new InvalidDataException("Typed write-intent batch did not read back inserted identities.");
            }
        }

        long[] genericIdentities = new long[4];
        using (LibraDexIndex<long, long> generic = Indexes.Create<long, long>(
            backingKind: DataKernelBackingKind.Memory,
            name: "write-intent-generic",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(915),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            using LibraDexBatch<long, long> batch = generic.BeginBatch(clusteredIntent);
            _ = batch.Insert(21, 2100);
            _ = batch.Insert(22, 2200);
            LibraDexGenericBatchCommitResult commit = batch.Commit();
            if (commit.InsertedCount != 2 || commit.DeferredCommitRequests == 0)
            {
                throw new InvalidDataException("Generic write-intent batch did not commit the expected inserted tuple count.");
            }

            LibraDexGenericRangeReadResult read = generic.ReadRange(21, 22, genericIdentities);
            ValidateGenericRead(read, genericIdentities, new long[] { 2100, 2200 }, "write-intent generic read");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.Delete(path);
        long rootOffset;
        long childRouterOffset = 0;
        long transformCount = 0;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(916), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "vs8intent", 0));
            rootOffset = root.Offset;
            _ = session.CreateVarKeyScalar8ShelfAndLinkRootRoute(rootOffset, 0x35, VarKeyScalar8Profile.DefaultInitial);

            using LibraDexFileSessionDurabilityBatch durabilityBatch = session.BeginDurabilityBatch(clusteredIntent);
            for (int i = 0; i < itemCount; i++)
            {
                byte[] key = CreateVarKeyScalar8LongSharedPrefixKey(i, keyLength, sharedPrefixLength);
                VarKeyScalar8RoutedInsertResult result = session.InsertWalkedRoutedVarKeyScalar8(rootOffset, maxKeyLength: 1024, key, CreateVarKeyScalar8Identity(i), allowDuplicateKeys: true, maxRouterHops: 8);
                if (result.InsertResult != VarKeyScalar8InsertResult.Inserted)
                {
                    throw new InvalidDataException($"Expected clustered write-intent VS8 insert {i}, got {result.Kind}/{result.InsertResult}.");
                }

                if (result.Kind == VarKeyScalar8RoutedInsertKind.WalkedShelfTransformSplit)
                {
                    transformCount++;
                    childRouterOffset = result.PrimaryOffset;
                }
            }

            (DataKernelCommitTelemetry commit, long deferredRequests, _) = durabilityBatch.Commit();
            if (deferredRequests == 0 || commit.WriteCallCount == 0)
            {
                throw new InvalidDataException("Clustered write-intent VS8 batch did not fold lower-level commit requests into one publication.");
            }

            if (transformCount != 1 || childRouterOffset == 0)
            {
                throw new InvalidDataException($"Expected one clustered write-intent VS8 transform, got {transformCount}.");
            }

            byte[] childRouterBytes = new byte[RouterLayout.Size];
            session.ReadRouterPageForRangeScan(childRouterOffset, childRouterBytes);
            RouterReader childReader = new(childRouterBytes);
            if (!childReader.IsValid || childReader.HasDirectIndex || childReader.PrefixByteCount <= 1 || childReader.RouteCount != 2)
            {
                throw new InvalidDataException($"Expected clustered write-intent VS8 child to be a two-route multi-byte router, got valid={childReader.IsValid} direct={childReader.HasDirectIndex} prefixBytes={childReader.PrefixByteCount} routes={childReader.RouteCount}.");
            }
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            byte[] lower = CreateVarKeyScalar8LongSharedPrefixKey(0, keyLength, sharedPrefixLength);
            lower.AsSpan(sharedPrefixLength).Clear();
            byte[] upper = CreateVarKeyScalar8LongSharedPrefixKey(0, keyLength, sharedPrefixLength);
            upper.AsSpan(sharedPrefixLength).Fill(0xFF);
            ulong[] identities = new ulong[itemCount];
            int copied = reopened.ReadVarKeyScalar8IdentityRange(rootOffset, maxKeyLength: 1024, lower, upper, identities);
            if (copied != itemCount)
            {
                throw new InvalidDataException($"Reopened clustered write-intent VS8 range returned {copied} identities; expected {itemCount}.");
            }
        }

        Console.WriteLine("write intent sanity");
        Console.WriteLine($"path {path}");
        Console.WriteLine($"intent order={clusteredIntent.Order} volume={clusteredIntent.Volume} locality={clusteredIntent.Locality} priority={clusteredIntent.Priority}");
        Console.WriteLine("typedBatchIntent ok");
        Console.WriteLine("genericBatchIntent ok");
        Console.WriteLine($"vs8ClusteredIntent ok items={itemCount} keyLength={keyLength} sharedPrefixLength={sharedPrefixLength} transforms={transformCount}");
        Console.WriteLine("write-intent-sanity ok");
        return 0;
    }


    private static Guid CreateFixedReaderGuid(int value)
    {
        Span<byte> bytes = stackalloc byte[16];
        BinaryPrimitives.WriteInt32BigEndian(bytes.Slice(12, sizeof(int)), value);
        return new Guid(bytes);
    }

    /// <summary>
    /// Validates native descending `LibraDexRangeReader` traversal for every fixed generic shape.<br/>
    /// The check uses in-memory indexes so it can run inside public-surface sanity without adding file lifecycle noise.<br/>
    /// Each reader must return the highest key first and must do so through the range-reader path, not through materialized identity buffers.<br/>
    /// </summary>
    private static void ValidateNativeDescendingRangeShapes()
    {
        using Catalog catalog = Catalog.CreateMemory();
        Guid guid1 = CreateFixedReaderGuid(1);
        Guid guid2 = CreateFixedReaderGuid(2);
        Guid guid3 = CreateFixedReaderGuid(3);
        byte[] bytes1 = CreateDescendingShapeBytes32(1);
        byte[] bytes2 = CreateDescendingShapeBytes32(2);
        byte[] bytes3 = CreateDescendingShapeBytes32(3);

        using LibraDexIndex<long, long> ss88 = catalog.Indexes["descending-shapes"]["ss88"].Int64Keys<long>().Create();
        ValidateGenericInsert(ss88.Insert(1, 101), "descending SS8-8 insert 1");
        ValidateGenericInsert(ss88.Insert(2, 102), "descending SS8-8 insert 2");
        ValidateGenericInsert(ss88.Insert(3, 103), "descending SS8-8 insert 3");
        ValidateFixedShapePhysicalCount(ss88, 3, LibraDexCondition.ForGroup("descending-shapes").Index("ss88").AsInt64.Between(1, 2).EndCondition, 2, "SS8-8");
        using (LibraDexRangeReader<long, long> reader = ss88.OpenRangeReader(1, 3, QueryDirection.Descending))
        {
            if (!reader.TryReadNext(out long firstKey, out long firstIdentity) ||
                !reader.TryReadNext(out long secondKey, out _) ||
                !reader.TryReadNext(out long thirdKey, out _) ||
                reader.TryReadNext(out _, out _) ||
                firstKey != 3 ||
                firstIdentity != 103 ||
                secondKey != 2 ||
                thirdKey != 1)
            {
                throw new InvalidDataException("Native descending SS8-8 reader did not return expected key order.");
            }
        }

        ValidateFixedShapePhysicalCountAfterDelete(ss88, 2, 102, LibraDexCondition.ForGroup("descending-shapes").Index("ss88").AsInt64.EqualTo(2).EndCondition, 2, "SS8-8");

        using LibraDexIndex<Guid, long> ss168 = catalog.Indexes["descending-shapes"]["ss168"].GuidKeys<long>().Create();
        ValidateGenericInsert(ss168.Insert(guid1, 201), "descending SS16-8 insert 1");
        ValidateGenericInsert(ss168.Insert(guid2, 202), "descending SS16-8 insert 2");
        ValidateGenericInsert(ss168.Insert(guid3, 203), "descending SS16-8 insert 3");
        ValidateFixedShapePhysicalCount(ss168, 3, LibraDexCondition.ForGroup("descending-shapes").Index("ss168").AsGuid.Between(guid1, guid2).EndCondition, 2, "SS16-8");
        using (LibraDexRangeReader<Guid, long> reader = ss168.OpenRangeReader(guid1, guid3, QueryDirection.Descending))
        {
            if (!reader.TryReadNext(out Guid firstKey, out long firstIdentity) ||
                !reader.TryReadNext(out Guid secondKey, out _) ||
                !reader.TryReadNext(out Guid thirdKey, out _) ||
                reader.TryReadNext(out _, out _) ||
                firstKey != guid3 ||
                firstIdentity != 203 ||
                secondKey != guid2 ||
                thirdKey != guid1)
            {
                throw new InvalidDataException("Native descending SS16-8 reader did not return expected key order.");
            }
        }

        ValidateFixedShapePhysicalCountAfterDelete(ss168, guid2, 202, LibraDexCondition.ForGroup("descending-shapes").Index("ss168").AsGuid.EqualTo(guid2).EndCondition, 2, "SS16-8");

        using LibraDexIndex<long, Guid> ss816 = catalog.Indexes["descending-shapes"]["ss816"].Int64Keys<Guid>().Create();
        ValidateGenericInsert(ss816.Insert(1, guid1), "descending SS8-16 insert 1");
        ValidateGenericInsert(ss816.Insert(2, guid2), "descending SS8-16 insert 2");
        ValidateGenericInsert(ss816.Insert(3, guid3), "descending SS8-16 insert 3");
        ValidateFixedShapePhysicalCount(ss816, 3, LibraDexCondition.ForGroup("descending-shapes").Index("ss816").AsInt64.Between(1, 2).EndCondition, 2, "SS8-16");
        using (LibraDexRangeReader<long, Guid> reader = ss816.OpenRangeReader(1, 3, QueryDirection.Descending))
        {
            if (!reader.TryReadNext(out long firstKey, out Guid firstIdentity) ||
                !reader.TryReadNext(out long secondKey, out _) ||
                !reader.TryReadNext(out long thirdKey, out _) ||
                reader.TryReadNext(out _, out _) ||
                firstKey != 3 ||
                firstIdentity != guid3 ||
                secondKey != 2 ||
                thirdKey != 1)
            {
                throw new InvalidDataException("Native descending SS8-16 reader did not return expected key order.");
            }
        }

        ValidateFixedShapePhysicalCountAfterDelete(ss816, 2, guid2, LibraDexCondition.ForGroup("descending-shapes").Index("ss816").AsInt64.EqualTo(2).EndCondition, 2, "SS8-16");

        using LibraDexIndex<Guid, Guid> ss1616 = catalog.Indexes["descending-shapes"]["ss1616"].GuidKeys<Guid>().Create();
        ValidateGenericInsert(ss1616.Insert(guid1, guid1), "descending SS16-16 insert 1");
        ValidateGenericInsert(ss1616.Insert(guid2, guid2), "descending SS16-16 insert 2");
        ValidateGenericInsert(ss1616.Insert(guid3, guid3), "descending SS16-16 insert 3");
        ValidateFixedShapePhysicalCount(ss1616, 3, LibraDexCondition.ForGroup("descending-shapes").Index("ss1616").AsGuid.Between(guid1, guid2).EndCondition, 2, "SS16-16");
        using (LibraDexRangeReader<Guid, Guid> reader = ss1616.OpenRangeReader(guid1, guid3, QueryDirection.Descending))
        {
            if (!reader.TryReadNext(out Guid firstKey, out Guid firstIdentity) ||
                !reader.TryReadNext(out Guid secondKey, out _) ||
                !reader.TryReadNext(out Guid thirdKey, out _) ||
                reader.TryReadNext(out _, out _) ||
                firstKey != guid3 ||
                firstIdentity != guid3 ||
                secondKey != guid2 ||
                thirdKey != guid1)
            {
                throw new InvalidDataException("Native descending SS16-16 reader did not return expected key order.");
            }
        }

        ValidateFixedShapePhysicalCountAfterDelete(ss1616, guid2, guid2, LibraDexCondition.ForGroup("descending-shapes").Index("ss1616").AsGuid.EqualTo(guid2).EndCondition, 2, "SS16-16");

        using LibraDexIndex<byte[], long> fs328 = catalog.Indexes["descending-shapes"]["fs328"].Blob.Scalar<long>(LibraDexScalarWidth.Bytes32).Create();
        ValidateGenericInsert(fs328.Insert(bytes1, 501), "descending FS32-8 insert 1");
        ValidateGenericInsert(fs328.Insert(bytes2, 502), "descending FS32-8 insert 2");
        ValidateGenericInsert(fs328.Insert(bytes3, 503), "descending FS32-8 insert 3");
        ValidateFixedShapePhysicalCount(fs328, 3, LibraDexCondition.ForGroup("descending-shapes").Index("fs328").AsBinary.Between(bytes1, bytes2).EndCondition, 2, "FS32-8");
        using (LibraDexRangeReader<byte[], long> reader = fs328.OpenRangeReader(bytes1, bytes3, QueryDirection.Descending))
        {
            if (!reader.TryReadNext(out byte[] firstKey, out long firstIdentity) ||
                !reader.TryReadNext(out byte[] secondKey, out _) ||
                !reader.TryReadNext(out byte[] thirdKey, out _) ||
                reader.TryReadNext(out _, out _) ||
                !firstKey.AsSpan().SequenceEqual(bytes3) ||
                firstIdentity != 503 ||
                !secondKey.AsSpan().SequenceEqual(bytes2) ||
                !thirdKey.AsSpan().SequenceEqual(bytes1))
            {
                throw new InvalidDataException("Native descending FS32-8 reader did not return expected key order.");
            }
        }

        ValidateFixedShapePhysicalCountAfterDelete(fs328, bytes2, 502, LibraDexCondition.ForGroup("descending-shapes").Index("fs328").AsBinary.EqualTo(bytes2).EndCondition, 2, "FS32-8");

        using LibraDexIndex<byte[], Guid> fs3216 = catalog.Indexes["descending-shapes"]["fs3216"].Blob.Scalar<Guid>(LibraDexScalarWidth.Bytes32).Create();
        ValidateGenericInsert(fs3216.Insert(bytes1, guid1), "descending FS32-16 insert 1");
        ValidateGenericInsert(fs3216.Insert(bytes2, guid2), "descending FS32-16 insert 2");
        ValidateGenericInsert(fs3216.Insert(bytes3, guid3), "descending FS32-16 insert 3");
        ValidateFixedShapePhysicalCount(fs3216, 3, LibraDexCondition.ForGroup("descending-shapes").Index("fs3216").AsBinary.Between(bytes1, bytes2).EndCondition, 2, "FS32-16");
        using (LibraDexRangeReader<byte[], Guid> reader = fs3216.OpenRangeReader(bytes1, bytes3, QueryDirection.Descending))
        {
            if (!reader.TryReadNext(out byte[] firstKey, out Guid firstIdentity) ||
                !reader.TryReadNext(out byte[] secondKey, out _) ||
                !reader.TryReadNext(out byte[] thirdKey, out _) ||
                reader.TryReadNext(out _, out _) ||
                !firstKey.AsSpan().SequenceEqual(bytes3) ||
                firstIdentity != guid3 ||
                !secondKey.AsSpan().SequenceEqual(bytes2) ||
                !thirdKey.AsSpan().SequenceEqual(bytes1))
            {
                throw new InvalidDataException("Native descending FS32-16 reader did not return expected key order.");
            }
        }

        ValidateFixedShapePhysicalCountAfterDelete(fs3216, bytes2, guid2, LibraDexCondition.ForGroup("descending-shapes").Index("fs3216").AsBinary.EqualTo(bytes2).EndCondition, 2, "FS32-16");
    }

    /// <summary>
    /// Validates the opt-in single-key-per-identity contract exposed through public index options and persisted catalog metadata.<br/>
    /// The contract is deliberately enforced on immediate generic writes first: duplicate identity writes to a different key are rejected, lossless direct rekey remains available, and batch writers are rejected until they track staged identity-key ownership.<br/>
    /// </summary>
    private static void ValidateSingleKeyPerIdentityContract()
    {
        using Catalog catalog = Catalog.CreateMemory();
        IndexOptions options = new() { IdentityKeyMultiplicity = IdentityKeyMultiplicity.SingleKeyPerIdentity };
        using LibraDexIndex<long, long> index = catalog.Indexes["single-key"]["value"].Int64Keys<long>().Create(options: options);
        if (index.IdentityKeyMultiplicity != IdentityKeyMultiplicity.SingleKeyPerIdentity ||
            !catalog.Indexes.TryGetInfo("single-key", "value", out CatalogIndexInfo info) ||
            info.IdentityKeyMultiplicity != IdentityKeyMultiplicity.SingleKeyPerIdentity)
        {
            throw new InvalidDataException("Single-key-per-identity option was not exposed through index and catalog metadata.");
        }

        ValidateGenericInsert(index.Insert(10, 100), "single-key first insert");
        if (!index.TryGetSingleKey(100, out long firstKey) || firstKey != 10 ||
            index.TryGetSingleKey(999, out _))
        {
            throw new InvalidDataException("Single-key-per-identity lookup did not return the inserted key or reject a missing identity.");
        }

        Func<string, IIndex> singleKeyResolver = indexName => string.Equals(indexName, "value", StringComparison.Ordinal)
            ? index
            : throw new KeyNotFoundException(indexName);
        LibraDexConditionEndCondition singleLeafCondition = LibraDexCondition
            .ForGroup("single-key")
            .Index("value").AsInt64.EqualTo(10)
            .EndCondition;
        IIdentityCriterionProjection singleLeafProjection = singleLeafCondition
            .Materialize(singleKeyResolver)
            .IDsWith(deduplication: IdentityDeduplication.Distinct);
        if (singleLeafProjection.Plan().RequiresDistinct ||
            !singleLeafProjection.Iterate<long>().SequenceEqual(new[] { 100L }))
        {
            throw new InvalidDataException("A single-key primitive retained redundant runtime identity deduplication or changed its result stream.");
        }

        LibraDexConditionEndCondition duplicateMembershipCondition = LibraDexCondition
            .ForGroup("single-key")
            .Index("value").AsInt64.In(new long[] { 10, 10 })
            .EndCondition;
        IIdentityCriterionProjection duplicateMembershipProjection = duplicateMembershipCondition
            .Materialize(singleKeyResolver)
            .IDsWith(deduplication: IdentityDeduplication.Distinct);
        if (!duplicateMembershipProjection.Plan().RequiresDistinct ||
            !duplicateMembershipProjection.Iterate<long>().SequenceEqual(new[] { 100L }))
        {
            throw new InvalidDataException("A duplicate membership primitive incorrectly inherited single-key deduplication elision.");
        }

        LibraDexConditionEndCondition duplicateUnionCondition = LibraDexCondition
            .ForGroup("single-key")
            .Index("value").AsInt64.EqualTo(10)
            .Or.Index("value").AsInt64.EqualTo(10)
            .EndCondition;
        IIdentityCriterionProjection duplicateUnionProjection = duplicateUnionCondition
            .Materialize(singleKeyResolver)
            .IDsWith(deduplication: IdentityDeduplication.Distinct);
        if (!duplicateUnionProjection.Plan().RequiresDistinct ||
            !duplicateUnionProjection.Iterate<long>().SequenceEqual(new[] { 100L }))
        {
            throw new InvalidDataException("Composite duplicate-producing identity criteria did not retain distinct-result enforcement.");
        }

        LibraDexGenericInsertResult duplicateIdentityDifferentKey = index.Insert(11, 100);
        if (duplicateIdentityDifferentKey.Inserted ||
            index.Count() != 1 ||
            index.Count(LibraDexCondition.ForGroup("single-key").Index("value").AsInt64.EqualTo(11).EndCondition) != 0)
        {
            throw new InvalidDataException("Single-key-per-identity insert guard allowed the same identity at a different key.");
        }

        index.Rekey(100, 10, 12);
        if (!index.TryGetSingleKey(100, out long rekeyedKey) ||
            rekeyedKey != 12 ||
            index.Count() != 1 ||
            index.Count(LibraDexCondition.ForGroup("single-key").Index("value").AsInt64.EqualTo(10).EndCondition) != 0 ||
            index.Count(LibraDexCondition.ForGroup("single-key").Index("value").AsInt64.EqualTo(12).EndCondition) != 1 ||
            index.Insert(10, 100).Inserted)
        {
            throw new InvalidDataException("Single-key-per-identity direct rekey did not preserve exactly one identity-key association.");
        }

        using (LibraDexBatch<long, long> batch = index.BeginBatch())
        {
            ValidateGenericInsert(batch.Insert(30, 300), "single-key batch first insert");
            if (batch.Insert(31, 300).Inserted)
            {
                throw new InvalidDataException("Single-key-per-identity explicit batch allowed a staged duplicate identity at a different key.");
            }

            LibraDexGenericBatchCommitResult commit = batch.Commit();
            if (commit.InsertedCount != 1)
            {
                throw new InvalidDataException("Single-key-per-identity explicit batch did not publish exactly one accepted insert.");
            }

            if (!index.TryGetSingleKey(300, out long batchKey) || batchKey != 30)
            {
                throw new InvalidDataException("Single-key-per-identity lookup did not rebuild correctly after explicit batch publication.");
            }
        }

        using (Catalog groupCatalog = Catalog.CreateMemory())
        {
            LibraDexIndex<long, long> groupIndex = groupCatalog.Indexes["single-key-group"]["value"].Int64Keys<long>().Create(options: options);
            CatalogIdentityGroupBatchManager groupBatch = groupCatalog.Indexes["single-key-group"].Batch;
            groupBatch.Enable();
            ValidateGenericInsert(groupIndex.Insert(40, 400), "single-key group batch first insert");
            if (groupIndex.Insert(41, 400).Inserted)
            {
                throw new InvalidDataException("Single-key-per-identity group batch allowed a staged duplicate identity at a different key.");
            }

            LibraDexGenericBatchCommitResult groupCommit = groupBatch.PublishAndDisable();
            if (groupCommit.InsertedCount != 1)
            {
                throw new InvalidDataException("Single-key-per-identity group batch did not publish exactly one accepted insert.");
            }
        }

        LibraDexQueuedWriter<long, long> writer = index.BeginConcurrentWriter();
        ValidateGenericInsert(writer.Insert(50, 500), "single-key queued writer first insert");
        if (!index.TryGetSingleKey(500, out long queuedKey) || queuedKey != 50)
        {
            throw new InvalidDataException("Single-key-per-identity lookup was not maintained by queued insertion.");
        }

        if (writer.Insert(51, 500).Inserted)
        {
            throw new InvalidDataException("Single-key-per-identity queued writer allowed a staged duplicate identity at a different key.");
        }

        using (LibraDexConcurrentBatch<long, long> concurrentBatch = index.BeginConcurrentBatch())
        {
            ValidateGenericInsert(concurrentBatch.Insert(60, 600), "single-key concurrent batch first insert");
            if (concurrentBatch.Insert(61, 600).Inserted)
            {
                throw new InvalidDataException("Single-key-per-identity concurrent batch allowed a staged duplicate identity at a different key.");
            }

            LibraDexConcurrentBatchPublishResult concurrentPublish = concurrentBatch.Publish();
            if (concurrentPublish.InsertedCount != 1)
            {
                throw new InvalidDataException("Single-key-per-identity concurrent batch did not publish exactly one accepted insert.");
            }

            if (!index.TryGetSingleKey(600, out long concurrentKey) || concurrentKey != 60)
            {
                throw new InvalidDataException("Single-key-per-identity lookup did not rebuild correctly after concurrent batch publication.");
            }
        }

        string path = Path.Combine("artifacts", "tmp-single-key-contract.lbdx");
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
        File.Delete(path);
        using (Catalog persisted = Catalog.Create(path))
        {
            using LibraDexIndex<long, long> persistedIndex = persisted.Indexes["single-key"]["value"].Int64Keys<long>().Create(options: options);
            ValidateGenericInsert(persistedIndex.Insert(20, 200), "single-key persisted insert");
        }

        using (Catalog reopened = Catalog.Open(path))
        {
            if (!reopened.Indexes.TryGetInfo("single-key", "value", out CatalogIndexInfo reopenedInfo) ||
                reopenedInfo.IdentityKeyMultiplicity != IdentityKeyMultiplicity.SingleKeyPerIdentity)
            {
                throw new InvalidDataException("Single-key-per-identity metadata was not preserved across catalog reopen.");
            }

            using LibraDexIndex<long, long> reopenedIndex = reopened.Indexes["single-key"]["value"].Int64Keys<long>().Open();
            if (reopenedIndex.IdentityKeyMultiplicity != IdentityKeyMultiplicity.SingleKeyPerIdentity ||
                !reopenedIndex.TryGetSingleKey(200, out long reopenedKey) ||
                reopenedKey != 20)
            {
                throw new InvalidDataException("Single-key-per-identity reopened index did not expose the persisted contract and identity lookup.");
            }
        }
    }

    /// <summary>
    /// Validates public physical tuple counting for a fixed generic shape.<br/>
    /// The whole-index count exercises the public `.Count()` aggregate, while the condition count proves `.Count(where)` routes through condition primitive counting with tuple multiplicity preserved.<br/>
    /// </summary>
    /// <typeparam name="TKey">The fixed generic key type.</typeparam>
    /// <typeparam name="TIdentity">The fixed generic identity type.</typeparam>
    /// <param name="index">The populated index to count.</param>
    /// <param name="expectedAllCount">The expected whole-index tuple count.</param>
    /// <param name="condition">The condition whose physical tuple count should be tested.</param>
    /// <param name="expectedConditionCount">The expected condition tuple count.</param>
    /// <param name="shapeName">The diagnostic shape name.</param>
    private static void ValidateFixedShapePhysicalCount<TKey, TIdentity>(
        LibraDexIndex<TKey, TIdentity> index,
        long expectedAllCount,
        LibraDexConditionEndCondition condition,
        long expectedConditionCount,
        string shapeName)
    {
        if (index.Count() != expectedAllCount ||
            ((IIndex)index).Count() != expectedAllCount ||
            index.Count(condition) != expectedConditionCount)
        {
            throw new InvalidDataException($"{shapeName} physical tuple count did not match expected values.");
        }
    }

    /// <summary>
    /// Validates that exact tuple deletion updates only the already-written shelf state needed by physical tuple counts.<br/>
    /// Whole-index and exact-key counts are read after deletion so fixed shapes prove count metadata stays truthful without relying on an extra global count publication.<br/>
    /// </summary>
    /// <typeparam name="TKey">The fixed generic key type.</typeparam>
    /// <typeparam name="TIdentity">The fixed generic identity type.</typeparam>
    /// <param name="index">The populated index to mutate and count.</param>
    /// <param name="key">The exact key to delete.</param>
    /// <param name="identity">The exact identity to delete.</param>
    /// <param name="deletedKeyCondition">The exact-key condition that should become empty after delete.</param>
    /// <param name="expectedAllCount">The expected whole-index tuple count after delete.</param>
    /// <param name="shapeName">The diagnostic shape name.</param>
    private static void ValidateFixedShapePhysicalCountAfterDelete<TKey, TIdentity>(
        LibraDexIndex<TKey, TIdentity> index,
        TKey key,
        TIdentity identity,
        LibraDexConditionEndCondition deletedKeyCondition,
        long expectedAllCount,
        string shapeName)
    {
        index.Delete(key, identity);
        if (index.Count() != expectedAllCount ||
            ((IIndex)index).Count() != expectedAllCount ||
            index.Count(deletedKeyCondition) != 0)
        {
            throw new InvalidDataException($"{shapeName} physical tuple count did not track exact tuple deletion.");
        }
    }

    /// <summary>
    /// Creates a sortable 32-byte test key with the supplied value encoded in the final four bytes.<br/>
    /// The leading bytes stay zero so lexical fixed-key order follows the integer value and keeps descending-shape tests easy to reason about.<br/>
    /// </summary>
    /// <param name="value">The integer value to encode into the key suffix.</param>
    /// <returns>A new 32-byte key buffer.</returns>
    private static byte[] CreateDescendingShapeBytes32(int value)
    {
        byte[] key = new byte[32];
        BinaryPrimitives.WriteInt32BigEndian(key.AsSpan(28, sizeof(int)), value);
        return key;
    }


    private static string WriteFixedReaderPerfReport(string directory, int itemCount, int startIndex, int rangeCount, int iterations, int repeatCount, IReadOnlyList<FixedReaderPerfRow> rows)
    {
        string artifactDirectory = Path.Combine(directory, "artifacts");
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, "fixed-reader-perf-current.md");
        StringBuilder builder = new();
        builder.AppendLine("# Fixed Reader Perf");
        builder.AppendLine();
        builder.AppendLine($"- Items: `{itemCount}`");
        builder.AppendLine($"- Range start: `{startIndex}`");
        builder.AppendLine($"- Range count: `{rangeCount}`");
        builder.AppendLine($"- Iterations: `{iterations}`");
        builder.AppendLine($"- Repeat count: `{repeatCount}`");
        builder.AppendLine();
        builder.AppendLine("| Shape | Range | Materialized ns/id | Cursor identity ns/id | Cursor key ns/id | Cursor tuple ns/id | Desc tuple ns/id | Count ns/call | Skip ns/id |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < rows.Count; i++)
        {
            FixedReaderPerfRow row = rows[i];
            builder.AppendLine(FormattableString.Invariant($"| {row.Shape} | {row.RangeCount} | {row.MaterializedNsPerIdentity:F2} | {row.CursorIdentityNsPerIdentity:F2} | {row.CursorKeyNsPerIdentity:F2} | {row.CursorTupleNsPerIdentity:F2} | {row.DescendingTupleNsPerIdentity:F2} | {row.CountNsPerCall:F2} | {row.SkipNsPerIdentity:F2} |"));
        }

        return WriteReport(reportPath, builder);
    }


    /// <summary>
    /// Compares public varlen-identity cursor streaming against disconnected identity-buffer reads for `SV8`, `SV16`, and `VV`.<br/>
    /// The benchmark isolates the new public buffer-manager DX from SQLite and write-path variables by creating each shape once, reopening through the public API, and timing repeated reads of the same range.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the buffer comparison completes and writes a compact report.</returns>
    private static int RunVarIdentityBufferPerf(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "VarIdentityBufferPerf"));
        int itemCount = GetIntOption(args, "--items", 8192);
        int prefixCount = GetIntOption(args, "--prefix-count", 64);
        int rangePrefixCount = GetIntOption(args, "--range-prefix-count", 8);
        int keyLength = GetIntOption(args, "--key-length", 48);
        int identityLength = GetIntOption(args, "--identity-length", 48);
        int iterations = GetIntOption(args, "--iterations", 200);
        int repeatCount = GetIntOption(args, "--repeat-count", 3);
        if (itemCount <= 0 || prefixCount <= 0 || prefixCount > 256 || rangePrefixCount <= 0 || rangePrefixCount > prefixCount ||
            keyLength <= 0 || keyLength > 1024 || identityLength <= 0 || identityLength > 1024 || iterations <= 0 || repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "var-identity-buffer-perf requires positive item/read parameters, prefix counts within 1-256, and key/identity lengths within 1-1024.");
        }

        Directory.CreateDirectory(directory);
        DataKernelOptions options = CreateDesignPerfOptions();
        List<VarIdentityBufferPerfRow> rows = [];
        rows.Add(MeasureVarIdentityBufferPerfSv8(Path.Combine(directory, "var-identity-buffer-sv8.lbdx"), options, itemCount, prefixCount, rangePrefixCount, identityLength, iterations, repeatCount));
        rows.Add(MeasureVarIdentityBufferPerfSv16(Path.Combine(directory, "var-identity-buffer-sv16.lbdx"), options, itemCount, prefixCount, rangePrefixCount, identityLength, iterations, repeatCount));
        rows.Add(MeasureVarIdentityBufferPerfVv(Path.Combine(directory, "var-identity-buffer-vv.lbdx"), options, itemCount, prefixCount, rangePrefixCount, keyLength, identityLength, iterations, repeatCount));

        string reportPath = WriteVarIdentityBufferPerfReport(directory, itemCount, prefixCount, rangePrefixCount, keyLength, identityLength, iterations, repeatCount, rows);
        Console.WriteLine("var identity buffer perf");
        Console.WriteLine($"directory {directory}");
        Console.WriteLine($"items {itemCount}");
        Console.WriteLine($"prefixCount {prefixCount}");
        Console.WriteLine($"rangePrefixCount {rangePrefixCount}");
        Console.WriteLine($"keyLength {keyLength}");
        Console.WriteLine($"identityLength {identityLength}");
        Console.WriteLine($"iterations {iterations}");
        Console.WriteLine($"repeatCount {repeatCount}");
        PrintVarIdentityBufferPerfRows(rows);
        Console.WriteLine($"report {reportPath}");
        Console.WriteLine("var-identity-buffer-perf ok");
        return 0;
    }


    private static VarIdentityBufferPerfRow MeasureVarIdentityBufferPerfSv8(string path, DataKernelOptions options, int itemCount, int prefixCount, int rangePrefixCount, int identityLength, int iterations, int repeatCount)
    {
        File.Delete(path);
        using (Scalar8VarIdentityIndex index = Indexes.SV8.Create(
            path,
            name: "sv8-buffer-perf",
            maxIdentityLength: 1024,
            options: options,
            developerMetadata: CreateDesignPerfMetadata(9301),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            using Scalar8VarIdentityBatch batch = index.BeginBatch(new LibraDexWriteIntent(Volume: LibraDexWriteVolume.Thousands, Locality: LibraDexWriteLocality.Broad, Priority: LibraDexWritePriority.WriteSpeed));
            for (int i = 0; i < itemCount; i++)
            {
                _ = batch.Insert(CreateScalar8VarIdentityKey(i, prefixCount), CreateScalar8VarIdentity(i, identityLength));
            }

            _ = batch.Commit();
        }

        using Scalar8VarIdentityIndex opened = Indexes.SV8.Open(path, 0, 1024, options, DataKernelTelemetryOptions.EnabledOptions);
        ulong lower = CreateScalar8VarIdentityKey(0, prefixCount);
        ulong upper = CreateScalar8VarIdentityKey(rangePrefixCount - 1, prefixCount);
        int expected = CountScalar8VarIdentityKeyRange(itemCount, prefixCount, 0, rangePrefixCount - 1);
        VarIdentityBufferPerfSample[] samples = new VarIdentityBufferPerfSample[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureVarIdentityBufferPerfSample(
                "SV8",
                expected,
                iterations,
                () => opened.OpenRangeReader(lower, upper),
                () => opened.ReadIdentityBuffer(lower, upper, expected * identityLength));
        }

        return CreateVarIdentityBufferPerfRow("SV8", expected, SelectMedianVarIdentityBufferPerfSample(samples));
    }


    private static VarIdentityBufferPerfRow MeasureVarIdentityBufferPerfSv16(string path, DataKernelOptions options, int itemCount, int prefixCount, int rangePrefixCount, int identityLength, int iterations, int repeatCount)
    {
        File.Delete(path);
        using (Scalar16VarIdentityIndex index = Indexes.SV16.Create(
            path,
            name: "sv16-buffer-perf",
            maxIdentityLength: 1024,
            options: options,
            developerMetadata: CreateDesignPerfMetadata(9302),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            using Scalar16VarIdentityBatch batch = index.BeginBatch(new LibraDexWriteIntent(Volume: LibraDexWriteVolume.Thousands, Locality: LibraDexWriteLocality.Broad, Priority: LibraDexWritePriority.WriteSpeed));
            for (int i = 0; i < itemCount; i++)
            {
                CreateScalar16VarIdentityKey(i, prefixCount, "low", out ulong keyHigh, out ulong keyLow);
                _ = batch.Insert(keyHigh, keyLow, CreateScalar8VarIdentity(i, identityLength));
            }

            _ = batch.Commit();
        }

        using Scalar16VarIdentityIndex opened = Indexes.SV16.Open(path, 0, 1024, options, DataKernelTelemetryOptions.EnabledOptions);
        CreateScalar16VarIdentityKey(0, prefixCount, "low", out ulong lowerHigh, out ulong lowerLow);
        CreateScalar16VarIdentityKey(rangePrefixCount - 1, prefixCount, "low", out ulong upperHigh, out ulong upperLow);
        int expected = CountScalar8VarIdentityKeyRange(itemCount, prefixCount, 0, rangePrefixCount - 1);
        VarIdentityBufferPerfSample[] samples = new VarIdentityBufferPerfSample[repeatCount];
        for (int i = 0; i < repeatCount; i++)
        {
            samples[i] = MeasureVarIdentityBufferPerfSample(
                "SV16",
                expected,
                iterations,
                () => opened.OpenRangeReader(lowerHigh, lowerLow, upperHigh, upperLow),
                () => opened.ReadIdentityBuffer(lowerHigh, lowerLow, upperHigh, upperLow, expected * identityLength));
        }

        return CreateVarIdentityBufferPerfRow("SV16", expected, SelectMedianVarIdentityBufferPerfSample(samples));
    }


