    private static string WriteVarIdentityBufferPerfReport(string directory, int itemCount, int prefixCount, int rangePrefixCount, int keyLength, int identityLength, int iterations, int repeatCount, IReadOnlyList<VarIdentityBufferPerfRow> rows)
    {
        string artifactDirectory = Path.Combine(directory, "artifacts");
