        builder.AppendLine(CultureInfo.InvariantCulture, $"- Prefix count: `{prefixCount}`");
        builder.AppendLine(CultureInfo.InvariantCulture, $"- Range prefix count: `{rangePrefixCount}`");
        builder.AppendLine(CultureInfo.InvariantCulture, $"- Key length: `{keyLength}`");
        builder.AppendLine(CultureInfo.InvariantCulture, $"- Identity length: `{identityLength}`");
        builder.AppendLine(CultureInfo.InvariantCulture, $"- Iterations: `{iterations}`");
        builder.AppendLine(CultureInfo.InvariantCulture, $"- Repeat count: `{repeatCount}`");
        builder.AppendLine();
        builder.AppendLine("| Shape | Range | Cursor ns/id | Buffer build ns/id | Buffer build+iterate ns/id | Payload bytes | Checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|");
