        {
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {row.Shape} | {row.RangeCount} | {row.CursorNsPerIdentity:F2} | {row.BufferBuildNsPerIdentity:F2} | {row.BufferBuildAndIterateNsPerIdentity:F2} | {row.PayloadBytes} | {row.Checksum} |");
