        VarLenOptimizerModeShapeResult vs8 = ValidateVarKeyScalar8OptimizerLifecycleAutomaticMode(vs8Path, options, keys, maxKeyLength, branchCount, policy, lower, upper);
        VarLenOptimizerModeShapeResult vs16 = ValidateVarKeyScalar16OptimizerLifecycleAutomaticMode(vs16Path, options, keys, maxKeyLength, branchCount, policy, lower, upper);
