        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "Routed bulk-write prefix count must be between 1 and 256.");
        }

        if (commitGapCoalesceBytes < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), commitGapCoalesceBytes, "Routed bulk-write commit gap coalescing bytes cannot be negative.");
