        Scalar8Scalar8RoutedBulkWriteResult[] results =
        [
            MeasureRepeatedScalar8Scalar8RoutedBulkWrite(Path.Combine(directory, "ss8-8-routed-bulk-sorted.lbdx"), "public batch sorted", batches, warmupBatches, itemsPerBatch, prefixCount, sortedOrder, options, repeatCount, profile),
            MeasureRepeatedScalar8Scalar8RoutedBulkWrite(Path.Combine(directory, "ss8-8-routed-bulk-random.lbdx"), "public batch random", batches, warmupBatches, itemsPerBatch, prefixCount, randomOrder, options, repeatCount, profile)
        ];

        string reportPath = WriteScalar8Scalar8RoutedBulkWriteReport(artifactDirectory, batches, warmupBatches, itemsPerBatch, prefixCount, profile, results);
        Console.WriteLine("ss8-8 routed bulk write");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"warmupBatches {warmupBatches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        Console.WriteLine($"commitGapCoalesceBytes {commitGapCoalesceBytes:N0}");
        Console.WriteLine($"shelfSize {profile.ShelfExtentSize:N0}");
        PrintScalar8Scalar8RoutedBulkWriteResults(results);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }


