        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "SS16-8 routed bulk-write prefix count must be between 1 and 256.");
        }

        if (commitGapCoalesceBytes < 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), commitGapCoalesceBytes, "SS16-8 routed bulk-write commit gap coalescing bytes cannot be negative.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(artifactDirectory);
        Scalar16Scalar8Profile profile = Scalar16Scalar8Profile.Create(shelfExtentSize);
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        int[] randomOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Random);
        DataKernelOptions options = CreateDesignPerfOptions(commitGapCoalesceBytes);

