    /// <summary>
    /// Measures public-wrapper `SS8-8` range reads after building a larger routed tree through public batch writes.<br/>
    /// The setup uses `LibraDex.Indexes.SS88.Create`, commits bulk inserts with `Scalar8Scalar8Batch`, reopens the file, and reads through `Scalar8Scalar8Index.ReadEncodedRange`.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the public bulk-read report is written.</returns>
    private static int RunScalar8Scalar8PublicBulkRead(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-public-bulk-read.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 100);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 1024);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        int iterations = GetIntOption(args, "--iterations", 100);
        int repeatCount = GetIntOption(args, "--repeat-count", 1);
        int shelfExtentSize = GetIntOption(args, "--shelf-size", Scalar8Scalar8Profile.Default32KiB.ShelfExtentSize);
        Scalar8Scalar8BulkWriteLocalityMode localityMode = ParseScalar8Scalar8BulkWriteLocalityMode(GetOption(args, "--locality-mode", "batch-major"));
        if (batches <= 0 || itemsPerBatch <= 0 || iterations <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Public bulk-read batches, items per batch, and iterations must be positive.");
        }

        if (repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), repeatCount, "Public bulk-read repeat count must be positive.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "Public bulk-read prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        File.Delete(path);

        DataKernelOptions options = CreateDesignPerfOptions();
        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.FromSupportedShelfExtentSize(shelfExtentSize);
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        using (Scalar8Scalar8Index created = Indexes.SS88.Create(
            path,
            DataKernelBackingKind.File,
            name: "public-bulk-read",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(93),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions,
            shelfExtentSize: profile.ShelfExtentSize))
        {
            _ = RunScalar8Scalar8RoutedBulkWriteLoop(created, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, localityMode);
        }

        int itemsPerPrefix = (itemsPerBatch + prefixCount - 1) / prefixCount;
        int middlePrefix = prefixCount / 2;
        int crossUpperPrefix = Math.Min(2, prefixCount - 1);
        int maxRangeCount = Math.Max(batches * itemsPerPrefix, batches * itemsPerPrefix * (crossUpperPrefix + 1));
        ulong[] identities = new ulong[maxRangeCount];
        Scalar8Scalar8PublicBulkReadResult[] results = new Scalar8Scalar8PublicBulkReadResult[5];
        using (Scalar8Scalar8Index opened = Indexes.SS88.Open(
            path,
            options: options,
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            results[0] = MeasureRepeatedScalar8Scalar8PublicBulkReadRange(opened, "prefix 0 cached", batches, itemsPerBatch, prefixCount, 0, 0, iterations, enableCoalescing: false, identities, repeatCount);
            results[1] = MeasureRepeatedScalar8Scalar8PublicBulkReadRange(opened, "prefix middle cached", batches, itemsPerBatch, prefixCount, middlePrefix, middlePrefix, iterations, enableCoalescing: false, identities, repeatCount);
            results[2] = MeasureRepeatedScalar8Scalar8PublicBulkReadRange(opened, "prefix last cached", batches, itemsPerBatch, prefixCount, prefixCount - 1, prefixCount - 1, iterations, enableCoalescing: false, identities, repeatCount);
            results[3] = MeasureRepeatedScalar8Scalar8PublicBulkReadRange(opened, "prefix 0-2 cached", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, enableCoalescing: false, identities, repeatCount);
            results[4] = MeasureRepeatedScalar8Scalar8PublicBulkReadRange(opened, "prefix 0-2 coalesced", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, enableCoalescing: true, identities, repeatCount);
        }

        string reportPath = WriteScalar8Scalar8PublicBulkReadReport(artifactDirectory, batches, itemsPerBatch, prefixCount, iterations, localityMode, results);
        Console.WriteLine("ss8-8 public bulk read");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"iterations {iterations:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        Console.WriteLine($"localityMode {localityMode}");
        Console.WriteLine($"shelfSize {profile.ShelfExtentSize:N0}");
        PrintScalar8Scalar8PublicBulkReadResults(results);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }


