        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        int iterations = GetIntOption(args, "--iterations", 100);
        int repeatCount = GetIntOption(args, "--repeat-count", 3);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (batches <= 0 || warmupBatches < 0 || itemsPerBatch <= 0 || iterations <= 0 || repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "SQLite comparison batches, warmup batches, items per batch, iterations, and repeat count must be valid positive values.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "SQLite comparison prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(artifactDirectory);
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        int[] randomOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Random);
        SqliteScalar8Scalar8Options options = new(journalMode, synchronous);

        SqliteScalar8Scalar8WriteResult[] writeResults =
        [
            MeasureRepeatedSqliteScalar8Scalar8Write(Path.Combine(directory, "sqlite-ss8-8-sorted.db"), "sqlite batch sorted", batches, warmupBatches, itemsPerBatch, prefixCount, sortedOrder, options, repeatCount),
            MeasureRepeatedSqliteScalar8Scalar8Write(Path.Combine(directory, "sqlite-ss8-8-random.db"), "sqlite batch random", batches, warmupBatches, itemsPerBatch, prefixCount, randomOrder, options, repeatCount)
        ];

        string readPath = Path.Combine(directory, "sqlite-ss8-8-read.db");
        ResetSqliteScalar8Scalar8Files(readPath);
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(readPath, options))
        {
            InitializeSqliteScalar8Scalar8Schema(connection);
            RunSqliteScalar8Scalar8WriteLoop(connection, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0);
        }

        int itemsPerPrefix = (itemsPerBatch + prefixCount - 1) / prefixCount;
        int middlePrefix = prefixCount / 2;
        int crossUpperPrefix = Math.Min(2, prefixCount - 1);
        int maxRangeCount = Math.Max(batches * itemsPerPrefix, batches * itemsPerPrefix * (crossUpperPrefix + 1));
        ulong[] identities = new ulong[maxRangeCount];
        SqliteScalar8Scalar8ReadResult[] readResults = new SqliteScalar8Scalar8ReadResult[5];
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(readPath, options))
        {
            readResults[0] = MeasureRepeatedSqliteScalar8Scalar8ReadRange(connection, "sqlite prefix 0", batches, itemsPerBatch, prefixCount, 0, 0, iterations, identities, repeatCount);
            readResults[1] = MeasureRepeatedSqliteScalar8Scalar8ReadRange(connection, "sqlite prefix middle", batches, itemsPerBatch, prefixCount, middlePrefix, middlePrefix, iterations, identities, repeatCount);
            readResults[2] = MeasureRepeatedSqliteScalar8Scalar8ReadRange(connection, "sqlite prefix last", batches, itemsPerBatch, prefixCount, prefixCount - 1, prefixCount - 1, iterations, identities, repeatCount);
            readResults[3] = MeasureRepeatedSqliteScalar8Scalar8ReadRange(connection, "sqlite prefix 0-2", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
            readResults[4] = MeasureRepeatedSqliteScalar8Scalar8ReadRange(connection, "sqlite prefix 0-2 repeated", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
        }

        string reportPath = WriteSqliteScalar8Scalar8ComparisonReport(
            artifactDirectory,
            batches,
            warmupBatches,
            itemsPerBatch,
            prefixCount,
            iterations,
            options,
            writeResults,
            readResults);

        Console.WriteLine("sqlite ss8-8 comparison");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"warmupBatches {warmupBatches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"iterations {iterations:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        Console.WriteLine($"journalMode {journalMode}");
        Console.WriteLine($"synchronous {synchronous}");
        PrintSqliteScalar8Scalar8WriteResults(writeResults);
        PrintSqliteScalar8Scalar8ReadResults(readResults);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }


    /// <summary>
    /// Measures a SQLite B-tree comparison workload shaped for the `SS16-16` key and identity payload width.<br/>
    /// SQLite stores each key and identity as a fixed 16-byte `BLOB`, using big-endian bytes so SQLite binary ordering matches unsigned scalar tuple ordering.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the SQLite comparison report is written.</returns>
    private static int RunSqliteScalar16Scalar16Comparison(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "SQLiteSS16-16Comparison"));
