        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "SQLite SS16-16 comparison prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(artifactDirectory);
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        int[] randomOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Random);
        SqliteScalar8Scalar8Options options = new(journalMode, synchronous);

        SqliteScalar8Scalar8WriteResult[] writeResults =
        [
            MeasureRepeatedSqliteScalar16Scalar16BlobWrite(Path.Combine(directory, "sqlite-ss16-16-blob-sorted.db"), "sqlite blob batch sorted", batches, warmupBatches, itemsPerBatch, prefixCount, sortedOrder, options, repeatCount),
            MeasureRepeatedSqliteScalar16Scalar16BlobWrite(Path.Combine(directory, "sqlite-ss16-16-blob-random.db"), "sqlite blob batch random", batches, warmupBatches, itemsPerBatch, prefixCount, randomOrder, options, repeatCount)
        ];

        string readPath = Path.Combine(directory, "sqlite-ss16-16-blob-read.db");
        ResetSqliteScalar8Scalar8Files(readPath);
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(readPath, options))
        {
            InitializeSqliteScalar16Scalar16BlobSchema(connection);
            RunSqliteScalar16Scalar16BlobWriteLoop(connection, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0);
        }

        int itemsPerPrefix = (itemsPerBatch + prefixCount - 1) / prefixCount;
        int middlePrefix = prefixCount / 2;
        int crossUpperPrefix = Math.Min(2, prefixCount - 1);
        int maxRangeCount = Math.Max(batches * itemsPerPrefix, batches * itemsPerPrefix * (crossUpperPrefix + 1));
        ulong[] identities = new ulong[maxRangeCount];
        SqliteScalar8Scalar8ReadResult[] readResults = new SqliteScalar8Scalar8ReadResult[5];
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(readPath, options))
        {
            readResults[0] = MeasureRepeatedSqliteScalar16Scalar16BlobReadRange(connection, "sqlite blob prefix 0", batches, itemsPerBatch, prefixCount, 0, 0, iterations, identities, repeatCount);
            readResults[1] = MeasureRepeatedSqliteScalar16Scalar16BlobReadRange(connection, "sqlite blob prefix middle", batches, itemsPerBatch, prefixCount, middlePrefix, middlePrefix, iterations, identities, repeatCount);
            readResults[2] = MeasureRepeatedSqliteScalar16Scalar16BlobReadRange(connection, "sqlite blob prefix last", batches, itemsPerBatch, prefixCount, prefixCount - 1, prefixCount - 1, iterations, identities, repeatCount);
            readResults[3] = MeasureRepeatedSqliteScalar16Scalar16BlobReadRange(connection, "sqlite blob prefix 0-2", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
            readResults[4] = MeasureRepeatedSqliteScalar16Scalar16BlobReadRange(connection, "sqlite blob prefix 0-2 repeated", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
        }

        string reportPath = WriteSqliteScalar16Scalar16BlobComparisonReport(
            artifactDirectory,
            batches,
            warmupBatches,
            itemsPerBatch,
            prefixCount,
            iterations,
            options,
            writeResults,
            readResults);

        Console.WriteLine("sqlite ss16-16 blob comparison");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"warmupBatches {warmupBatches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"iterations {iterations:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        Console.WriteLine($"journalMode {journalMode}");
