                MeasureRepeatedSqliteScalar8Scalar16BlobWrite(Path.Combine(directory, "sqlite-ss8-16-sorted.db"), "sqlite ss8-16 sorted", batches, warmupBatches, itemsPerBatch, prefixCount, sortedOrder, sqliteOptions, repeatCount),
