    /// <summary>
    /// Measures `FS32-8` routed range-read throughput against a matching SQLite `BLOB(32)`/integer primary-key table.<br/>
    /// The LibraDex row uses the same fixed-key data generator as the all-shape write-parity command, then scans prefix-shaped ranges over the persisted routed tree.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the read-parity report is written.</returns>
    private static int RunFixed32Scalar8ReadParity(string[] args)
    {
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "FS32-8ReadParity"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 100);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 1024);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        int iterations = GetIntOption(args, "--iterations", 100);
        int repeatCount = GetIntOption(args, "--repeat-count", 3);
        int commitGapCoalesceBytes = GetIntOption(args, "--wide-commit-gap-coalesce-bytes", 16 * 1024);
        string journalMode = GetOption(args, "--journal-mode", "wal");
        string synchronous = GetOption(args, "--synchronous", "normal");
        if (batches <= 0 || itemsPerBatch <= 0 || iterations <= 0 || repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "FS32-8 read-parity batches, items per batch, iterations, and repeat count must be positive.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "FS32-8 read-parity prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(directory);
        Directory.CreateDirectory(artifactDirectory);
        string libraPath = Path.Combine(directory, "fs32-8-read.lbdx");
        File.Delete(libraPath);
        Fixed32Scalar8Profile profile = Fixed32Scalar8Profile.Default40KiB;
        DataKernelOptions libraOptions = CreateDesignPerfOptions(commitGapCoalesceBytes);
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        long rootOffset;
        using (LibraDexFileSession created = LibraDexFileSession.Initialize(libraPath, libraOptions, CreateDesignPerfMetadata(3281), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = created.CreateRootRouterIndex(CreateHarnessSlot(0, "f328read", 0));
            rootOffset = root.Offset;
            _ = RunFixed32Scalar8RoutedBulkWriteLoop(created, rootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, profile, includeAttribution: false);
        }

        int itemsPerPrefix = (itemsPerBatch + prefixCount - 1) / prefixCount;
        int middlePrefix = prefixCount / 2;
        int crossUpperPrefix = Math.Min(2, prefixCount - 1);
        int maxRangeCount = Math.Max(batches * itemsPerPrefix, batches * itemsPerPrefix * (crossUpperPrefix + 1));
        ulong[] identities = new ulong[maxRangeCount];
        Fixed32Scalar8ReadParityResult[] libraResults = new Fixed32Scalar8ReadParityResult[5];
        using (LibraDexFileSession opened = LibraDexFileSession.Open(libraPath, libraOptions, DataKernelTelemetryOptions.EnabledOptions))
        {
            libraResults[0] = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix 0", batches, itemsPerBatch, prefixCount, 0, 0, iterations, identities, repeatCount);
            libraResults[1] = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix middle", batches, itemsPerBatch, prefixCount, middlePrefix, middlePrefix, iterations, identities, repeatCount);
            libraResults[2] = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix last", batches, itemsPerBatch, prefixCount, prefixCount - 1, prefixCount - 1, iterations, identities, repeatCount);
            libraResults[3] = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix 0-2", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
            libraResults[4] = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix 0-2 repeated", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
        }

        SqliteScalar8Scalar8Options sqliteOptions = new(journalMode, synchronous);
        string sqlitePath = Path.Combine(directory, "sqlite-fs32-8-read.db");
        ResetSqliteScalar8Scalar8Files(sqlitePath);
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            InitializeSqliteFixed32Scalar8BlobSchema(connection);
            RunSqliteFixed32Scalar8BlobWriteLoop(connection, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0);
        }

        SqliteScalar8Scalar8ReadResult[] sqliteResults = new SqliteScalar8Scalar8ReadResult[5];
        using (SqliteConnection connection = OpenSqliteScalar8Scalar8Connection(sqlitePath, sqliteOptions))
        {
            sqliteResults[0] = MeasureRepeatedSqliteFixed32Scalar8BlobReadRange(connection, "sqlite fs32 prefix 0", batches, itemsPerBatch, prefixCount, 0, 0, iterations, identities, repeatCount);
            sqliteResults[1] = MeasureRepeatedSqliteFixed32Scalar8BlobReadRange(connection, "sqlite fs32 prefix middle", batches, itemsPerBatch, prefixCount, middlePrefix, middlePrefix, iterations, identities, repeatCount);
            sqliteResults[2] = MeasureRepeatedSqliteFixed32Scalar8BlobReadRange(connection, "sqlite fs32 prefix last", batches, itemsPerBatch, prefixCount, prefixCount - 1, prefixCount - 1, iterations, identities, repeatCount);
            sqliteResults[3] = MeasureRepeatedSqliteFixed32Scalar8BlobReadRange(connection, "sqlite fs32 prefix 0-2", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
            sqliteResults[4] = MeasureRepeatedSqliteFixed32Scalar8BlobReadRange(connection, "sqlite fs32 prefix 0-2 repeated", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, iterations, identities, repeatCount);
        }

        string reportPath = WriteFixed32Scalar8ReadParityReport(
            artifactDirectory,
            batches,
            itemsPerBatch,
            prefixCount,
            iterations,
            repeatCount,
            commitGapCoalesceBytes,
            sqliteOptions,
            libraResults,
            sqliteResults);

        Console.WriteLine("fs32-8 read parity");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"iterations {iterations:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        PrintFixed32Scalar8ReadParityResults(libraResults, sqliteResults);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }


    /// <summary>
    /// Sweeps `FS32-8` shelf sizes across routed bulk-write and routed range-read workloads.<br/>
    /// The command prioritizes logical read/write throughput while keeping bytes/item and per-range read bytes visible as secondary compactness and I/O diagnostics.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the size sweep report is written.</returns>
    private static int RunFixed32Scalar8SizeSweep(string[] args)
    {
        int[] shelfSizes = ParseIntList(GetOption(args, "--shelf-sizes", "32768,40960,49152,57344,65536"));
        string directory = GetOption(args, "--directory", Path.Combine(@"T:\LibraDex", "FS32-8SizeSweep"));
