        if (shelfSizes.Length == 0 || batches <= 0 || warmupBatches < 0 || itemsPerBatch <= 0 || prefixCount <= 0 || prefixCount > 256 || readIterations <= 0 || repeatCount <= 0 || commitGapCoalesceBytes < 0)
        {
