        for (int i = 0; i < shelfSizes.Length; i++)
        {
            Fixed32Scalar8Profile profile = Fixed32Scalar8Profile.Create(shelfSizes[i]);
            string profileDirectory = Path.Combine(directory, profile.ShelfExtentSize.ToString(CultureInfo.InvariantCulture));
            Directory.CreateDirectory(profileDirectory);
            Scalar8Scalar8RoutedBulkWriteResult sortedWrite = MeasureRepeatedFixed32Scalar8RoutedBulkWrite(
                Path.Combine(profileDirectory, "fs32-8-sorted.lbdx"),
