                warmupBatches,
                itemsPerBatch,
                prefixCount,
                sortedOrder,
                options,
                repeatCount,
                profile,
                includeAttribution: false);
            Scalar8Scalar8RoutedBulkWriteResult randomWrite = MeasureRepeatedFixed32Scalar8RoutedBulkWrite(
                Path.Combine(profileDirectory, "fs32-8-random.lbdx"),
                "fs32 random",
                batches,
                warmupBatches,
                itemsPerBatch,
                prefixCount,
                randomOrder,
                options,
                repeatCount,
                profile,
                includeAttribution: false);

            string readPath = Path.Combine(profileDirectory, "fs32-8-read.lbdx");
            File.Delete(readPath);
            long rootOffset;
            using (LibraDexFileSession created = LibraDexFileSession.Initialize(readPath, options, CreateDesignPerfMetadata(3282), DataKernelTelemetryOptions.EnabledOptions))
            {
                (RouterSnapshot root, _) = created.CreateRootRouterIndex(CreateHarnessSlot(0, "f328swp", 0));
                rootOffset = root.Offset;
                _ = RunFixed32Scalar8RoutedBulkWriteLoop(created, rootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, profile, includeAttribution: false);
            }

            Fixed32Scalar8ReadParityResult prefix0Read;
            Fixed32Scalar8ReadParityResult prefixSpanRead;
            using (LibraDexFileSession opened = LibraDexFileSession.Open(readPath, options, DataKernelTelemetryOptions.EnabledOptions))
            {
                prefix0Read = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix 0", batches, itemsPerBatch, prefixCount, 0, 0, readIterations, identities, repeatCount);
                prefixSpanRead = MeasureRepeatedFixed32Scalar8ReadRange(opened, rootOffset, profile, "fs32 prefix 0-2", batches, itemsPerBatch, prefixCount, 0, crossUpperPrefix, readIterations, identities, repeatCount);
            }

            rows[i] = new Fixed32Scalar8SizeSweepRow(profile, sortedWrite, randomWrite, prefix0Read, prefixSpanRead);
        }

        string reportPath = WriteFixed32Scalar8SizeSweepReport(
            artifactDirectory,
            batches,
            warmupBatches,
            itemsPerBatch,
            prefixCount,
            readIterations,
            repeatCount,
            commitGapCoalesceBytes,
            rows);

        Console.WriteLine("fs32-8 size sweep");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"warmupBatches {warmupBatches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"readIterations {readIterations:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        PrintFixed32Scalar8SizeSweepRows(rows);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }


