    /// <summary>
    /// Validates eight same-file indexes over the same generated identity set using two independent instances of each current physical shape.<br/>
    /// Creation, write, and reopen-validation orders are intentionally different from slot order so the test exercises index-directory slot replacement and root-router independence instead of sequential happy-path assumptions.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the eight-index same-identities sanity report is written.</returns>
    private static int RunMultiIndexEightSameIdentitiesSanity(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "multi-index-same-identities-sanity.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 8);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 256);
        int prefixCount = GetIntOption(args, "--prefix-count", 8);
        int commitGapCoalesceBytes = GetIntOption(args, "--commit-gap-coalesce-bytes", 16 * 1024);
        if (batches <= 0 || itemsPerBatch <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Eight-index same-identities batches and items per batch must be positive.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "Eight-index same-identities prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        File.Delete(path);

        DataKernelOptions options = CreateDesignPerfOptions(commitGapCoalesceBytes);
        Scalar8Scalar8Profile scalar8Scalar8Profile = Scalar8Scalar8Profile.Default32KiB;
        Scalar16Scalar8Profile scalar16Scalar8Profile = Scalar16Scalar8Profile.Default32KiB;
        Scalar8Scalar16Profile scalar8Scalar16Profile = Scalar8Scalar16Profile.Default32KiB;
        Scalar16Scalar16Profile scalar16Scalar16Profile = Scalar16Scalar16Profile.Default24KiB;
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        MultiIndexSameIdentitiesPlan[] plans = CreateEightIndexSameIdentitiesPlans();
        long rootCreateWrites = 0;
        long rootCreateBytes = 0;

        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(821), DataKernelTelemetryOptions.EnabledOptions))
        {
            int[] createOrder = [3, 0, 6, 1, 4, 7, 2, 5];
            for (int i = 0; i < createOrder.Length; i++)
            {
                MultiIndexSameIdentitiesPlan plan = plans[createOrder[i]];
                DataKernelCommitTelemetry rootCommit;
                if (plan.Shape == MultiIndexSameIdentitiesShape.SS88)
                {
                    (Scalar8Scalar8IndexHandle handle, RouterSnapshot root, DataKernelCommitTelemetry commit) = session.CreateScalar8Scalar8RootRouterIndex(CreateHarnessSlot(plan.SlotIndex, plan.Name, 0));
                    plan.Scalar8Scalar8Handle = handle;
                    plan.RootOffset = root.Offset;
                    rootCommit = commit;
                }
                else
                {
                    (RouterSnapshot root, DataKernelCommitTelemetry commit) = session.CreateRootRouterIndex(CreateHarnessSlot(plan.SlotIndex, plan.Name, 0));
                    plan.RootOffset = root.Offset;
                    rootCommit = commit;
                }

                rootCreateWrites += rootCommit.WriteCallCount;
                rootCreateBytes += rootCommit.BytesWritten;
            }

            ValidateDistinctEightIndexRoots(plans);

            int[] writeOrder = [6, 0, 3, 5, 1, 7, 4, 2];
            for (int i = 0; i < writeOrder.Length; i++)
            {
                MultiIndexSameIdentitiesPlan plan = plans[writeOrder[i]];
                plan.Telemetry = plan.Shape switch
                {
                    MultiIndexSameIdentitiesShape.SS88 => RunMultiIndexScalar8Scalar8Write(session, plan, batches, itemsPerBatch, prefixCount, sortedOrder),
                    MultiIndexSameIdentitiesShape.SS168 => RunScalar16Scalar8RoutedBulkWriteLoop(session, plan.RootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, scalar16Scalar8Profile, includeAttribution: false),
                    MultiIndexSameIdentitiesShape.SS816 => RunScalar8Scalar16RoutedBulkWriteLoop(session, plan.RootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, scalar8Scalar16Profile, includeAttribution: false),
                    MultiIndexSameIdentitiesShape.SS1616 => RunScalar16Scalar16RoutedBulkWriteLoop(session, plan.RootOffset, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, scalar16Scalar16Profile, includeAttribution: false),
                    _ => throw new InvalidDataException($"Unsupported eight-index shape {plan.Shape}.")
                };
            }
        }

        using (LibraDexFileSession reopened = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            ValidateEightIndexDirectory(reopened, plans);
            int[] validateOrder = [5, 2, 7, 4, 1, 6, 0, 3];
            for (int i = 0; i < validateOrder.Length; i++)
            {
                MultiIndexSameIdentitiesPlan plan = plans[validateOrder[i]];
                MultiIndexValidationCounts validation = plan.Shape switch
                {
                    MultiIndexSameIdentitiesShape.SS88 => ValidateEightIndexScalar8Scalar8Reopen(reopened, plan.RootOffset, scalar8Scalar8Profile, batches, itemsPerBatch, prefixCount, sortedOrder),
                    MultiIndexSameIdentitiesShape.SS168 => ValidateEightIndexScalar16Scalar8Reopen(reopened, plan.RootOffset, scalar16Scalar8Profile, batches, itemsPerBatch, prefixCount, sortedOrder),
                    MultiIndexSameIdentitiesShape.SS816 => ValidateEightIndexScalar8Scalar16Reopen(reopened, plan.RootOffset, scalar8Scalar16Profile, batches, itemsPerBatch, prefixCount, sortedOrder),
                    MultiIndexSameIdentitiesShape.SS1616 => ValidateEightIndexScalar16Scalar16Reopen(reopened, plan.RootOffset, scalar16Scalar16Profile, batches, itemsPerBatch, prefixCount, sortedOrder),
                    _ => throw new InvalidDataException($"Unsupported eight-index validation shape {plan.Shape}.")
                };
                plan.ValidatedItems = validation.Scalar8Scalar8ValidatedItems;
                plan.DistinctShelves = validation.Scalar8Scalar8DistinctShelves;
            }
        }

        long identityChecksum = CalculateSameIdentityChecksum(batches, itemsPerBatch, prefixCount, sortedOrder);
        long finalLength = new FileInfo(path).Length;
        string reportPath = WriteMultiIndexEightSameIdentitiesSanityReport(
            artifactDirectory,
            path,
            batches,
            itemsPerBatch,
            prefixCount,
            commitGapCoalesceBytes,
            rootCreateWrites,
            rootCreateBytes,
            identityChecksum,
            finalLength,
            plans);
        PrintMultiIndexEightSameIdentitiesSanityResult(rootCreateWrites, rootCreateBytes, identityChecksum, finalLength, plans);
        Console.WriteLine($"multi-index same-identities sanity ok path={Path.GetFullPath(path)}");
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }


    /// <summary>
    /// Diagnoses routed shelf target locality for public bulk-read ranges over a public batch-built `SS8-8` tree.<br/>
    /// The command explains whether coalescing can help by reporting distinct shelf targets, contiguous shelf runs, router targets, and duplicate route-target spans.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the target-locality report is written.</returns>
    private static int RunScalar8Scalar8PublicReadTargets(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-public-read-targets.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 100);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 1024);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        Scalar8Scalar8BulkWriteLocalityMode localityMode = ParseScalar8Scalar8BulkWriteLocalityMode(GetOption(args, "--locality-mode", "batch-major"));
        if (batches <= 0 || itemsPerBatch <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Public read-target batches and items per batch must be positive.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "Public read-target prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);
        File.Delete(path);

        DataKernelOptions options = CreateDesignPerfOptions();
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        using (Scalar8Scalar8Index created = Indexes.SS88.Create(
            path,
            DataKernelBackingKind.File,
            name: "public-read-targets",
            options: options,
            developerMetadata: CreateDesignPerfMetadata(94),
            telemetryOptions: DataKernelTelemetryOptions.EnabledOptions))
        {
            _ = RunScalar8Scalar8RoutedBulkWriteLoop(created, batches, itemsPerBatch, prefixCount, sortedOrder, batchOffset: 0, localityMode);
        }

        int middlePrefix = prefixCount / 2;
        int crossUpperPrefix = Math.Min(2, prefixCount - 1);
        Scalar8Scalar8PublicReadTargetResult[] results = new Scalar8Scalar8PublicReadTargetResult[5];
        using (LibraDexFileSession session = LibraDexFileSession.Open(path, options, DataKernelTelemetryOptions.EnabledOptions))
        {
            Scalar8Scalar8IndexHandle handle = session.GetScalar8Scalar8IndexHandle(0);
            results[0] = DiagnoseScalar8Scalar8PublicReadTargets(session, handle, "prefix 0", 0, 0);
            results[1] = DiagnoseScalar8Scalar8PublicReadTargets(session, handle, "prefix middle", middlePrefix, middlePrefix);
            results[2] = DiagnoseScalar8Scalar8PublicReadTargets(session, handle, "prefix last", prefixCount - 1, prefixCount - 1);
            results[3] = DiagnoseScalar8Scalar8PublicReadTargets(session, handle, "prefix 0-2", 0, crossUpperPrefix);
            results[4] = DiagnoseScalar8Scalar8PublicReadTargets(session, handle, "prefix 0-last", 0, prefixCount - 1);
        }

        string reportPath = WriteScalar8Scalar8PublicReadTargetsReport(artifactDirectory, batches, itemsPerBatch, prefixCount, localityMode, results);
        Console.WriteLine("ss8-8 public read targets");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"localityMode {localityMode}");
