    /// <summary>
    /// Measures public-wrapper routed `SS8-8` bulk-build file growth against live router and shelf structure.<br/>
    /// The setup uses `LibraDex.Indexes.SS88.Create` plus `Scalar8Scalar8Batch`, then reopens the file and traverses the live route graph from the public index handle.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when the public growth report is written.</returns>
    private static int RunScalar8Scalar8PublicGrowth(string[] args)
    {
        string path = GetOption(args, "--path", Path.Combine(@"T:\LibraDex", "ss8-8-public-growth.lbdx"));
        string artifactDirectory = GetOption(args, "--artifact-directory", Path.Combine("artifacts", "perf-runs"));
        int batches = GetIntOption(args, "--batches", 250);
        int itemsPerBatch = GetIntOption(args, "--items-per-batch", 1024);
        int prefixCount = GetIntOption(args, "--prefix-count", 16);
        int repeatCount = GetIntOption(args, "--repeat-count", 1);
        int shelfExtentSize = GetIntOption(args, "--shelf-size", Scalar8Scalar8Profile.Default32KiB.ShelfExtentSize);
        Scalar8Scalar8BulkWriteLocalityMode localityMode = ParseScalar8Scalar8BulkWriteLocalityMode(GetOption(args, "--locality-mode", "batch-major"));
        if (batches <= 0 || itemsPerBatch <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), "Public growth batches and items per batch must be positive.");
        }

        if (repeatCount <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(args), repeatCount, "Public growth repeat count must be positive.");
        }

        if (prefixCount <= 0 || prefixCount > 256)
        {
            throw new ArgumentOutOfRangeException(nameof(args), prefixCount, "Public growth prefix count must be between 1 and 256.");
        }

        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        Directory.CreateDirectory(artifactDirectory);

        DataKernelOptions options = CreateDesignPerfOptions();
        Scalar8Scalar8Profile profile = Scalar8Scalar8Profile.FromSupportedShelfExtentSize(shelfExtentSize);
        int[] sortedOrder = CreateScalar8Scalar8OrderVector(itemsPerBatch, Scalar8Scalar8InsertOrder.Sorted);
        Scalar8Scalar8PublicGrowthResult result = MeasureRepeatedScalar8Scalar8PublicGrowth(path, batches, itemsPerBatch, prefixCount, localityMode, sortedOrder, options, repeatCount, profile);

        string reportPath = WriteScalar8Scalar8PublicGrowthReport(artifactDirectory, batches, itemsPerBatch, prefixCount, localityMode, result);
        Console.WriteLine("ss8-8 public growth");
        Console.WriteLine($"batches {batches:N0}");
        Console.WriteLine($"itemsPerBatch {itemsPerBatch:N0}");
        Console.WriteLine($"prefixCount {prefixCount:N0}");
        Console.WriteLine($"repeatCount {repeatCount:N0}");
        Console.WriteLine($"localityMode {localityMode}");
        Console.WriteLine($"shelfSize {profile.ShelfExtentSize:N0}");
        PrintScalar8Scalar8PublicGrowth(result);
        Console.WriteLine($"report {Path.GetFullPath(reportPath)}");
        return 0;
    }


    /// <summary>
    /// Writes the current routed `SS8-8` range/scoop perf report and archives the previous current report by timestamp.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The report directory.</param>
    /// <param name="iterations">The configured iteration count.</param>
    /// <param name="rangeLength">The configured range length.</param>
    /// <param name="results">The measured range/scoop results.</param>
    /// <returns>The current report path.</returns>
    private static string WriteScalar8Scalar8RangeScoopPerfReport(
        string artifactDirectory,
        int iterations,
        int rangeLength,
        ReadOnlySpan<Scalar8Scalar8RangeScoopPerfResult> results)
    {
        return WriteScalar8Scalar8RangeScoopPerfReport(artifactDirectory, iterations, rangeLength, results, "ss8-8-range-scoop-perf", "SS8-8 Range Scoop Perf");
    }


    /// <summary>
    /// Writes a routed `SS8-8` range/scoop perf report and archives the previous current report by timestamp.<br/>
    /// The report key controls the current and timestamped filenames so focused probes can keep separate rolling baselines.<br/>
    /// The title is intentionally caller-supplied because wide/deep probes share table shape with the guarded range-scoop baseline but answer a different design question.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The report directory.</param>
    /// <param name="iterations">The configured iteration count.</param>
    /// <param name="rangeLength">The configured returned identity count.</param>
    /// <param name="results">The measured range/scoop results.</param>
    /// <param name="reportKey">The filename key used for current and timestamped reports.</param>
    /// <param name="title">The markdown report title.</param>
    /// <returns>The current report path.</returns>
    private static string WriteScalar8Scalar8RangeScoopPerfReport(
        string artifactDirectory,
        int iterations,
        int rangeLength,
        ReadOnlySpan<Scalar8Scalar8RangeScoopPerfResult> results,
        string reportKey,
        string title)
    {
        string currentPath = Path.Combine(artifactDirectory, $"{reportKey}-current.md");
        ArchiveCurrentReport(currentPath, reportKey);
        string timestamp = DateTimeOffset.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        string timestampPath = Path.Combine(artifactDirectory, $"{reportKey}-{timestamp}.md");

        StringBuilder builder = new();
        builder.AppendLine($"# {title} - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine($"- Iterations: `{iterations}`");
        builder.AppendLine($"- Range length: `{rangeLength}` identities");
        builder.AppendLine("- Scenario: same transformed-shelf right-side range, route lower/upper boundaries, read one shelf extent, copy identities.");
        builder.AppendLine();
        builder.AppendLine("| scenario | iterations | range | elapsed ms | ns/range | ns/identity | reads | backing reads | bytes | bytes/identity | checksum |");
        builder.AppendLine("| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8RangeScoopPerfResult result = results[i];
            double nsPerRange = result.Elapsed.TotalSeconds * 1_000_000_000d / result.Iterations;
            double nsPerIdentity = result.Elapsed.TotalSeconds * 1_000_000_000d / result.IdentityCount;
            double bytesPerIdentity = result.BytesRead / (double)result.IdentityCount;
            builder.AppendLine($"| {result.Name} | {result.Iterations} | {result.RangeLength} | {result.Elapsed.TotalMilliseconds:N3} | {nsPerRange:N2} | {nsPerIdentity:N2} | {result.ReadCallCount} | {result.BackingReadCallCount} | {result.BytesRead} | {bytesPerIdentity:N2} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- This is the first routed range/scoop primitive and intentionally supports one-shelf ranges only.");
        builder.AppendLine("- Both policies still read one shelf extent per range operation.");
        builder.AppendLine("- Arena-aware routing amortizes router arena cost across repeated same-shelf range operations.");

        File.WriteAllText(currentPath, builder.ToString());
        File.WriteAllText(timestampPath, builder.ToString());
        return currentPath;
    }


