    /// <summary>
    /// Measures one walked parent-route split after deterministic setup fills the target child-router shelf.<br/>
    /// The timed mutation uses the full `SS8-8` walked insert orchestrator and expects the parent-route refinement path.<br/>
    /// </summary>
    /// <param name="path">The sample file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <returns>The measured mutation sample.</returns>
    private static Scalar8Scalar8DesignPerfSample MeasureScalar8Scalar8DesignWalkedParentRouteSplit(string path, Scalar8Scalar8Profile profile)
    {
        CreateTransformSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int _, out int _);
        DataKernelOptions options = CreateDesignPerfOptions();
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(27), DataKernelTelemetryOptions.EnabledOptions);
        (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8pfpr", 0));
        _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x00]);
        const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
        const ulong secondByteFarRightBase = 0x00C0_0000_0000_0000UL;
        ulong transformKey = secondByteRightBase + 10_000UL;
        (
            _,
            _,
            long rightShelfOffset,
            _,
            int transformedRightCount,
            Scalar8Scalar8InsertResult transformResult,
            _) = session.SplitRoutedScalar8Scalar8ByShelfTransform(root.Offset, 0x00, 0x80, profile, transformKey, transformKey);
        if (rightShelfOffset == 0 || transformResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException("Design perf walked parent-route split setup did not transform.");
        }

        int fillCount = profile.MaxItemCount - transformedRightCount;
        for (int i = 0; i < fillCount; i++)
        {
            ulong fillKey = secondByteFarRightBase + (ulong)i;
            Scalar8Scalar8RoutedInsertResult fill = session.InsertWalkedRoutedScalar8Scalar8(root.Offset, profile, fillKey, fillKey, allowDuplicateKeys: true, maxRouterHops: 8);
            if (fill.Kind != Scalar8Scalar8RoutedInsertKind.WalkedNoSplit || fill.PrimaryOffset != rightShelfOffset)
            {
                throw new InvalidDataException("Design perf walked parent-route split setup did not fill the expected shelf.");
            }
        }

        _ = session.GetAndResetReadTelemetry();
        ulong splitKey = secondByteFarRightBase + 10_000UL;
        Stopwatch stopwatch = Stopwatch.StartNew();
        Scalar8Scalar8RoutedInsertResult result = session.InsertWalkedRoutedScalar8Scalar8(root.Offset, profile, splitKey, splitKey, allowDuplicateKeys: true, maxRouterHops: 8);
        stopwatch.Stop();
        if (result.Kind != Scalar8Scalar8RoutedInsertKind.WalkedParentRouteSplit)
        {
            throw new InvalidDataException("Design perf walked parent-route split scenario did not take the parent-route split path.");
        }

        return CreateDesignPerfSample(stopwatch, session.GetAndResetReadTelemetry(), result.Commit);
    }


