    /// <summary>
    /// Measures growth and slack for a root-prefix-visible `SS8-8` split.<br/>
    /// This shape rewrites the source shelf, appends one shelf, and rewrites the root router.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <returns>The measured growth/slack result.</returns>
    private static Scalar8Scalar8GrowthSlackResult MeasureScalar8Scalar8RootPrefixGrowthSlack(string path, Scalar8Scalar8Profile profile)
    {
        File.Delete(path);
        CreateRootPrefixSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int leftCount, out int rightCount);
        DataKernelOptions options = CreateDesignPerfOptions();
        long setupLength;
        long finalLength;
        DataKernelCommitTelemetry commit;
        int finalLeftCount;
        int finalRightCount;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(31), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8gsrp", 0));
            _ = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, keys, identities, [0x00, 0x80]);
            setupLength = GetFileLength(path);
            const ulong rightPrefixBase = 0x8000_0000_0000_0000UL;
            ulong insertedKey = rightPrefixBase + 10_000UL;
            (
                _,
                _,
                finalLeftCount,
                finalRightCount,
                _,
                commit) = session.SplitRoutedScalar8Scalar8ByRootPrefix(root.Offset, 0x00, 0x80, profile, insertedKey, insertedKey);
            finalLength = GetFileLength(path);
        }

        return CreateScalar8Scalar8GrowthSlackResult(
            "root-prefix split",
            setupLength,
            finalLength,
            routerCount: 1,
            shelfCount: 2,
            finalLeftCount,
            finalRightCount,
            profile,
            commit);
    }


