    /// <summary>
    /// Measures growth and slack for a walked deeper `SS8-8` transmorphic split.<br/>
    /// This shape reuses a full shelf below a child router as the next-depth router and appends two replacement shelves.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile.</param>
    /// <returns>The measured growth/slack result.</returns>
    private static Scalar8Scalar8GrowthSlackResult MeasureScalar8Scalar8WalkedTransformGrowthSlack(string path, Scalar8Scalar8Profile profile)
    {
        File.Delete(path);
        CreateDeeperTransformSplitVectors(profile, out ulong[] keys, out ulong[] identities, out int _, out int _);
        DataKernelOptions options = CreateDesignPerfOptions();
        long setupLength;
        long finalLength;
        DataKernelCommitTelemetry commit;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, CreateDesignPerfMetadata(33), DataKernelTelemetryOptions.EnabledOptions))
        {
            (RouterSnapshot root, _) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "ss8gswt", 0));
            _ = session.CreateScalar8Scalar8ShelfBehindChildRouter(root.Offset, 0x00, 0x00, profile, keys, identities);
            setupLength = GetFileLength(path);
            const ulong thirdByteRightBase = 0x0000_8000_0000_0000UL;
            ulong insertedKey = thirdByteRightBase + 10_000UL;
            Scalar8Scalar8RoutedInsertResult result = session.InsertWalkedRoutedScalar8Scalar8(root.Offset, profile, insertedKey, insertedKey, allowDuplicateKeys: true, maxRouterHops: 8);
            if (result.Kind != Scalar8Scalar8RoutedInsertKind.WalkedShelfTransformSplit)
            {
                throw new InvalidDataException("Growth/slack walked transform scenario did not take the expected split path.");
            }

            commit = result.Commit;
            finalLength = GetFileLength(path);
        }

        int finalLeftCount = profile.MaxItemCount / 2;
        int finalRightCount = profile.MaxItemCount - finalLeftCount + 1;
        return CreateScalar8Scalar8GrowthSlackResult(
            "walked transform split",
            setupLength,
            finalLength,
            routerCount: 3,
            shelfCount: 2,
            finalLeftCount,
            finalRightCount,
            profile,
            commit);
    }


    /// <summary>
    /// Gets the current file length for a scenario file after refreshing file-system metadata.<br/>
    /// The harness uses this immediately after commits to make append growth visible without adding `DataKernel` file-length APIs yet.<br/>
    /// </summary>
    /// <param name="path">The file path to inspect.</param>
    /// <returns>The current file length in bytes.</returns>
    private static long GetFileLength(string path)
    {
        FileInfo info = new(path);
        info.Refresh();
        return info.Length;
    }



    /// <summary>
    /// Validates walked no-split insert when the root route points directly to an `SS8-8` shelf.<br/>
    /// Expected read shape is one router page, one 4-byte classifier read, and one shelf extent read.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile to validate.</param>
    private static void RunScalar8Scalar8WalkedInsertOneLevel(string path, Scalar8Scalar8Profile profile)
    {
        const int itemCount = 512;
        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexWalkedInsertOne",
            DevCustomText: "ss8-8 walked insert one",
            DevGuid: Guid.Parse("69587ef3-0f6c-45a7-ab32-fd1cd97e8665"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 13);

        ulong insertedKey = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)(itemCount + 128));
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions);
        IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8wlk0", 0);
        (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
        PrintCommit("ss8-8 walked one root create", rootCommit);
        (long shelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar8ShelfAndLinkRootRoute(root.Offset, 0x00, profile, itemCount);
        PrintCommit("ss8-8 walked one shelf link", linkCommit);
        ValidateScalar8Scalar8RouteLinkCommit(linkCommit, profile, allocatorMetadataPages: 2);
        _ = session.GetAndResetReadTelemetry();

        Scalar8Scalar8RoutedInsertResult result = session.InsertWalkedRoutedScalar8Scalar8NoSplit(
            root.Offset,
            profile,
            insertedKey,
            insertedKey,
            allowDuplicateKeys: true,
            maxRouterHops: 8);
        if (result.Kind != Scalar8Scalar8RoutedInsertKind.WalkedNoSplit || result.PrimaryOffset != shelfOffset || result.InsertResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected walked one-level no-split insert at shelf {shelfOffset}, got {result.Kind}/{result.InsertResult} offset {result.PrimaryOffset}.");
        }

        DataKernelReadTelemetry readTelemetry = session.GetAndResetReadTelemetry();
        PrintRead("ss8-8 walked one insert read", readTelemetry);
        if (readTelemetry.ReadCallCount != 3 || readTelemetry.BytesRead != RouterLayout.Size + sizeof(uint) + profile.ShelfExtentSize)
        {
            throw new InvalidDataException("Walked one-level insert should read one router page, one 4-byte classifier magic, and one shelf extent.");
        }

        PrintCommit("ss8-8 walked one insert commit", result.Commit);
        ValidateScalar8Scalar8RouteInsertCommit(result.Commit, profile);
        ValidateRoutedScalar8Scalar8Shelf(session, root.Offset, shelfOffset, profile, itemCount + 1, insertedKey, insertedKey);
    }


    /// <summary>
    /// Validates walked no-split insert when the root route points to a child router and the child route points to an `SS8-8` shelf.<br/>
    /// Expected read shape is two router pages, two 4-byte classifier reads, and one shelf extent read.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile to validate.</param>
    private static void RunScalar8Scalar8WalkedInsertTwoLevel(string path, Scalar8Scalar8Profile profile)
    {
        int leftCount = profile.MaxItemCount / 2;
        int rightCount = profile.MaxItemCount - leftCount;
        ulong[] encodedKeys = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentities = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            ulong encoded = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)i);
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            ulong encoded = secondByteRightBase + (ulong)i;
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexWalkedInsertTwo",
            DevCustomText: "ss8-8 walked insert two",
            DevGuid: Guid.Parse("892d7369-6b6f-4da7-bb95-adf2c5055899"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 14);

        ulong splitInsertedKey = secondByteRightBase + 10_000UL;
        ulong insertedKey = secondByteRightBase + 20_000UL;
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions);
        IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8wlk1", 0);
        (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
        PrintCommit("ss8-8 walked two root create", rootCommit);
        (long sourceShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, encodedKeys, encodedIdentities, [0x00]);
        PrintCommit("ss8-8 walked two shelf link", linkCommit);
        ValidateScalar8Scalar8RouteLinkCommit(linkCommit, profile, allocatorMetadataPages: 2);
        _ = session.GetAndResetReadTelemetry();

        (
            long childRouterOffset,
            _,
            long rightShelfOffset,
            _,
            _,
            Scalar8Scalar8InsertResult splitResult,
            DataKernelCommitTelemetry transformCommit) = session.SplitRoutedScalar8Scalar8ByShelfTransform(
                root.Offset,
                0x00,
                0x80,
                profile,
                splitInsertedKey,
                splitInsertedKey);
        if (childRouterOffset != sourceShelfOffset || splitResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException("Walked two-level insert setup transform did not reuse the source shelf offset.");
        }

        PrintRead("ss8-8 walked two transform read", session.GetAndResetReadTelemetry());
        PrintCommit("ss8-8 walked two transform commit", transformCommit);
        ValidateScalar8Scalar8TransformCommit(transformCommit, profile, allocatorMetadataPages: 1);
        _ = session.GetAndResetReadTelemetry();

        Scalar8Scalar8RoutedInsertResult result = session.InsertWalkedRoutedScalar8Scalar8NoSplit(
            root.Offset,
            profile,
            insertedKey,
            insertedKey,
            allowDuplicateKeys: true,
            maxRouterHops: 8);
        if (result.Kind != Scalar8Scalar8RoutedInsertKind.WalkedNoSplit || result.PrimaryOffset != rightShelfOffset || result.InsertResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected walked two-level no-split insert at shelf {rightShelfOffset}, got {result.Kind}/{result.InsertResult} offset {result.PrimaryOffset}.");
        }

        DataKernelReadTelemetry readTelemetry = session.GetAndResetReadTelemetry();
        PrintRead("ss8-8 walked two insert read", readTelemetry);
        ValidateWalkedTwoLevelInsertReadTelemetry("SS8-8", readTelemetry, profile.ShelfExtentSize);

        PrintCommit("ss8-8 walked two insert commit", result.Commit);
        ValidateScalar8Scalar8RouteInsertCommit(result.Commit, profile);
        ValidateTwoLevelRoutedScalar8Scalar8ShelfShape(session, root.Offset, 0x00, 0x80, childRouterOffset, rightShelfOffset, profile, rightCount + 2, insertedKey, insertedKey);
    }


