        if (result.Kind != Scalar8Scalar16RoutedInsertKind.WalkedParentRouteSplit || result.PrimaryOffset != childRouterOffset || result.LeftShelfOffset != rightShelfOffset || result.RightShelfOffset == 0 || result.InsertResult != Scalar8Scalar16InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected unified SS8-16 walked parent-route decision preserving shelf {rightShelfOffset}, got {result.Kind}/{result.InsertResult} primary {result.PrimaryOffset} left {result.LeftShelfOffset} right {result.RightShelfOffset}.");
