    /// <summary>
    /// Validates the unified walked `SS16-16` decision path when a full walked shelf can split by refining its parent router routes.<br/>
    /// The expected outcome is `WalkedParentRouteSplit`, preserving the old shelf offset as one split side and appending one shelf.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS16-16` shelf profile to validate.</param>
    private static void RunScalar16Scalar16WalkedDecisionParentRoute(string path, Scalar16Scalar16Profile profile)
    {
        int leftCount = profile.MaxItemCount / 2;
        int rightCount = profile.MaxItemCount - leftCount;
        ulong[] keyHighs = new ulong[profile.MaxItemCount];
        ulong[] keyLows = new ulong[profile.MaxItemCount];
        ulong[] identityHighs = new ulong[profile.MaxItemCount];
        ulong[] identityLows = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            keyHighs[index] = 0;
            keyLows[index] = (ulong)i;
            identityHighs[index] = 0;
            identityLows[index] = (ulong)i;
            index++;
        }

        const ulong secondByteRightBaseHigh = 0x0080_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            keyHighs[index] = secondByteRightBaseHigh;
            keyLows[index] = (ulong)i;
            identityHighs[index] = 0;
            identityLows[index] = (ulong)i;
            index++;
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexS1616DecisionParent",
            DevCustomText: "ss16-16 walked decision parent",
            DevGuid: Guid.Parse("31636821-eae2-40ce-ba2c-68ae3f0e2f69"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 103);

        const ulong secondByteFarRightBaseHigh = 0x00C0_0000_0000_0000UL;
        ulong transformInsertedKeyHigh = secondByteRightBaseHigh;
        const ulong transformInsertedKeyLow = 10_000UL;
        const ulong transformInsertedIdentityHigh = 1;
        const ulong transformInsertedIdentityLow = 10_000UL;
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions);
        (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(CreateHarnessSlot(0, "s1616wd2", 0));
        PrintCommit("ss16-16 decision parent root create", rootCommit);
        (long sourceShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar16Scalar16ShelfAndLinkRootRoutes(root.Offset, profile, keyHighs, keyLows, identityHighs, identityLows, [0x00]);
        PrintCommit("ss16-16 decision parent shelf link", linkCommit);
        ValidateScalar16Scalar16RouteLinkCommit(linkCommit, profile);

        (
            long childRouterOffset,
            _,
            long rightShelfOffset,
            _,
            int transformedRightCount,
            Scalar16Scalar16InsertResult transformResult,
            DataKernelCommitTelemetry transformCommit) = session.SplitRoutedScalar16Scalar16ByShelfTransform(root.Offset, 0x00, 0x80, profile, transformInsertedKeyHigh, transformInsertedKeyLow, transformInsertedIdentityHigh, transformInsertedIdentityLow);
        if (childRouterOffset != sourceShelfOffset || transformResult != Scalar16Scalar16InsertResult.Inserted)
        {
            throw new InvalidDataException("Unified SS16-16 parent decision setup transform did not reuse the source shelf offset.");
        }

        PrintCommit("ss16-16 decision parent transform", transformCommit);
        ValidateScalar16Scalar16TransformCommit(transformCommit, profile);

        int fillCount = profile.MaxItemCount - transformedRightCount;
        for (int i = 0; i < fillCount; i++)
        {
            (long fillShelfOffset, Scalar16Scalar16InsertResult fillResult, _) = session.InsertWalkedRoutedScalar16Scalar16NoSplit(
                root.Offset,
                profile,
                secondByteFarRightBaseHigh,
                (ulong)i,
                encodedIdentityHigh: 1,
                encodedIdentityLow: (ulong)i,
                allowDuplicateKeys: true,
                maxRouterHops: 8);
            if (fillShelfOffset != rightShelfOffset || fillResult != Scalar16Scalar16InsertResult.Inserted)
            {
                throw new InvalidDataException("Unified SS16-16 parent decision setup did not fill the expected shelf.");
            }
        }

        _ = session.GetAndResetReadTelemetry();
        ulong splitKeyHigh = secondByteFarRightBaseHigh;
        const ulong splitKeyLow = 10_000UL;
        const ulong splitIdentityHigh = 1;
        const ulong splitIdentityLow = 10_000UL;
        Scalar16Scalar16RoutedInsertResult result = session.InsertWalkedRoutedScalar16Scalar16(
            root.Offset,
            profile,
            splitKeyHigh,
            splitKeyLow,
            splitIdentityHigh,
            splitIdentityLow,
            allowDuplicateKeys: true,
            maxRouterHops: 8);
        if (result.Kind != Scalar16Scalar16RoutedInsertKind.WalkedParentRouteSplit || result.PrimaryOffset != childRouterOffset || result.LeftShelfOffset != rightShelfOffset || result.RightShelfOffset == 0 || result.InsertResult != Scalar16Scalar16InsertResult.Inserted)
        {
            throw new InvalidDataException($"Expected unified SS16-16 walked parent-route decision preserving shelf {rightShelfOffset}, got {result.Kind}/{result.InsertResult} primary {result.PrimaryOffset} left {result.LeftShelfOffset} right {result.RightShelfOffset}.");
        }

        PrintRead("ss16-16 decision parent read", session.GetAndResetReadTelemetry());
        PrintCommit("ss16-16 decision parent commit", result.Commit);
        ValidateScalar16Scalar16RouteSplitCommit(result.Commit, profile);
        ValidateTwoLevelRoutedScalar16Scalar16ShelfShape(session, root.Offset, 0x00, 0xC0, childRouterOffset, result.RightShelfOffset, profile, fillCount + 1, splitKeyHigh, splitKeyLow, splitIdentityHigh, splitIdentityLow);
    }


    /// <summary>
    /// Validates read telemetry for a two-level classified route walk.<br/>
    /// Legal shapes include two plain router pages plus classifier magics and router-arena first-touch variants for transformed child routers.<br/>
    /// </summary>
    /// <param name="shapeName">The compact shape label used in failure messages.</param>
    /// <param name="readTelemetry">The captured read telemetry for the classified route walk.</param>
    /// <param name="shelfExtentSize">The profiled shelf extent size used to derive the transformed child-router arena size.</param>
    /// <exception cref="InvalidDataException">Thrown when the read telemetry does not match a supported two-level route-walker shape.</exception>
    private static void ValidateTwoLevelRouteWalkerReadTelemetry(
        string shapeName,
        DataKernelReadTelemetry readTelemetry,
        int shelfExtentSize)
    {
        int routerArenaReadSize = Math.Min(shelfExtentSize, 64 * 1024);
        const int classifierBytes = sizeof(uint) * 2;
        bool plainRouterRead = readTelemetry.ReadCallCount == 4 && readTelemetry.BytesRead == (RouterLayout.Size * 2) + classifierBytes;
        bool rootWarmArenaDiscoveryRead = readTelemetry.ReadCallCount == 4 && readTelemetry.BytesRead == RouterLayout.Size + routerArenaReadSize + classifierBytes;
        bool twoRouterArenaSingleClassifierRead = readTelemetry.ReadCallCount == 4 && readTelemetry.BytesRead == (RouterLayout.Size * 2) + routerArenaReadSize + sizeof(uint);
        bool coldArenaDiscoveryRead = readTelemetry.ReadCallCount == 5 && readTelemetry.BytesRead == (RouterLayout.Size * 2) + routerArenaReadSize + classifierBytes;
        if (!plainRouterRead && !rootWarmArenaDiscoveryRead && !twoRouterArenaSingleClassifierRead && !coldArenaDiscoveryRead)
        {
            throw new InvalidDataException($"Two-level {shapeName} route walker should read two router pages plus classifier magics, or a transformed child-router arena plus classifier magics.");
        }
    }


    /// <summary>
    /// Validates read telemetry for a walked two-level no-split insert.<br/>
    /// Legal shapes include two plain router pages plus classifier magics plus shelf read, and transformed child-router arena first-touch variants plus shelf read.<br/>
    /// A previously classified target can omit one 4-byte classifier read while retaining the same router and shelf reads.<br/>
    /// </summary>
    /// <param name="shapeName">The compact shape label used in failure messages.</param>
    /// <param name="readTelemetry">The captured read telemetry for the walked insert.</param>
    /// <param name="shelfExtentSize">The profiled shelf extent size used for the shelf read and transformed child-router arena size.</param>
    /// <exception cref="InvalidDataException">Thrown when the read telemetry does not match a supported walked insert shape.</exception>
    private static void ValidateWalkedTwoLevelInsertReadTelemetry(
        string shapeName,
        DataKernelReadTelemetry readTelemetry,
        int shelfExtentSize)
    {
        int routerArenaReadSize = Math.Min(shelfExtentSize, 64 * 1024);
        const int classifierBytes = sizeof(uint) * 2;
        bool plainRouterRead = readTelemetry.ReadCallCount == 5 && readTelemetry.BytesRead == (RouterLayout.Size * 2) + classifierBytes + shelfExtentSize;
        bool rootWarmArenaDiscoveryRead = readTelemetry.ReadCallCount == 5 && readTelemetry.BytesRead == RouterLayout.Size + routerArenaReadSize + classifierBytes + shelfExtentSize;
        bool coldArenaSingleClassifierRead = readTelemetry.ReadCallCount == 5 && readTelemetry.BytesRead == (RouterLayout.Size * 2) + routerArenaReadSize + sizeof(uint) + shelfExtentSize;
        bool coldArenaDiscoveryRead = readTelemetry.ReadCallCount == 6 && readTelemetry.BytesRead == (RouterLayout.Size * 2) + routerArenaReadSize + classifierBytes + shelfExtentSize;
        if (!plainRouterRead && !rootWarmArenaDiscoveryRead && !coldArenaSingleClassifierRead && !coldArenaDiscoveryRead)
        {
            throw new InvalidDataException($"Walked two-level {shapeName} insert should read route pages or a transformed child-router arena, two classifier magics, and one shelf extent.");
        }
    }


    /// <summary>
