    /// <summary>
    /// Validates classified route walking from a root router through one child router to an `SS8-8` shelf.<br/>
    /// Expected read shape is two full router pages plus two 4-byte target classifier reads.<br/>
    /// </summary>
    /// <param name="path">The scenario file path.</param>
    /// <param name="profile">The `SS8-8` shelf profile to validate.</param>
    private static void RunScalar8Scalar8RouteWalkerTwoLevel(string path, Scalar8Scalar8Profile profile)
    {
        int leftCount = profile.MaxItemCount / 2;
        int rightCount = profile.MaxItemCount - leftCount;
        ulong[] encodedKeys = new ulong[profile.MaxItemCount];
        ulong[] encodedIdentities = new ulong[profile.MaxItemCount];
        int index = 0;
        for (int i = 0; i < leftCount; i++)
        {
            ulong encoded = Scalar8Scalar8Layout.EncodeUnsignedScalar8((ulong)i);
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        const ulong secondByteRightBase = 0x0080_0000_0000_0000UL;
        for (int i = 0; i < rightCount; i++)
        {
            ulong encoded = secondByteRightBase + (ulong)i;
            encodedKeys[index] = encoded;
            encodedIdentities[index] = encoded;
            index++;
        }

        DataKernelOptions options = new(
            AppendBufferSize: DefaultAppendBufferSize,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);

        SuperblockDeveloperMetadata metadata = new(
            DevIdentity: "LibraDexRouteWalkerTwo",
            DevCustomText: "ss8-8 route walker two",
            DevGuid: Guid.Parse("5c5f9b9e-45e9-47d1-b2ac-cb2d0fa8518a"),
            DevDate1UtcTicks: 1,
            DevDate2UtcTicks: 2,
            DevNumber: 12);

        ulong insertedKey = secondByteRightBase + 10_000UL;
        using LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions);
        IndexDirectorySlotSnapshot slotRequest = CreateHarnessSlot(0, "ss8walk2", 0);
        (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slotRequest);
        PrintCommit("ss8-8 walker two root create", rootCommit);
        (long sourceShelfOffset, DataKernelCommitTelemetry linkCommit) = session.CreateScalar8Scalar8ShelfAndLinkRootRoutes(root.Offset, profile, encodedKeys, encodedIdentities, [0x00]);
        PrintCommit("ss8-8 walker two shelf link", linkCommit);
        ValidateScalar8Scalar8RouteLinkCommit(linkCommit, profile, allocatorMetadataPages: 2);
        _ = session.GetAndResetReadTelemetry();

        (
            long childRouterOffset,
            _,
            long rightShelfOffset,
            _,
            _,
            Scalar8Scalar8InsertResult splitResult,
            DataKernelCommitTelemetry transformCommit) = session.SplitRoutedScalar8Scalar8ByShelfTransform(
                root.Offset,
                0x00,
                0x80,
                profile,
                insertedKey,
                insertedKey);
        if (childRouterOffset != sourceShelfOffset || splitResult != Scalar8Scalar8InsertResult.Inserted)
        {
            throw new InvalidDataException("Route walker two-level setup transform did not reuse the source shelf offset.");
        }

        PrintRead("ss8-8 walker two transform read", session.GetAndResetReadTelemetry());
        PrintCommit("ss8-8 walker two transform commit", transformCommit);
        ValidateScalar8Scalar8TransformCommit(transformCommit, profile, allocatorMetadataPages: 1);
        _ = session.GetAndResetReadTelemetry();

        Scalar8Scalar8RouteTarget target = session.WalkScalar8Scalar8RouteTarget(root.Offset, insertedKey, maxRouterHops: 8);
        if (target.Kind != Scalar8Scalar8RouteTargetKind.Shelf || target.Offset != rightShelfOffset || target.RouterDepth != 1)
        {
            throw new InvalidDataException($"Expected two-level walker shelf target {rightShelfOffset}, got {target.Kind} offset {target.Offset} depth {target.RouterDepth}.");
        }

        DataKernelReadTelemetry readTelemetry = session.GetAndResetReadTelemetry();
        PrintRead("ss8-8 walker two read", readTelemetry);
        ValidateTwoLevelRouteWalkerReadTelemetry("SS8-8", readTelemetry, profile.ShelfExtentSize);
    }


