    /// <param name="label">The diagnostic label for the commit.</param>
    /// <param name="backing">The backing mode used by the DataKernel.</param>
    /// <param name="telemetry">The commit telemetry to validate.</param>
    /// <param name="profile">The `SS16-16` shelf profile.</param>
    /// <exception cref="InvalidDataException">Thrown when the commit shape drifts from one fixed shelf extent.</exception>
    private static void ValidateScalar16Scalar16CommitShape(string label, DataKernelBackingKind backing, DataKernelCommitTelemetry telemetry, Scalar16Scalar16Profile profile)
    {
        PrintCommit(label, telemetry);
        if (telemetry.SetLengthCallCount != 0)
        {
            throw new InvalidDataException($"{label} used SetLength.");
        }

        if (telemetry.BytesWritten != profile.ShelfExtentSize)
        {
            throw new InvalidDataException($"{label} wrote {telemetry.BytesWritten} bytes instead of one SS16-16 shelf.");
        }

        if (backing == DataKernelBackingKind.File && telemetry.WriteCallCount != 1)
        {
            throw new InvalidDataException($"{label} expected one file write call, got {telemetry.WriteCallCount}.");
        }
    }


    private static RouteStressResult RunCombinedRouteStress(string path, int depth)
    {
        File.Delete(path);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);

        DataKernelOptions options = new(DefaultAppendBufferSize, 0, false, 512);
        SuperblockDeveloperMetadata metadata = CreateRouteStressMetadata("combined");
        const long finalTarget = 0x0070_0000;

        Stopwatch watch = Stopwatch.StartNew();
        DataKernelCommitTelemetry commit;
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slot = CreateHarnessSlot(0, "combined", 0);
            (RouteChainCreationResult chain, DataKernelCommitTelemetry chainCommit) = session.CreateRouteChainIndexCombined(slot, depth, finalTarget);
            commit = chainCommit;
            long actual = RoutePersistedChain(session, chain.RootOffset, CreateRepeatedKey(depth, 0x41), depth + 1);
            if (actual != finalTarget)
            {
                throw new InvalidDataException("Combined route chain did not reach the expected final target.");
            }
        }

        watch.Stop();
        return new RouteStressResult(1, commit.WriteCallCount, commit.BytesWritten, commit.SetLengthCallCount, watch.Elapsed, finalTarget);
    }


    private static RouteStressResult RunSeparatedRouteStress(string path, int depth)
    {
        File.Delete(path);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);

        DataKernelOptions options = new(DefaultAppendBufferSize, 0, false, 512);
        SuperblockDeveloperMetadata metadata = CreateRouteStressMetadata("separated");
        const long finalTarget = 0x0070_0000;
        long writes = 0;
        long bytes = 0;
        long setLength = 0;
        int commits = 0;

        Stopwatch watch = Stopwatch.StartNew();
        using (LibraDexFileSession session = LibraDexFileSession.Initialize(path, options, metadata, DataKernelTelemetryOptions.EnabledOptions))
        {
            IndexDirectorySlotSnapshot slot = CreateHarnessSlot(0, "separated", 0);
            (RouterSnapshot root, DataKernelCommitTelemetry rootCommit) = session.CreateRootRouterIndex(slot);
            AddCommit(rootCommit, ref commits, ref writes, ref bytes, ref setLength);

            long previousOffset = root.Offset;
            for (int i = 1; i < depth; i++)
            {
                RouterRouteSnapshot[] routes = [new RouterRouteSnapshot(0x41, 0x41, 0)];
                (RouterSnapshot child, DataKernelCommitTelemetry childCommit) = session.CreateCompressedRouter(1, checked((ushort)i), 16, 1, routes);
                AddCommit(childCommit, ref commits, ref writes, ref bytes, ref setLength);

                int routeIndex = i == 1 ? 0x41 : 0;
                DataKernelCommitTelemetry linkCommit = session.UpdateRouterRoute(previousOffset, routeIndex, 0x41, 0x41, child.Offset);
                AddCommit(linkCommit, ref commits, ref writes, ref bytes, ref setLength);
                previousOffset = child.Offset;
            }

            DataKernelCommitTelemetry finalCommit = session.UpdateRouterRoute(previousOffset, depth == 1 ? 0x41 : 0, 0x41, 0x41, finalTarget);
            AddCommit(finalCommit, ref commits, ref writes, ref bytes, ref setLength);

            long actual = RoutePersistedChain(session, root.Offset, CreateRepeatedKey(depth, 0x41), depth + 1);
            if (actual != finalTarget)
            {
                throw new InvalidDataException("Separated route chain did not reach the expected final target.");
            }
        }

        watch.Stop();
        return new RouteStressResult(commits, writes, bytes, setLength, watch.Elapsed, finalTarget);
    }


    private static SuperblockDeveloperMetadata CreateRouteStressMetadata(string name)
    {
        return new SuperblockDeveloperMetadata(name, "route stress", Guid.Parse("ad7cd340-47e3-463d-9dd4-3da9ecfef428"), 1, 2, 3);
    }


    /// <summary>
    /// Prepares a rotating current report path and archives the previous current report when present.<br/>
    /// Report builders keep their content local while sharing the common directory/create/archive boilerplate.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="currentFileName">The current report file name.</param>
    /// <param name="archivePrefix">The archive file prefix used by <see cref="ArchiveCurrentReport(string, string)"/>.</param>
    /// <returns>The prepared current report path.</returns>
    private static string PrepareCurrentReport(
        string artifactDirectory,
        string currentFileName,
        string archivePrefix)
    {
        Directory.CreateDirectory(artifactDirectory);
        string reportPath = Path.Combine(artifactDirectory, currentFileName);
        ArchiveCurrentReport(reportPath, archivePrefix);
        return reportPath;
    }


    /// <summary>
    /// Writes a generated markdown report and returns the path for caller output.<br/>
    /// This keeps report writers focused on content instead of repeating the same final write and return pair.<br/>
    /// </summary>
    /// <param name="reportPath">The report path to write.</param>
    /// <param name="builder">The generated report content.</param>
    /// <returns>The written report path.</returns>
    private static string WriteReport(string reportPath, StringBuilder builder)
    {
        File.WriteAllText(reportPath, builder.ToString());
        return reportPath;
    }


    /// <summary>
    /// Writes the rotating `SS8-8` design-performance report and archives the previous current report.<br/>
    /// The report captures isolated routed mutation costs before full bulk-load and deeper split orchestration exist.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="runs">The number of samples per scenario.</param>
    /// <param name="profile">The `SS8-8` shelf profile used by the measured scenarios.</param>
    /// <param name="results">The measured scenario results.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar8Scalar8DesignPerfReport(
        string artifactDirectory,
        int runs,
        Scalar8Scalar8Profile profile,
        Scalar8Scalar8DesignPerfResult[] results)
    {
        string reportPath = PrepareCurrentReport(artifactDirectory, "ss8-8-design-perf-current.md", "ss8-8-design-perf");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# LibraDex SS8-8 Design Perf - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Runs per scenario: `{runs}`");
        builder.AppendLine($"- Shelf size: `{profile.ShelfExtentSize}` bytes");
        builder.AppendLine($"- Max items per shelf: `{profile.MaxItemCount}`");
        builder.AppendLine("- Each sample uses a fresh `.lbdx` file and deterministic setup.");
        builder.AppendLine("- Measured elapsed time covers only the target mutation call, not setup.");
        builder.AppendLine("- Syscall-shape columns are averaged across samples and should be exact for stable scenarios.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | avg ms | median ms | min ms | max ms | sd ms | reads | bytes/read | writes | bytes/write | setlen |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8DesignPerfResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.AverageMilliseconds:F4} | {result.MedianMilliseconds:F4} | {result.MinMilliseconds:F4} | {result.MaxMilliseconds:F4} | {result.StandardDeviationMilliseconds:F4} | {result.AverageReadCalls:F2} | {result.AverageBytesRead:F0} | {result.AverageWriteCalls:F2} | {result.AverageBytesWritten:F0} | {result.AverageSetLengthCalls:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Notes");
        builder.AppendLine();
        builder.AppendLine("- Direct one-level no-split is the current lowest-cost routed mutation shape.");
        builder.AppendLine("- Direct two-level no-split measures the specialized path after a known child route.");
        builder.AppendLine("- Walked two-level no-split measures the general classified walker path and should be compared against the direct two-level row.");
        builder.AppendLine("- Split rows show immediate structural mutation cost, not amortized bulk-load throughput.");

        return WriteReport(reportPath, builder);
    }


    /// <summary>
    /// Writes the rotating `SS16-8` design-performance comparison report and archives the previous current report.<br/>
    /// The report compares only scenarios implemented for both `SS8-8` and `SS16-8` so widened-key overhead is visible before further route-walker duplication.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="runs">The number of fresh-file samples per scenario.</param>
    /// <param name="ss88Profile">The `SS8-8` profile used by baseline rows.</param>
    /// <param name="ss168Profile">The `SS16-8` profile used by widened-key rows.</param>
    /// <param name="ss88Results">The measured `SS8-8` baseline rows.</param>
    /// <param name="ss168Results">The measured `SS16-8` widened-key rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar16Scalar8DesignPerfReport(
        string artifactDirectory,
        int runs,
        Scalar8Scalar8Profile ss88Profile,
        Scalar16Scalar8Profile ss168Profile,
        Scalar8Scalar8DesignPerfResult[] ss88Results,
        Scalar8Scalar8DesignPerfResult[] ss168Results)
    {
        string reportPath = PrepareCurrentReport(artifactDirectory, "ss16-8-design-perf-current.md", "ss16-8-design-perf");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# LibraDex SS16-8 Design Perf - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Runs per scenario: `{runs}`");
        builder.AppendLine($"- SS8-8 shelf size: `{ss88Profile.ShelfExtentSize}` bytes; max items: `{ss88Profile.MaxItemCount}`");
        builder.AppendLine($"- SS16-8 shelf size: `{ss168Profile.ShelfExtentSize}` bytes; max items: `{ss168Profile.MaxItemCount}`");
        builder.AppendLine("- Each sample uses a fresh `.lbdx` file and deterministic setup.");
        builder.AppendLine("- Measured elapsed time covers only the target mutation call, not setup.");
        builder.AppendLine("- Scenario set includes direct rooted mutations and walked orchestrator mutations implemented for both shapes.");
        builder.AppendLine();
        builder.AppendLine("## Comparison");
        builder.AppendLine();
        builder.AppendLine("| scenario | ss8 median ms | ss16 median ms | median delta % | ss8 avg ms | ss16 avg ms | ss8 min/max/sd | ss16 min/max/sd | ss8 reads | ss16 reads | ss8 read bytes | ss16 read bytes | ss8 writes | ss16 writes | ss8 write bytes | ss16 write bytes | ss8 setlen | ss16 setlen |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < ss168Results.Length; i++)
        {
            Scalar8Scalar8DesignPerfResult ss88 = ss88Results[i];
            Scalar8Scalar8DesignPerfResult ss168 = ss168Results[i];
            double deltaPercent = ss88.MedianMilliseconds == 0 ? 0 : ((ss168.MedianMilliseconds - ss88.MedianMilliseconds) / ss88.MedianMilliseconds) * 100.0;
            string ss88Spread = string.Create(CultureInfo.InvariantCulture, $"{ss88.MinMilliseconds:F4}/{ss88.MaxMilliseconds:F4}/{ss88.StandardDeviationMilliseconds:F4}");
            string ss168Spread = string.Create(CultureInfo.InvariantCulture, $"{ss168.MinMilliseconds:F4}/{ss168.MaxMilliseconds:F4}/{ss168.StandardDeviationMilliseconds:F4}");
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {ss168.Name} | {ss88.MedianMilliseconds:F4} | {ss168.MedianMilliseconds:F4} | {deltaPercent:F2} | {ss88.AverageMilliseconds:F4} | {ss168.AverageMilliseconds:F4} | {ss88Spread} | {ss168Spread} | {ss88.AverageReadCalls:F2} | {ss168.AverageReadCalls:F2} | {ss88.AverageBytesRead:F0} | {ss168.AverageBytesRead:F0} | {ss88.AverageWriteCalls:F2} | {ss168.AverageWriteCalls:F2} | {ss88.AverageBytesWritten:F0} | {ss168.AverageBytesWritten:F0} | {ss88.AverageSetLengthCalls:F2} | {ss168.AverageSetLengthCalls:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Notes");
        builder.AppendLine();
        builder.AppendLine("- SS16-8 doubles key width and lowers max items per 32 KiB shelf, so split rows compare equivalent structural shapes rather than equal item counts.");
        builder.AppendLine("- Syscall and byte columns should stay shape-equivalent for matching structural mutations; elapsed drift primarily points at route walking, shelf CPU, and tuple movement.");
        builder.AppendLine("- Walked rows use each shape's full walked insert orchestrator rather than isolated split primitives.");

        return WriteReport(reportPath, builder);
    }


    /// <summary>
