        builder.AppendLine("- Measured elapsed time covers only the target mutation call, not setup.");
        builder.AppendLine("- Scenario set includes direct rooted mutations and walked orchestrator mutations implemented for all three shapes.");
        builder.AppendLine();
        builder.AppendLine("## Comparison");
        builder.AppendLine();
        builder.AppendLine("| scenario | ss8 median ms | ss16 median ms | fs32 median ms | fs32 vs ss8 % | fs32 vs ss16 % | ss8 avg ms | ss16 avg ms | fs32 avg ms | ss8 min/max/sd | ss16 min/max/sd | fs32 min/max/sd | ss8 reads | ss16 reads | fs32 reads | ss8 read bytes | ss16 read bytes | fs32 read bytes | ss8 writes | ss16 writes | fs32 writes | ss8 write bytes | ss16 write bytes | fs32 write bytes | ss8 setlen | ss16 setlen | fs32 setlen |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < fs328Results.Length; i++)
        {
            Scalar8Scalar8DesignPerfResult ss88 = ss88Results[i];
            Scalar8Scalar8DesignPerfResult ss168 = ss168Results[i];
            Scalar8Scalar8DesignPerfResult fs328 = fs328Results[i];
            double fs32VsSs8Percent = ss88.MedianMilliseconds == 0 ? 0 : ((fs328.MedianMilliseconds - ss88.MedianMilliseconds) / ss88.MedianMilliseconds) * 100.0;
            double fs32VsSs16Percent = ss168.MedianMilliseconds == 0 ? 0 : ((fs328.MedianMilliseconds - ss168.MedianMilliseconds) / ss168.MedianMilliseconds) * 100.0;
            string ss88Spread = string.Create(CultureInfo.InvariantCulture, $"{ss88.MinMilliseconds:F4}/{ss88.MaxMilliseconds:F4}/{ss88.StandardDeviationMilliseconds:F4}");
            string ss168Spread = string.Create(CultureInfo.InvariantCulture, $"{ss168.MinMilliseconds:F4}/{ss168.MaxMilliseconds:F4}/{ss168.StandardDeviationMilliseconds:F4}");
            string fs328Spread = string.Create(CultureInfo.InvariantCulture, $"{fs328.MinMilliseconds:F4}/{fs328.MaxMilliseconds:F4}/{fs328.StandardDeviationMilliseconds:F4}");
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {fs328.Name} | {ss88.MedianMilliseconds:F4} | {ss168.MedianMilliseconds:F4} | {fs328.MedianMilliseconds:F4} | {fs32VsSs8Percent:F2} | {fs32VsSs16Percent:F2} | {ss88.AverageMilliseconds:F4} | {ss168.AverageMilliseconds:F4} | {fs328.AverageMilliseconds:F4} | {ss88Spread} | {ss168Spread} | {fs328Spread} | {ss88.AverageReadCalls:F2} | {ss168.AverageReadCalls:F2} | {fs328.AverageReadCalls:F2} | {ss88.AverageBytesRead:F0} | {ss168.AverageBytesRead:F0} | {fs328.AverageBytesRead:F0} | {ss88.AverageWriteCalls:F2} | {ss168.AverageWriteCalls:F2} | {fs328.AverageWriteCalls:F2} | {ss88.AverageBytesWritten:F0} | {ss168.AverageBytesWritten:F0} | {fs328.AverageBytesWritten:F0} | {ss88.AverageSetLengthCalls:F2} | {ss168.AverageSetLengthCalls:F2} | {fs328.AverageSetLengthCalls:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Notes");
        builder.AppendLine();
        builder.AppendLine("- FS32-8 quadruples key width versus SS8-8 while keeping scalar-8 identities; this report isolates the implemented fixed-32-key case.");
        builder.AppendLine("- Syscall and byte columns should stay shape-equivalent for matching structural mutations; elapsed drift primarily points at key comparison, tuple movement, route walking, and shelf CPU.");
        builder.AppendLine("- Split rows compare equivalent structural shapes rather than equal item counts because max items per 32 KiB shelf differ by tuple width.");

        return WriteReport(reportPath, builder);
    }


