    /// <summary>
    /// Writes the rotating public-wrapper routed `SS8-8` bulk-write report and archives the previous current report.<br/>
    /// The report focuses on developer-facing batch durability cadence rather than isolated shelf mutation cost.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="batches">The measured batch count per row.</param>
    /// <param name="warmupBatches">The warmup batch count per row.</param>
    /// <param name="itemsPerBatch">The logical items inserted per committed batch.</param>
    /// <param name="prefixCount">The number of root prefixes covered by each generated batch.</param>
    /// <param name="profile">The `SS8-8` shelf profile used by the public wrapper.</param>
    /// <param name="results">The measured routed bulk-write rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar8Scalar8RoutedBulkWriteReport(
        string artifactDirectory,
        int batches,
        int warmupBatches,
        int itemsPerBatch,
        int prefixCount,
        Scalar8Scalar8Profile profile,
        Scalar8Scalar8RoutedBulkWriteResult[] results)
    {
        string reportPath = PrepareCurrentReport(artifactDirectory, "ss8-8-routed-bulk-write-current.md", "ss8-8-routed-bulk-write");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Routed Bulk Write - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Batches per row: `{batches}`");
        builder.AppendLine($"- Warmup batches per row: `{warmupBatches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Shelf size: `{profile.ShelfExtentSize}` bytes");
        builder.AppendLine($"- Max items per shelf: `{profile.MaxItemCount}`");
        builder.AppendLine($"- Repeat samples per row: `{(results.Length == 0 ? 0 : results[0].SampleCount)}`");
        builder.AppendLine("- Rows use `LibraDex.Indexes.SS88.Create` and `Scalar8Scalar8Batch`.");
        builder.AppendLine("- Each measured batch commits once through the public batch API.");
        builder.AppendLine("- Key sets are identical between sorted and random rows; only insertion order changes.");
        builder.AppendLine($"- Raw commit baseline: `{FileReserveCommitBaselineMiBs:F2} MiB/s`");
        builder.AppendLine("- `raw commit %` is broad effective byte throughput vs raw file-reserve commit throughput; keep small structured-write baselines for fairness checks.");
        builder.AppendLine("- `items vs prev` and `bytes/item vs prev` compare against the prior 250-batch public-wrapper checkpoint.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | items/sec | items vs prev | us/item | batches/sec | commits | deferred/batch | writes/batch | bytes/batch | bytes/item | bytes/item vs prev | MiB/s | raw commit % | setLength | checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8RoutedBulkWriteResult result = results[i];
            double previousItemsPerSecond = GetPreviousPublicBulkWriteItemsPerSecond(result.Name);
            double rawCommitPercent = CalculateBaselinePercent(result.MiBs, FileReserveCommitBaselineMiBs);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SampleCount} | {result.ItemsPerSecond:F2} | {FormatPercentChange(result.ItemsPerSecond, previousItemsPerSecond)} | {result.MicrosecondsPerItem:F3} | {result.BatchesPerSecond:F2} | {result.CommitCount} | {result.DeferredCommitRequestsPerBatch:F3} | {result.WritesPerBatch:F3} | {result.BytesPerBatch:F2} | {result.BytesPerItem:F2} | {FormatPercentChange(result.BytesPerItem, PreviousPublicBulkWriteBytesPerItem)} | {result.MiBs:F2} | {FormatBaselinePercent(rawCommitPercent)} | {result.SetLengthCallCount} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Percent Summary");
        builder.AppendLine();
        builder.AppendLine("| scenario | raw commit % | items/sec vs previous | bytes/item vs previous |");
        builder.AppendLine("|---|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8RoutedBulkWriteResult result = results[i];
            double previousItemsPerSecond = GetPreviousPublicBulkWriteItemsPerSecond(result.Name);
            double rawCommitPercent = CalculateBaselinePercent(result.MiBs, FileReserveCommitBaselineMiBs);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {FormatBaselinePercent(rawCommitPercent)} | {FormatPercentChange(result.ItemsPerSecond, previousItemsPerSecond)} | {FormatPercentChange(result.BytesPerItem, PreviousPublicBulkWriteBytesPerItem)} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Remaining Gap Attribution");
        builder.AppendLine();
        builder.AppendLine("| scenario | routed items/sec | DK 16B stream % | raw same-byte ceiling items/sec | same-byte raw % | bytes/item over 16B payload | payload-only items/sec at current MiB/s |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8RoutedBulkWriteResult result = results[i];
            double dkStreamItemsPerSecond = GetDataKernel16ByteStreamItemsPerSecond(result.Name);
            double dkStreamPercent = dkStreamItemsPerSecond <= 0 ? 0 : result.ItemsPerSecond * 100d / dkStreamItemsPerSecond;
            double sameByteRawCeilingItemsPerSecond = result.BytesPerItem <= 0 ? 0 : FileReserveCommitBaselineMiBs * 1024d * 1024d / result.BytesPerItem;
            double sameByteRawPercent = sameByteRawCeilingItemsPerSecond <= 0 ? 0 : result.ItemsPerSecond * 100d / sameByteRawCeilingItemsPerSecond;
            double bytesOverPayload = result.BytesPerItem / LogicalScalar8Scalar8PayloadBytesPerItem;
            double payloadOnlyItemsPerSecondAtCurrentMiBs = result.MiBs * 1024d * 1024d / LogicalScalar8Scalar8PayloadBytesPerItem;
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.ItemsPerSecond:F2} | {dkStreamPercent:F2}% | {sameByteRawCeilingItemsPerSecond:F2} | {sameByteRawPercent:F2}% | {bytesOverPayload:F2}x | {payloadOnlyItemsPerSecondAtCurrentMiBs:F2} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- This is the current public encoded routed bulk-write probe through `Scalar8Scalar8Batch`.");
        builder.AppendLine("- `items/sec` and `us/item` are the headline metrics; byte throughput and write counts diagnose amplification.");
        builder.AppendLine("- The sorted/random gap should decide whether random slot maintenance is a real routed-workload hotspot.");
        builder.AppendLine("- `deferred/batch` shows how many lower-level commit requests the public batch folds into one durable publication.");
        builder.AppendLine("- After route-target caching, compare `MiB/s` and commit share against raw commit baselines to decide whether the next gap is write-byte pressure or remaining CPU.");
        builder.AppendLine("- If same-byte raw percent is high but DK 16B stream percent is low, the remaining gap is primarily bytes/item rather than commit throughput.");
        builder.AppendLine("- If same-byte raw percent is low, the next question is still CPU or write-call publication overhead for the current byte shape.");
        builder.AppendLine("- A negative `bytes/item vs prev` is desirable; a positive `items vs prev` is desirable.");

        return WriteReport(reportPath, builder);
    }


