        builder.AppendLine("- It is not yet an `SS8-8`-style public batch API result.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | samples | items/sec | us/item | batches/sec | commits | deferred/batch | writes/batch | bytes/batch | bytes/item | MiB/s | setLength | checksum |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8RoutedBulkWriteResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SampleCount} | {result.ItemsPerSecond:F2} | {result.MicrosecondsPerItem:F3} | {result.BatchesPerSecond:F2} | {result.CommitCount} | {result.DeferredCommitRequestsPerBatch:F3} | {result.WritesPerBatch:F3} | {result.BytesPerBatch:F2} | {result.BytesPerItem:F2} | {result.MiBs:F2} | {result.SetLengthCallCount} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Attribution");
        builder.AppendLine();
        builder.AppendLine("| scenario | root lookup ns/item | route cache hits | route cache misses | route walks | route walk ns/item | shelf insert ns/item | shelf cache hits | shelf cache misses | cached inserts | walked fallback | full fallback | no-split fallback | transform split fallback | parent-route split fallback | root route creates |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8RoutedBulkWriteResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.RootLookupNsPerItem:F2} | {result.RouteTargetCacheHitCount} | {result.RouteTargetCacheMissCount} | {result.RouteWalkCount} | {result.RouteWalkNsPerItem:F2} | {result.ShelfInsertNsPerItem:F2} | {result.ShelfCacheHitCount} | {result.ShelfCacheMissCount} | {result.CachedInsertCount} | {result.WalkedFallbackCount} | {result.CacheFullFallbackCount} | {result.NoSplitFallbackCount} | {result.TransformSplitFallbackCount} | {result.ParentRouteSplitFallbackCount} | {result.RootRouteCreateCount} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Publication Attribution");
        builder.AppendLine();
        builder.AppendLine("| scenario | full shelf stages | delta shelf stages | delta spans | delta changed bytes | delta bytes/item | post-coalesce bytes/item | post-coalesce writes/batch |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8RoutedBulkWriteResult result = results[i];
            double deltaBytesPerItem = result.ItemCount == 0 ? 0 : result.DeltaChangedBytes / (double)result.ItemCount;
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.FullShelfStageCount} | {result.DeltaShelfStageCount} | {result.DeltaChangedSpanCount} | {result.DeltaChangedBytes} | {deltaBytesPerItem:F2} | {result.BytesPerItem:F2} | {result.WritesPerBatch:F3} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Notes");
        builder.AppendLine();
        builder.AppendLine("- The SQLite `SS16-16` BLOB comparison uses the same generated high/low values and one transaction per logical batch.");
        builder.AppendLine("- Current LibraDex rows include repeated walked insert work, batch-local dirty shelf caching, and changed-region publication.");
        builder.AppendLine("- `Deferred/batch` reports lower-level commit requests folded into the session durability batch publication.");
        builder.AppendLine("- The command default uses the current empirical `SS16-16` routed bulk-write coalescing knee; pass `--commit-gap-coalesce-bytes` to sweep another value.");

        return WriteReport(reportPath, builder);
    }


