    /// <param name="rows">The measured cadence rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar8Scalar8RoutedCadenceSuiteReport(
        string artifactDirectory,
        int prefixCount,
        Scalar8Scalar8Profile profile,
        int repeatCount,
        int commitGapCoalesceBytes,
        IReadOnlyList<Scalar8Scalar8RoutedCadenceResult> rows)
    {
        string reportPath = PrepareCurrentReport(artifactDirectory, "ss8-8-routed-cadence-suite-current.md", "ss8-8-routed-cadence-suite");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# SS8-8 Routed Cadence Suite - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Shelf size: `{profile.ShelfExtentSize}` bytes");
        builder.AppendLine($"- Max items per shelf: `{profile.MaxItemCount}`");
        builder.AppendLine($"- Repeat samples per row: `{repeatCount}`");
        builder.AppendLine($"- Commit gap coalescing bytes: `{commitGapCoalesceBytes}`");
        builder.AppendLine("- Rows use `LibraDex.Indexes.SS88.Create` and `Scalar8Scalar8Batch`.");
        builder.AppendLine("- Cadences keep total measured inserts near one million while changing commit size.");
        builder.AppendLine($"- Raw commit baseline: `{FileReserveCommitBaselineMiBs:F2} MiB/s`");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| cadence | order | batches | warmup | items/batch | samples | items/sec | us/item | batches/sec | writes/batch | bytes/batch | bytes/item | MiB/s | raw commit % | setLength | checksum |");
        builder.AppendLine("|---|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < rows.Count; i++)
        {
            Scalar8Scalar8RoutedCadenceResult row = rows[i];
            Scalar8Scalar8RoutedBulkWriteResult result = row.Result;
            double rawCommitPercent = CalculateBaselinePercent(result.MiBs, FileReserveCommitBaselineMiBs);
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {row.CadenceName} | {row.OrderName} | {result.Batches} | {row.WarmupBatches} | {result.ItemsPerBatch} | {result.SampleCount} | {result.ItemsPerSecond:F2} | {result.MicrosecondsPerItem:F3} | {result.BatchesPerSecond:F2} | {result.WritesPerBatch:F3} | {result.BytesPerBatch:F2} | {result.BytesPerItem:F2} | {result.MiBs:F2} | {FormatBaselinePercent(rawCommitPercent)} | {result.SetLengthCallCount} | {result.Checksum} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Cadence Drift");
        builder.AppendLine();
        builder.AppendLine("| order | 1024 items/sec | 102 items/sec | 10 items/sec | 102 vs 1024 | 10 vs 1024 | 1024 B/item | 102 B/item | 10 B/item |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|");
        AppendScalar8Scalar8RoutedCadenceDrift(builder, rows, "sorted");
        AppendScalar8Scalar8RoutedCadenceDrift(builder, rows, "random");

        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- Use this report as the compact batch-size sensitivity check before making write-path policy changes.");
        builder.AppendLine("- A tiny-batch row that loses throughput while preserving the same bytes/item and writes/batch points to per-commit fixed overhead.");
        builder.AppendLine("- A tiny-batch row that inflates bytes/item or writes/batch points to publication shape rather than route or shelf CPU.");

        return WriteReport(reportPath, builder);
    }


