        builder.AppendLine("| metric | raw baseline distance | previous checkpoint distance |");
        builder.AppendLine("|---|---:|---:|");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| file bytes/item | {FormatPercentDistance(result.FileBytesPerItem, Scalar8Scalar8Layout.ItemSize)} | {FormatPercentChange(result.FileBytesPerItem, PreviousPublicGrowthFileBytesPerItem)} |");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| live bytes/item | {FormatPercentDistance(result.LiveBytesPerItem, Scalar8Scalar8Layout.ItemSize + Scalar8Scalar8Layout.SlotSize)} | {FormatPercentChange(result.LiveBytesPerItem, PreviousPublicGrowthLiveBytesPerItem)} |");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| overhead bytes/item | n/a | {FormatPercentChange(result.OverheadBytesPerItem, PreviousPublicGrowthOverheadBytesPerItem)} |");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| written bytes/item | n/a | {FormatPercentChange(result.WrittenBytesPerItem, PreviousPublicGrowthWrittenBytesPerItem)} |");
