    /// <summary>
    /// Writes the rotating multi-index same-identities sanity report and archives the previous current report.<br/>
    /// The report records the first structural proof that separate index-directory slots can host different shelf shapes over the same logical identities in one LibraDex file.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="path">The validated LibraDex file path.</param>
    /// <param name="batches">The generated batch count.</param>
    /// <param name="itemsPerBatch">The generated item count per batch.</param>
    /// <param name="prefixCount">The generated root-prefix count.</param>
    /// <param name="commitGapCoalesceBytes">The `DataKernel` commit gap coalescing setting.</param>
    /// <param name="result">The measured and validated sanity result.</param>
    /// <returns>The report path.</returns>
    private static string WriteMultiIndexSameIdentitiesSanityReport(
        string artifactDirectory,
        string path,
        int batches,
        int itemsPerBatch,
        int prefixCount,
        int commitGapCoalesceBytes,
        MultiIndexSameIdentitiesResult result)
    {
        string reportPath = PrepareCurrentReport(artifactDirectory, "multi-index-same-identities-sanity-current.md", "multi-index-same-identities-sanity");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# Multi-Index Same-Identities Sanity - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Path: `{Path.GetFullPath(path)}`");
        builder.AppendLine($"- Batches: `{batches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Commit gap coalescing bytes: `{commitGapCoalesceBytes}`");
        builder.AppendLine("- Slot `0` default shape: `SS8-8`, key equals identity.");
        builder.AppendLine("- Slot `1` default shape: `SS16-8`, key high equals identity and key low is deterministic.");
        builder.AppendLine("- Both indexes receive the same 8-byte identity set and are validated after reopening the file.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| index | slot | root offset | commits | writes | bytes | validated items | distinct shelves |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| SS8-8 | {result.Scalar8Scalar8SlotIndex} | {result.Scalar8Scalar8RootOffset} | {result.Scalar8Scalar8CommitCount} | {result.Scalar8Scalar8WriteCallCount} | {result.Scalar8Scalar8BytesWritten} | {result.Scalar8Scalar8ValidatedItems} | {result.Scalar8Scalar8DistinctShelves} |");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| SS16-8 | {result.Scalar16Scalar8SlotIndex} | {result.Scalar16Scalar8RootOffset} | {result.Scalar16Scalar8CommitCount} | {result.Scalar16Scalar8WriteCallCount} | {result.Scalar16Scalar8BytesWritten} | {result.Scalar16Scalar8ValidatedItems} | {result.Scalar16Scalar8DistinctShelves} |");
        builder.AppendLine();
        builder.AppendLine("## File Telemetry");
        builder.AppendLine();
        builder.AppendLine("| root create writes | root create bytes | setLength | identity checksum | final file bytes |");
        builder.AppendLine("|---:|---:|---:|---:|---:|");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.RootCreateWriteCallCount} | {result.RootCreateBytesWritten} | {result.SetLengthCallCount} | {result.IdentityChecksum} | {result.FinalFileBytes} |");
        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- The index-directory retained both active slots after reopen.");
        builder.AppendLine("- Root-router offsets are distinct, so the two indexes do not alias the same route graph.");
        builder.AppendLine("- Each generated identity was found through both shape-local route walkers after reopen.");
        builder.AppendLine("- This is a structural sanity proof, not a multi-index performance benchmark.");

        return WriteReport(reportPath, builder);
    }


