        int itemsPerBatch,
        int prefixCount,
        int commitGapCoalesceBytes,
        long rootCreateWrites,
        long rootCreateBytes,
        long identityChecksum,
        long finalFileBytes,
        ReadOnlySpan<MultiIndexSameIdentitiesPlan> plans)
    {
        string reportPath = PrepareCurrentReport(artifactDirectory, "multi-index-same-identities-sanity-current.md", "multi-index-same-identities-sanity");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# Multi-Index Same-Identities Sanity - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Path: `{Path.GetFullPath(path)}`");
        builder.AppendLine($"- Batches: `{batches}`");
        builder.AppendLine($"- Items per batch: `{itemsPerBatch}`");
        builder.AppendLine($"- Root prefixes per generated batch: `{prefixCount}`");
        builder.AppendLine($"- Commit gap coalescing bytes: `{commitGapCoalesceBytes}`");
        builder.AppendLine("- Total indexes: `8`");
        builder.AppendLine("- Shape instances: two each of `SS8-8`, `SS16-8`, `SS8-16`, and `SS16-16`.");
        builder.AppendLine("- Identity lanes: four indexes with 8-byte identities and four indexes with 16-byte identities.");
        builder.AppendLine("- Create slot order: `3, 0, 6, 1, 4, 7, 2, 5`.");
        builder.AppendLine("- Write slot order: `6, 0, 3, 5, 1, 7, 4, 2`.");
        builder.AppendLine("- Validate slot order after reopen: `5, 2, 7, 4, 1, 6, 0, 3`.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| slot | shape | identity B | root offset | commits | writes | bytes | validated items | distinct shelves |");
        builder.AppendLine("|---:|---|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < plans.Length; i++)
        {
            MultiIndexSameIdentitiesPlan plan = plans[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {plan.SlotIndex} | {FormatMultiIndexShape(plan.Shape)} | {plan.IdentityBytes} | {plan.RootOffset} | {plan.Telemetry.CommitCount} | {plan.Telemetry.WriteCallCount} | {plan.Telemetry.BytesWritten} | {plan.ValidatedItems} | {plan.DistinctShelves} |");
        }

        builder.AppendLine();
        builder.AppendLine("## File Telemetry");
        builder.AppendLine();
        builder.AppendLine("| root create writes | root create bytes | identity checksum | final file bytes |");
        builder.AppendLine("|---:|---:|---:|---:|");
        builder.AppendLine(CultureInfo.InvariantCulture, $"| {rootCreateWrites} | {rootCreateBytes} | {identityChecksum} | {finalFileBytes} |");
        builder.AppendLine();
        builder.AppendLine("## Interpretation");
        builder.AppendLine();
        builder.AppendLine("- The index-directory retained all eight active slots after reopen.");
        builder.AppendLine("- All eight root-router offsets are distinct.");
        builder.AppendLine("- Every generated identity was found through every shape-local route walker after reopen.");
        builder.AppendLine("- This remains structural sanity coverage, not a multi-index performance benchmark.");

        return WriteReport(reportPath, builder);
    }


    /// <summary>
    /// Formats a multi-index plan shape for console and markdown output.<br/>
    /// Keeping this in one helper prevents the enum names from leaking into artifacts.<br/>
    /// </summary>
    /// <param name="shape">The plan shape.</param>
    /// <returns>The display shape name.</returns>
    private static string FormatMultiIndexShape(MultiIndexSameIdentitiesShape shape)
    {
        return shape switch
        {
            MultiIndexSameIdentitiesShape.SS88 => "SS8-8",
            MultiIndexSameIdentitiesShape.SS168 => "SS16-8",
            MultiIndexSameIdentitiesShape.SS816 => "SS8-16",
            MultiIndexSameIdentitiesShape.SS1616 => "SS16-16",
            _ => throw new InvalidDataException($"Unknown multi-index shape {shape}.")
        };
    }


    /// <summary>
    /// Pre-creates the raw small-I/O baseline file with deterministic bytes before measured rows execute.<br/>
    /// Setup time is intentionally outside the baseline because the measured scenarios compare existing-page reads and rewrites.<br/>
    /// </summary>
    /// <param name="path">The file path to create.</param>
    /// <param name="regionStride">The byte stride between rotating regions.</param>
    /// <param name="regionCount">The number of rotating regions.</param>
    private static void PrepareSmallIoBaselineFile(string path, int regionStride, int regionCount)
    {
        File.Delete(path);
        byte[] chunk = CreatePattern(Math.Min(regionStride, 1024 * 1024), 113);
        long totalBytes = (long)regionStride * regionCount;
        long written = 0;
        using Microsoft.Win32.SafeHandles.SafeFileHandle handle = File.OpenHandle(
            path,
            FileMode.CreateNew,
            FileAccess.Write,
            FileShare.Read,
            FileOptions.RandomAccess);

        while (written < totalBytes)
        {
            int length = (int)Math.Min(chunk.Length, totalBytes - written);
            RandomAccess.Write(handle, chunk.AsSpan(0, length), written);
            written += length;
        }
    }


    /// <summary>
    /// Formats a raw-baseline percentage with a compact direction marker for markdown terminals that do not render color reliably.<br/>
    /// The marker is intentionally simple: up means at or above raw baseline, down means below raw baseline.<br/>
    /// </summary>
    /// <param name="percent">The percent-of-baseline value.</param>
    /// <returns>A markdown-safe percentage string.</returns>
    private static string FormatBaselinePercent(double percent)
    {
        string marker = percent >= 100d ? "up" : "down";
        return string.Create(CultureInfo.InvariantCulture, $"{percent:F2}% {marker}");
    }


    /// <summary>
    /// Formats the percentage change between a current metric and a previous checkpoint metric.<br/>
    /// The sign is preserved because the caller decides whether higher or lower is desirable for that metric.<br/>
    /// </summary>
    /// <param name="current">The current measured value.</param>
    /// <param name="previous">The previous checkpoint value.</param>
    /// <returns>A signed markdown-safe percentage string, or `n/a` when the checkpoint is not known.</returns>
    private static string FormatPercentChange(double current, double previous)
    {
        if (previous <= 0)
        {
            return "n/a";
        }

        double percent = (current - previous) * 100d / previous;
        return string.Create(CultureInfo.InvariantCulture, $"{percent:+0.00;-0.00;0.00}%");
    }


    /// <summary>
    /// Formats the percentage distance from a raw size baseline.<br/>
    /// Positive values mean the current size is above the raw byte floor.<br/>
    /// </summary>
    /// <param name="current">The current measured value.</param>
    /// <param name="baseline">The raw baseline value.</param>
    /// <returns>A signed markdown-safe percentage string, or `n/a` when the baseline is not known.</returns>
    private static string FormatPercentDistance(double current, double baseline)
    {
        if (baseline <= 0)
        {
            return "n/a";
        }

        double percent = (current - baseline) * 100d / baseline;
        return string.Create(CultureInfo.InvariantCulture, $"{percent:+0.00;-0.00;0.00}%");
    }


    /// <summary>
    /// Formats a direct throughput ratio as a compact multiplier.<br/>
    /// The numerator is usually LibraDex and the denominator is SQLite or raw `DataKernel`, making `1.00x` the parity point.<br/>
    /// </summary>
    /// <param name="numerator">The value in the numerator.</param>
    /// <param name="denominator">The value in the denominator.</param>
    /// <returns>A markdown-safe multiplier string, or `n/a` when the denominator is not known.</returns>
    private static string FormatMultiplier(double numerator, double denominator)
    {
        if (denominator <= 0)
        {
            return "n/a";
        }

        return string.Create(CultureInfo.InvariantCulture, $"{numerator / denominator:F2}x");
    }


    /// <summary>
    /// Creates a stable per-sample path for repeated benchmark runs.<br/>
    /// The first sample keeps the requested path so single-sample behavior remains unchanged.<br/>
    /// </summary>
    /// <param name="path">The caller-specified benchmark path.</param>
    /// <param name="sampleIndex">The zero-based sample index.</param>
    /// <returns>The path to use for the selected repeat sample.</returns>
    private static string CreateRepeatPath(string path, int sampleIndex)
    {
        if (sampleIndex == 0)
        {
            return path;
        }

        string? directory = Path.GetDirectoryName(path);
        string fileName = Path.GetFileNameWithoutExtension(path);
        string extension = Path.GetExtension(path);
        return Path.Combine(directory ?? string.Empty, string.Create(CultureInfo.InvariantCulture, $"{fileName}.r{sampleIndex + 1}{extension}"));
    }


    /// <summary>
    /// Returns the prior public bulk-write throughput checkpoint for a named routed bulk-write scenario.<br/>
    /// Unknown names return zero so report rows can still render as `n/a` during new experiment paths.<br/>
    /// </summary>
    /// <param name="name">The report scenario name.</param>
    /// <returns>The previous checkpoint items-per-second value, or zero when the scenario has no checkpoint.</returns>
    private static double GetPreviousPublicBulkWriteItemsPerSecond(string name)
    {
        return name switch
        {
            "public batch sorted" => PreviousPublicBulkWriteSortedItemsPerSecond,
            "public batch random" => PreviousPublicBulkWriteRandomItemsPerSecond,
            _ => 0d
        };
    }


    /// <summary>
    /// Returns the lower-structure 16-byte `DataKernel` stream item baseline for a named routed bulk-write scenario.<br/>
    /// The baseline keeps remaining write-gap reports anchored to logical payload throughput instead of only broad byte throughput.<br/>
    /// </summary>
    /// <param name="name">The routed write scenario name.</param>
    /// <returns>The matching 16-byte stream baseline in items per second, or zero when no baseline is known.</returns>
    private static double GetDataKernel16ByteStreamItemsPerSecond(string name)
    {
        return name switch
        {
            "public batch sorted" => DataKernel16ByteStreamSortedItemsPerSecond,
            "public batch random" => DataKernel16ByteStreamRandomItemsPerSecond,
            _ => 0d
        };
    }


    /// <summary>
    /// Returns the prior public bulk-read checkpoint for a named read scenario and requested metric.<br/>
    /// The same scenario mapping owns both throughput and latency baselines so report rows cannot drift between separate switches.<br/>
    /// </summary>
    /// <param name="name">The report scenario name.</param>
    /// <param name="nanoseconds">True to return nanoseconds per identity; false to return identities per second.</param>
    /// <returns>The requested previous checkpoint value, or zero when the scenario has no checkpoint.</returns>
    private static double GetPreviousPublicReadBaseline(string name, bool nanoseconds)
    {
        return name switch
        {
            "prefix 0 cached" => nanoseconds ? PreviousPublicReadPrefix0NsPerIdentity : PreviousPublicReadPrefix0IdentitiesPerSecond,
            "prefix middle cached" => nanoseconds ? PreviousPublicReadPrefixMiddleNsPerIdentity : PreviousPublicReadPrefixMiddleIdentitiesPerSecond,
            "prefix last cached" => nanoseconds ? PreviousPublicReadPrefixLastNsPerIdentity : PreviousPublicReadPrefixLastIdentitiesPerSecond,
            "prefix 0-2 cached" => nanoseconds ? PreviousPublicReadPrefix0To2NsPerIdentity : PreviousPublicReadPrefix0To2IdentitiesPerSecond,
            "prefix 0-2 coalesced" => nanoseconds ? PreviousPublicReadPrefix0To2CoalescedNsPerIdentity : PreviousPublicReadPrefix0To2CoalescedIdentitiesPerSecond,
            _ => 0d
        };
    }


    /// <summary>
    /// Returns the current encoded public-wrapper median throughput checkpoint for a typed routed bulk-write scenario.<br/>
    /// Unknown names return zero so new typed rows report `n/a` instead of borrowing an unrelated baseline.<br/>
    /// </summary>
    /// <param name="name">The typed report scenario name.</param>
    /// <returns>The encoded median items-per-second value, or zero when the scenario has no checkpoint.</returns>
    private static double GetEncodedMedianPublicBulkWriteItemsPerSecond(string name)
    {
        return name switch
        {
            "typed public batch sorted" => EncodedMedianPublicBulkWriteSortedItemsPerSecond,
            "sqlite batch sorted" => EncodedMedianPublicBulkWriteSortedItemsPerSecond,
            "typed public batch random" => EncodedMedianPublicBulkWriteRandomItemsPerSecond,
            "sqlite batch random" => EncodedMedianPublicBulkWriteRandomItemsPerSecond,
            _ => 0d
        };
    }


    /// <summary>
    /// Returns the encoded public-wrapper median read checkpoint for a typed or SQLite read scenario and requested metric.<br/>
    /// The shared mapping keeps paired throughput and latency baselines aligned for equivalent scenario aliases.<br/>
    /// </summary>
    /// <param name="name">The typed or SQLite report scenario name.</param>
    /// <param name="nanoseconds">True to return nanoseconds per identity; false to return identities per second.</param>
    /// <returns>The requested encoded median checkpoint value, or zero when the scenario has no checkpoint.</returns>
    private static double GetEncodedMedianPublicReadBaseline(string name, bool nanoseconds)
    {
        return name switch
        {
            "typed prefix 0 cached" or "sqlite prefix 0" => nanoseconds ? EncodedMedianPublicReadPrefix0NsPerIdentity : EncodedMedianPublicReadPrefix0IdentitiesPerSecond,
            "typed prefix middle cached" or "sqlite prefix middle" => nanoseconds ? EncodedMedianPublicReadPrefixMiddleNsPerIdentity : EncodedMedianPublicReadPrefixMiddleIdentitiesPerSecond,
            "typed prefix last cached" or "sqlite prefix last" => nanoseconds ? EncodedMedianPublicReadPrefixLastNsPerIdentity : EncodedMedianPublicReadPrefixLastIdentitiesPerSecond,
            "typed prefix 0-2 cached" or "sqlite prefix 0-2" => nanoseconds ? EncodedMedianPublicReadPrefix0To2NsPerIdentity : EncodedMedianPublicReadPrefix0To2IdentitiesPerSecond,
            "typed prefix 0-2 coalesced" or "sqlite prefix 0-2 repeated" => nanoseconds ? EncodedMedianPublicReadPrefix0To2CoalescedNsPerIdentity : EncodedMedianPublicReadPrefix0To2CoalescedIdentitiesPerSecond,
            _ => 0d
        };
    }


    /// <summary>
    /// Writes the rotating `SS8-8` growth/slack report and archives the previous current report.<br/>
    /// The report compares live file growth and immediate shelf occupancy after the validated routed split shapes.<br/>
    /// </summary>
    /// <param name="artifactDirectory">The artifact directory that receives the report.</param>
    /// <param name="profile">The `SS8-8` shelf profile used by the measured scenarios.</param>
    /// <param name="results">The measured growth/slack rows.</param>
    /// <returns>The report path.</returns>
    private static string WriteScalar8Scalar8GrowthSlackReport(
        string artifactDirectory,
        Scalar8Scalar8Profile profile,
        Scalar8Scalar8GrowthSlackResult[] results)
    {
        string reportPath = PrepareCurrentReport(artifactDirectory, "ss8-8-growth-slack-current.md", "ss8-8-growth-slack");

        string timestamp = DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
        StringBuilder builder = new();
        builder.AppendLine($"# LibraDex SS8-8 Growth Slack - {timestamp} UTC");
        builder.AppendLine();
        builder.AppendLine("## Scope");
        builder.AppendLine();
        builder.AppendLine($"- Shelf size: `{profile.ShelfExtentSize}` bytes");
        builder.AppendLine($"- Max items per shelf: `{profile.MaxItemCount}`");
        builder.AppendLine($"- Item+slot bytes per capacity unit: `{Scalar8Scalar8Layout.ItemSize + Scalar8Scalar8Layout.SlotSize}`");
        builder.AppendLine($"- Per-shelf unused tail bytes: `{profile.UnusedTailBytes}`");
        builder.AppendLine("- `extent slack` means file bytes not accounted for by known live metadata, routers, and shelves in this scenario.");
        builder.AppendLine("- For transform splits, extent slack is the unused remainder of the former 32 KiB shelf extent after a 4 KiB router is written at that offset.");
        builder.AppendLine("- `free bytes` means immediate unused shelf capacity after the split, not reclaimable file deadspace.");
        builder.AppendLine();
        builder.AppendLine("## Results");
        builder.AppendLine();
        builder.AppendLine("| scenario | setup | final | growth | live bytes | extent slack | routers | shelves | items | capacity | occ % | free slots | free bytes | router slack | writes | write bytes | setlen |");
        builder.AppendLine("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8GrowthSlackResult result = results[i];
            builder.AppendLine(CultureInfo.InvariantCulture, $"| {result.Name} | {result.SetupLength} | {result.FinalLength} | {result.GrowthBytes} | {result.LiveStructureBytes} | {result.ExtentSlackBytes} | {result.RouterCount} | {result.ShelfCount} | {result.ItemCount} | {result.ShelfCapacity} | {result.ShelfOccupancyPercent:F2} | {result.FreeItemSlots} | {result.ShelfFreeCapacityBytes} | {result.RouterReservedSlackBytes} | {result.WriteCalls} | {result.BytesWritten} | {result.SetLengthCalls} |");
        }

        builder.AppendLine();
        builder.AppendLine("## Notes");
        builder.AppendLine();
        builder.AppendLine("- Transform splits grow by two shelf extents because the old full shelf is reused as a router.");
        builder.AppendLine("- Root-prefix split grows by one shelf extent because the original shelf remains a shelf and only one new shelf is appended.");
        builder.AppendLine("- Immediate occupancy after balanced split is about 50%, which is useful mutation slack but can create file-size pressure under scattered inserts.");
        builder.AppendLine("- Router reserved slack is intentional 4 KiB router-page headroom, not a compaction candidate.");

        return WriteReport(reportPath, builder);
    }


