    /// <summary>
    /// Appends a markdown table for single-shelf `SS8-8` performance results.<br/>
    /// This is report formatting only and is intentionally not used in measured paths.<br/>
    /// </summary>
    /// <param name="builder">The report builder to append to.</param>
    /// <param name="results">The result rows to append.</param>
    private static void AppendScalar8Scalar8PerfTable(StringBuilder builder, Scalar8Scalar8PerfResult[] results)
    {
        builder.AppendLine("| Shelf bytes | Max items | Measured items | Fill % | Unused | Sorted insert ns | Reverse insert ns | Random insert ns | Lower-bound ns | Range ns | Range ns/id | Scoop ns | Scoop ns/id | Checksum |");
        builder.AppendLine("| ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8PerfResult result = results[i];
            builder.AppendLine($"| {result.ShelfSize} | {result.MaxItems} | {result.MeasuredItems} | {result.FillPercent:N2}% | {result.UnusedTailBytes} | {FormatStats(result.SortedInsertNs)} | {FormatStats(result.ReverseInsertNs)} | {FormatStats(result.RandomInsertNs)} | {FormatStats(result.LowerBoundNs)} | {FormatStats(result.RangeNs)} | {FormatStats(result.RangeNsPerIdentity)} | {FormatStats(result.ScoopNs)} | {FormatStats(result.ScoopNsPerIdentity)} | {result.Checksum} |");
        }
    }


    /// <summary>
    /// Appends a markdown table for multi-shelf `SS8-8` performance results.<br/>
    /// Multi-shelf rows make arena size and distributed lookup behavior explicit.<br/>
    /// </summary>
    /// <param name="builder">The report builder to append to.</param>
    /// <param name="results">The result rows to append.</param>
    private static void AppendScalar8Scalar8MultiShelfPerfTable(StringBuilder builder, Scalar8Scalar8MultiShelfPerfResult[] results)
    {
        builder.AppendLine("| Shelf bytes | Max items | Measured items/shelf | Shelf count | Arena bytes | Random insert ns | Lower-bound ns | Range ns/id | Scoop ns/id | Checksum |");
        builder.AppendLine("| ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |");
        for (int i = 0; i < results.Length; i++)
        {
            Scalar8Scalar8MultiShelfPerfResult result = results[i];
            builder.AppendLine($"| {result.ShelfSize} | {result.MaxItems} | {result.MeasuredItems} | {result.ShelfCount} | {result.ArenaBytes} | {FormatStats(result.RandomInsertNs)} | {FormatStats(result.LowerBoundNs)} | {FormatStats(result.RangeNsPerIdentity)} | {FormatStats(result.ScoopNsPerIdentity)} | {result.Checksum} |");
        }
    }


