    /// <summary>
    /// Validates `DataKernel.Commit` superseded-write elimination and adjacent write combining.<br/>
    /// Reservation reuse and direct memory writes are checked separately from genuine borrowed-segment overlap and phase ordering.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>Zero when file-backed and memory-backed commit coalescing behavior match expectations.</returns>
    private static int RunCommitCoalescingSanity(string[] args)
    {
        string path = Path.GetFullPath(GetOption(args, "--path", Path.Combine("artifacts", "commit-coalescing-" + Guid.NewGuid().ToString("N"), "mixed.lbdx")));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        var failures = new List<Exception>();
        var results = new List<CommitCoalescingSanityResult>();
        foreach (var backing in new[] { DataKernelBackingKind.File, DataKernelBackingKind.Memory })
        {
            try
            {
                var result = RunCommitCoalescingSanityCase(backing, path); results.Add(result);
                Console.WriteLine($"PASS mixed {backing} writes={result.WriteCallCount} backingWrites={result.BackingWriteCallCount} bytes={result.BytesWritten} checksum={result.Checksum}");
                if (backing == DataKernelBackingKind.File) File.Delete(path);
            }
            catch (Exception ex) { failures.Add(ex); Console.WriteLine($"FAIL mixed {backing}: {ex}"); }
        }
        if (results.Count == 2 && results[0].Checksum != results[1].Checksum)
            failures.Add(new InvalidDataException("File and memory logical results differ."));
        RunCommitCoalescingMatrix(Path.GetDirectoryName(path)!, failures);
        if (failures.Count != 0) throw new AggregateException("Commit coalescing validation failed.", failures);
        Console.WriteLine($"commit-coalescing-sanity ok path={path}");
        return 0;
    }


    /// <summary>
    /// Runs one raw `DataKernel` commit-coalescing scenario for the requested backing kind.<br/>
    /// The staged operations intentionally mix full cover, partial cover, append overwrite, and adjacent segments in one commit boundary.<br/>
    /// </summary>
    /// <param name="backing">The raw backing kind to validate.</param>
    /// <param name="path">The file path used by file-backed validation.</param>
    /// <returns>The commit shape and checksum for the validated backing kind.</returns>
    private static CommitCoalescingSanityResult RunCommitCoalescingSanityCase(DataKernelBackingKind backing, string path)
    {
        DataKernelOptions options = new(
            AppendBufferSize: 64,
            ReservedPrefixBytes: 0,
            FlushToDiskOnCommit: false,
            MaxCommitGapCoalesceBytes: 512);
        using DataKernel kernel = OpenKernel(backing, path, FileMode.CreateNew, options, DataKernelTelemetryOptions.EnabledOptions);

        RawDataReservation fullyCoveredOld = kernel.ReserveAt(4096, 16);
        FillPattern(fullyCoveredOld.Span, 11);
        RawDataReservation fullyCoveredNew = kernel.ReserveAt(4096, 16);
        FillPattern(fullyCoveredNew.Span, 12);

        RawDataReservation partialOld = kernel.ReserveAt(8192, 16);
        FillPattern(partialOld.Span, 21);
        RawDataReservation partialNew = kernel.ReserveAt(8200, 8);
        FillPattern(partialNew.Span, 22);

        RawDataReservation append = kernel.Reserve(32);
        FillPattern(append.Span, 31);
        RawDataReservation appendOverwrite = kernel.ReserveAt(append.Extent.Offset + 8, 16);
        FillPattern(appendOverwrite.Span, 32);

        RawDataReservation contiguousLeft = kernel.ReserveAt(12288, 16);
        FillPattern(contiguousLeft.Span, 41);
        RawDataReservation contiguousRight = kernel.ReserveAt(12304, 16);
        FillPattern(contiguousRight.Span, 42);

        RawDataReservation nearGapBase = kernel.ReserveAt(16384, 24);
        FillPattern(nearGapBase.Span, 50);
        RawDataReservation nearGapLeft = kernel.ReserveAt(16384, 8);
        FillPattern(nearGapLeft.Span, 51);
        RawDataReservation nearGapRight = kernel.ReserveAt(16400, 8);
        FillPattern(nearGapRight.Span, 52);

        DataKernelCommitTelemetry commit = kernel.Commit();
        long checksum = 0;
        checksum += ValidateKernelRange(kernel, 4096, CreatePattern(16, 12), "fully covered overwrite");

        byte[] partialExpected = CreatePattern(16, 21);
        CreatePattern(8, 22).CopyTo(partialExpected.AsSpan(8));
        checksum += ValidateKernelRange(kernel, 8192, partialExpected, "partial overlap");

        byte[] appendExpected = CreatePattern(32, 31);
        CreatePattern(16, 32).CopyTo(appendExpected.AsSpan(8));
        checksum += ValidateKernelRange(kernel, append.Extent.Offset, appendExpected, "append overwrite");

        byte[] contiguousExpected = new byte[32];
        CreatePattern(16, 41).CopyTo(contiguousExpected.AsSpan(0));
        CreatePattern(16, 42).CopyTo(contiguousExpected.AsSpan(16));
        checksum += ValidateKernelRange(kernel, 12288, contiguousExpected, "contiguous write combine");

        byte[] nearGapExpected = CreatePattern(24, 50);
        CreatePattern(8, 51).CopyTo(nearGapExpected.AsSpan(0));
        CreatePattern(8, 52).CopyTo(nearGapExpected.AsSpan(16));
        checksum += ValidateKernelRange(kernel, 16384, nearGapExpected, "contained reservation reuse");

        // File: 32 Payload bytes plus 104 Publication bytes in five groups. Memory: all eleven direct reservations.
        long expectedBytesWritten = backing == DataKernelBackingKind.File ? 136 : 176;
        long expectedBackingWrites = backing == DataKernelBackingKind.File ? 6 : 11;
        if (commit.BackingWriteCallCount != expectedBackingWrites || commit.BytesWritten != expectedBytesWritten ||
            commit.SetLengthCallCount != 0 || commit.WriteCallCount != (backing == DataKernelBackingKind.File ? expectedBackingWrites : 0))
            throw new InvalidDataException($"Unexpected mixed-reservation telemetry for {backing}: writes={commit.WriteCallCount}, backingWrites={commit.BackingWriteCallCount}, bytes={commit.BytesWritten}, setLength={commit.SetLengthCallCount}.");

        return new CommitCoalescingSanityResult(commit.WriteCallCount, commit.BackingWriteCallCount, commit.BytesWritten, checksum);
    }


    /// <summary>
    /// Reads and validates one raw `DataKernel` range against expected bytes.<br/>
    /// The returned checksum keeps file and memory backing parity visible without printing each byte span.<br/>
    /// </summary>
    /// <param name="kernel">The kernel to read.</param>
    /// <param name="offset">The raw offset to read.</param>
    /// <param name="expected">The expected byte image.</param>
    /// <param name="scenario">The validation scenario name used in failures.</param>
    /// <returns>A compact checksum over the validated bytes.</returns>
    private static long ValidateKernelRange(DataKernel kernel, long offset, ReadOnlySpan<byte> expected, string scenario)
    {
        byte[] actual = new byte[expected.Length];
        kernel.Read(offset, actual);
        if (!actual.AsSpan().SequenceEqual(expected))
        {
            throw new InvalidDataException($"Commit coalescing sanity failed for {scenario}.");
        }

        long checksum = 0;
        for (int i = 0; i < actual.Length; i++)
        {
            checksum += actual[i] * (i + 1L);
        }

        return checksum;
    }


    /// <summary>
    /// Gets the configured validation tier policy from a command-line tier name.<br/>
    /// Fast is intended for normal iteration, checkpoint for more serious drift checks, and baseline for intentional baseline refreshes.<br/>
    /// </summary>
    /// <param name="tier">The requested tier name.</param>
    /// <returns>The validation tier policy.</returns>
    private static ValidationTierOptions GetValidationTierOptions(string tier)
    {
        return tier switch
        {
            "baseline" => new ValidationTierOptions("baseline", 1024L * 1024 * 1024, ValidationBlockSize, ValidationAppendBufferSize, 10, 5000),
            "checkpoint" => new ValidationTierOptions("checkpoint", 1024L * 1024 * 1024, ValidationBlockSize, ValidationAppendBufferSize, 3, 1000),
            _ => new ValidationTierOptions("fast", 64L * 1024 * 1024, ValidationBlockSize, ValidationAppendBufferSize, 1, 100)
        };
    }


    /// <summary>
    /// Extracts the validation timestamp from a report heading.<br/>
    /// Expected heading shape is `# LibraDex Validation - tier - yyyyMMdd-HHmmss UTC`.<br/>
    /// </summary>
    /// <param name="content">The report content to inspect.</param>
    /// <returns>The extracted timestamp, or an empty string when no valid heading was found.</returns>
    private static string ExtractValidationTimestamp(string content)
    {
        using StringReader reader = new(content);
        string? line = reader.ReadLine();
        if (string.IsNullOrWhiteSpace(line))
        {
            return string.Empty;
        }

        const string marker = " - ";
        int markerIndex = line.LastIndexOf(marker, StringComparison.Ordinal);
        if (markerIndex < 0)
        {
            return string.Empty;
        }

        string timestampPart = line[(markerIndex + marker.Length)..].Trim();
        const string suffix = " UTC";
        if (!timestampPart.EndsWith(suffix, StringComparison.Ordinal))
        {
            return string.Empty;
        }

        string timestamp = timestampPart[..^suffix.Length];
        return DateTime.TryParseExact(
            timestamp,
            "yyyyMMdd-HHmmss",
            CultureInfo.InvariantCulture,
            DateTimeStyles.AssumeUniversal,
            out _)
            ? timestamp
            : string.Empty;
    }


    /// <summary>
    /// Formats validation drift with a markdown-safe direction cue for validation reports.<br/>
    /// Negative throughput drift means the current result is faster than baseline, while positive drift is slower.<br/>
    /// Shape metrics use pass/fail markers because their drift is exact-counter difference rather than performance direction.<br/>
    /// </summary>
    /// <param name="metric">The validation metric to format.</param>
    /// <returns>A markdown-safe drift value with direction text.</returns>
    private static string FormatDrift(ValidationMetric metric)
    {
        string text = metric.DriftPercent.ToString("N2", CultureInfo.InvariantCulture) + "%";
        if (metric.IsShapeMetric)
        {
            return metric.Status == ValidationStatus.Pass
                ? $"{text} [ok]"
                : $"{text} [shape drift]";
        }

        if (metric.DriftPercent < 0)
        {
            return $"{text} [up faster]";
        }

        if (metric.Status == ValidationStatus.Pass)
        {
            return $"{text} [ok slower]";
        }

        if (metric.Status == ValidationStatus.Warn)
        {
            return $"{text} [warn slower]";
        }

        return $"{text} [down slower]";
    }


