    private static RouteShapeResult RunRouteShapeCase(string name, RouterRouteSnapshot[] compressedRoutes, int iterations)
    {
        long[] expandedTargets = BuildExpandedTargets(compressedRoutes);
        byte[] compressedBytes = new byte[RouterLayout.Size];
        byte[] expandedBytes = new byte[RouterLayout.Size];

        RouterWriter compressedWriter = new(compressedBytes);
        compressedWriter.InitializeCompressed(1, 1, RouterLayout.MaxOneByteRouteCount, 1, compressedRoutes);

        RouterWriter expandedWriter = new(expandedBytes);
        expandedWriter.InitializeExpandedOneByte(1, 1, expandedTargets);

        bool equivalent = VerifyRouteEquivalence(compressedBytes, expandedBytes);
        RoutePerfResult compressedPerf = MeasureShapeRoutePerf(compressedBytes, iterations);
        RoutePerfResult expandedPerf = MeasureShapeRoutePerf(expandedBytes, iterations);

        int compressedBytesUsed = compressedRoutes.Length * RouterLayout.RouteSlotSize;
        int expandedBytesUsed = RouterLayout.MaxOneByteRouteCount * RouterLayout.RouteSlotSize;
        return new RouteShapeResult(
            name,
            equivalent,
            compressedRoutes.Length,
            compressedBytesUsed,
            expandedBytesUsed,
            expandedBytesUsed - compressedBytesUsed,
            compressedPerf,
            expandedPerf);
    }


    private static void AppendRoutePerf(StringBuilder builder, string scenario, RoutePerfResult result)
    {
        double seconds = Math.Max(result.Elapsed.TotalSeconds, 0.000001);
        double routesPerSecond = result.Iterations / seconds;
        double nsPerRoute = (seconds * 1_000_000_000d) / result.Iterations;
        builder.AppendLine($"| {scenario} | {result.Elapsed.TotalMilliseconds:N3} | {routesPerSecond:N2} | {nsPerRoute:N2} | {result.Checksum} |");
    }


