    private static Guid CreateStableGuid(int value)
    {
        Span<byte> bytes = stackalloc byte[16];
        BinaryPrimitives.WriteInt32BigEndian(bytes.Slice(12, sizeof(int)), value);
        return new Guid(bytes);
    }


    private static byte[] CreateBigIntVarIdentityBytes(int value)
    {
        return Encoding.UTF8.GetBytes(FormattableString.Invariant($"varid-{value:D6}"));
    }


    private static AppendMode GetAppendModeOption(string[] args)
    {
        string value = GetOption(args, "--append-mode", "append");
        return value.Equals("reserve", StringComparison.OrdinalIgnoreCase)
            ? AppendMode.Reserve
            : AppendMode.Append;
    }


    private static string GetOption(string[] args, string name, string defaultValue)
    {
        for (int i = 0; i < args.Length - 1; i++)
        {
            if (args[i].Equals(name, StringComparison.OrdinalIgnoreCase))
            {
                return args[i + 1];
            }
        }

        return defaultValue;
    }


    /// <summary>
    /// Checks whether a command-line option name was supplied.<br/>
    /// This distinguishes an omitted option from an option deliberately set to its default value, which matters for harness policies that can auto-select shape defaults from write intent.<br/>
    /// The helper treats option names case-insensitively and does not require the option to have a following value.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <param name="name">The option name to locate.</param>
    /// <returns>`true` when the option name appears in <paramref name="args"/>; otherwise `false`.</returns>
    private static bool HasOption(string[] args, string name)
    {
        for (int i = 0; i < args.Length; i++)
        {
            if (args[i].Equals(name, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }


    private static int GetIntOption(string[] args, string name, int defaultValue)
    {
        string value = GetOption(args, name, defaultValue.ToString());
        return int.Parse(value);
    }


    private static long GetLongOption(string[] args, string name, long defaultValue)
    {
        string value = GetOption(args, name, defaultValue.ToString());
        return long.Parse(value);
    }


    private static bool GetBoolOption(string[] args, string name, bool defaultValue)
    {
        string value = GetOption(args, name, defaultValue.ToString());
        return bool.Parse(value);
    }


    /// <summary>
    /// Reads the standard write-intent command-line option group.<br/>
    /// The group uses `--write-order`, `--write-volume`, `--write-locality`, and `--write-priority` so benchmark commands can exercise public developer intent without adding shape-specific flags.<br/>
    /// Missing options remain `Default`, preserving compatibility for existing harness invocations.<br/>
    /// </summary>
    /// <param name="args">The harness command-line arguments.</param>
    /// <returns>The parsed write-intent value.</returns>
    private static LibraDexWriteIntent GetWriteIntentOption(string[] args)
    {
        return new LibraDexWriteIntent(
            ParseWriteOrder(GetOption(args, "--write-order", LibraDexWriteOrder.Default.ToString())),
            ParseWriteVolume(GetOption(args, "--write-volume", LibraDexWriteVolume.Default.ToString())),
            ParseWriteLocality(GetOption(args, "--write-locality", LibraDexWriteLocality.Default.ToString())),
            ParseWritePriority(GetOption(args, "--write-priority", LibraDexWritePriority.Default.ToString())));
    }


    /// <summary>
    /// Parses a write-order option using tolerant names suitable for command-line use.<br/>
    /// Accepted values mirror `LibraDexWriteOrder` names while allowing case-insensitive input.<br/>
    /// </summary>
    /// <param name="value">The command-line value to parse.</param>
    /// <returns>The parsed write-order hint.</returns>
    private static LibraDexWriteOrder ParseWriteOrder(string value)
    {
        return value.Trim().ToLowerInvariant() switch
        {
            "default" => LibraDexWriteOrder.Default,
            "sorted" => LibraDexWriteOrder.Sorted,
            "random" => LibraDexWriteOrder.Random,
            _ => throw new ArgumentOutOfRangeException(nameof(value), value, "Write order must be default, sorted, or random.")
        };
    }


    /// <summary>
    /// Parses a write-volume option using tolerant names suitable for command-line use.<br/>
    /// Accepted values mirror `LibraDexWriteVolume` names while allowing case-insensitive input.<br/>
    /// </summary>
    /// <param name="value">The command-line value to parse.</param>
    /// <returns>The parsed write-volume hint.</returns>
    private static LibraDexWriteVolume ParseWriteVolume(string value)
    {
        return value.Trim().ToLowerInvariant() switch
        {
            "default" => LibraDexWriteVolume.Default,
            "small" => LibraDexWriteVolume.Small,
            "thousands" => LibraDexWriteVolume.Thousands,
            "millions" => LibraDexWriteVolume.Millions,
            _ => throw new ArgumentOutOfRangeException(nameof(value), value, "Write volume must be default, small, thousands, or millions.")
        };
    }


    /// <summary>
    /// Parses a write-locality option using tolerant names suitable for command-line use.<br/>
    /// Accepted values mirror `LibraDexWriteLocality` names while allowing case-insensitive input.<br/>
    /// </summary>
    /// <param name="value">The command-line value to parse.</param>
    /// <returns>The parsed write-locality hint.</returns>
    private static LibraDexWriteLocality ParseWriteLocality(string value)
    {
        return value.Trim().ToLowerInvariant() switch
        {
            "default" => LibraDexWriteLocality.Default,
            "clustered" => LibraDexWriteLocality.Clustered,
            "broad" => LibraDexWriteLocality.Broad,
            _ => throw new ArgumentOutOfRangeException(nameof(value), value, "Write locality must be default, clustered, or broad.")
        };
    }


    /// <summary>
    /// Parses a write-priority option using tolerant names suitable for command-line use.<br/>
    /// Accepted values mirror `LibraDexWritePriority` names while allowing case-insensitive input and a hyphenated write-speed alias.<br/>
    /// </summary>
    /// <param name="value">The command-line value to parse.</param>
    /// <returns>The parsed write-priority hint.</returns>
    private static LibraDexWritePriority ParseWritePriority(string value)
    {
        return value.Trim().ToLowerInvariant() switch
        {
            "default" => LibraDexWritePriority.Default,
            "balanced" => LibraDexWritePriority.Balanced,
            "writespeed" => LibraDexWritePriority.WriteSpeed,
            "write-speed" => LibraDexWritePriority.WriteSpeed,
            "compactness" => LibraDexWritePriority.Compactness,
            _ => throw new ArgumentOutOfRangeException(nameof(value), value, "Write priority must be default, balanced, write-speed, or compactness.")
        };
    }


    private static Scalar8Scalar8BulkWriteLocalityMode ParseScalar8Scalar8BulkWriteLocalityMode(string value)
    {
        return value.Trim().ToLowerInvariant() switch
        {
            "batch-major" => Scalar8Scalar8BulkWriteLocalityMode.BatchMajor,
            "batchmajor" => Scalar8Scalar8BulkWriteLocalityMode.BatchMajor,
            "prefix-major" => Scalar8Scalar8BulkWriteLocalityMode.PrefixMajor,
            "prefixmajor" => Scalar8Scalar8BulkWriteLocalityMode.PrefixMajor,
            _ => throw new ArgumentOutOfRangeException(nameof(value), value, "SS8-8 bulk write locality mode must be batch-major or prefix-major.")
        };
    }


    private static int[] ParseIntList(string value)
    {
        string[] parts = value.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        int[] result = new int[parts.Length];
        for (int i = 0; i < parts.Length; i++)
        {
            result[i] = int.Parse(parts[i]);
        }

        return result;
    }


    private static int PrintUsage(string command)
    {
        Console.Error.WriteLine($"Unknown command '{command}'.");
        Console.Error.WriteLine("Usage:");
        Console.Error.WriteLine("  dotnet run --project LibraDex.Harness -c Debug -- sanity-raw --backing file");
        Console.Error.WriteLine("  dotnet run --project LibraDex.Harness -c Debug -- sanity-raw --backing memory");
        Console.Error.WriteLine("  dotnet run --project LibraDex.Harness -c Debug -- commit-coalescing-sanity --path T:\\LibraDex\\commit-coalescing-sanity.lbdx");
        Console.Error.WriteLine("  dotnet run --project LibraDex.Harness -c Debug -- sanity-format --path T:\\LibraDex\\format-sanity.lbdx");
        Console.Error.WriteLine("  dotnet run --project LibraDex.Harness -c Release -- stress-format --directory T:\\LibraDex\\FormatStress --iterations 1000");
